window.POEM_DB=window.POEM_DB||{};POEM_DB["song_007"]={"n":"方回","dyn":"宋","poems":[{"t":"丁桥晓行","f":"七言绝句","c":["苕水无声镜面光，渔家孤艇泊中央。","十幅生绡谁画得，一轮斜月一篷霜。"]},{"t":"七十翁吟七言十绝 其二","f":"七言绝句","c":["顿尔缪为象山学，雕吾痛绝水心文。","潜夫诗格温夫字，掩耳平生不愿闻。"]},{"t":"七十翁吟七言十绝 其七","f":"七言绝句","c":["脍炙鲸鹏吾不佞，撮扪蚤虱尔徒劳。","泰山夜半见红日，政要人生著脚高。"]},{"t":"七十翁吟七言十绝 其八","f":"七言绝句","c":["后山卒仅四十九，讳日崇宁一日前。","当时假使馀七帙，忍见中原丙午年。"]},{"t":"七十翁吟七言十绝 其四","f":"七言绝句","c":["郑玄三礼王弼易，亦绘冕旒配孔庭。","虚耗中原实卫霍，麒麟阁上也图形。"]},{"t":"七十翁吟七言十绝 其一","f":"七言绝句","c":["自知酒量防踰矩，敢诧诗才妙斲轮。","古圣贤心得丝许，虽非尼扁异愚民。"]},{"t":"七十翁吟七言十绝 其十","f":"七言绝句","c":["少陵诗诧古来希，老病馀生曷不归。","不信神仙不信佛，死时惟裹破深衣。"]},{"t":"七十翁吟七言十绝 其九","f":"七言绝句","c":["周家八百年天下，文武焉知有赧王。","老寿彭公亦馀骨，始知生死是兴亡。"]},{"t":"七十翁吟七言十绝 其六","f":"七言绝句","c":["恨予生不及晦翁，撰杖鹅湖观异同。","岂减游杨侍程子，未甘籍湜事韩公。"]},{"t":"二月十五日赵君实南山别墅俟主客俱不至","f":"七言绝句","c":["篱落梅残野菜青，田间閒看鹤梳翎。","主人不到客且去，细雨南山暗画屏。"]},{"t":"二月朔大雪已五日三首 其三","f":"七言绝句","c":["牛马毛寒缩如猬，古今此句绝奇奇。","今春大雪亦将尔，莺死无声社燕迟。"]},{"t":"二月朔大雪已五日三首 其二","f":"七言绝句","c":["燕山雪花大如席，岂料江南亦见之。","腊前六出知焉往，却在春风二月时。"]},{"t":"二月朔大雪已五日三首 其一","f":"七言绝句","c":["侵寻半月是花朝，大雪漫天五日飘。","腊月如春众芳吐，繁华时节却萧条。"]},{"t":"八月十二日过湖","f":"七言绝句","c":["荷已无花柳欲陈，秋风飒飒水粼粼。","湖山惨淡西施老，细看终于胜丑人。"]},{"t":"十七日大雪","f":"七言绝句","c":["扁舟未觉出城难，访旧情知老畏寒。","七十五翁无□□，□楼聊且隔帘看。"]},{"t":"十六日大雪","f":"七言绝句","c":["长至前踰一月晴，忽然细细雨无声。","中宵变作今□□，□得楼头鼓角清。"]},{"t":"十四日至节","f":"七言绝句","c":["钱塘多少富豪家，酒肉如山赏物华。","野老入城□□□，□萝卜菜腊梅花。"]},{"t":"又题画赤脚仙","f":"七言绝句","c":["万古天冠地屦身，画师游戏恐非真。","父生师教成何事，甘作蓬头跣足人。"]},{"t":"三天竺还五首 其五","f":"七言绝句","c":["七十二翁头雪白，弱冠初游鬓如漆。","除却一二老山僧，独来独往无人识。"]},{"t":"三天竺还五首 其四","f":"七言绝句","c":["山中事事胜人间，莫怪山翁喜入山。","才说出山心不喜，又将身世堕尘寰。"]},{"t":"三天竺还五首 其三","f":"七言绝句","c":["涧晴石出水穿沙，万树松杉隐数家。","一鸟不鸣风不动，忽闻林下响缫车。"]},{"t":"三天竺还五首 其二","f":"七言绝句","c":["松枝垂地荫松身，恨不移家此卜邻。","石上一根长数丈，似吾细看更无人。"]},{"t":"三天竺还五首 其一","f":"七言绝句","c":["城中决定少新诗，便向湖光也未宜。","我有新诗无数处，三天竺路笋舆迟。"]},{"t":"三天竺道中","f":"七言绝句","c":["三天竺路渐平登，高似雷峰塔几层。","山到无人行处好，松阴万树立孤僧。"]},{"t":"三月三日西湖第三桥四首 其四","f":"七言绝句","c":["野蔌随宜酒半醺，富儿盘馔拥红裙。","兰亭会上无丝竹，芥蒂区区笑右军。"]},{"t":"三月三日西湖第三桥四首 其三","f":"七言绝句","c":["尽道西湖久寂寥，红栏干落但空桥。","细思未有苏堤日，且把閒愁著酒浇。"]},{"t":"三月三日西湖第三桥四首 其二","f":"七言绝句","c":["正月桥西卖酒家，柳初青眼草初芽。","重来红紫随风雨，犹有野田黄菜花。"]},{"t":"三月三日西湖第三桥四首 其一","f":"七言绝句","c":["北曲南歌日日新，红妆不逐落红春。","网鱼野老何曾觑，岂是心肠木石人。"]},{"t":"三竺道中三首 其三","f":"七言绝句","c":["石溪清浅不容舟，但有常常绿水流。","莫道江湖风浪阔，此中涓滴是源头。"]},{"t":"三竺道中三首 其二","f":"七言绝句","c":["少人行处路方佳，半著僧鞋半草鞋。","直到全无马粪处，山僮竹帚扫松钗。"]},{"t":"三竺道中三首 其一","f":"七言绝句","c":["武林风物异他乡，三竺山行草亦香。","村落寻常绩麻处，隔帘时复见红妆。"]},{"t":"三贤堂已无官卖其址","f":"七言绝句","c":["三贤无像亦无堂，败柳犹垂赤土墙。","官卖神祠有前例，熙宁丞相起坊场。"]},{"t":"三贤堂移入西湖新书院","f":"七言绝句","c":["湖边莫怪旧祠荒，士女何曾炷瓣香。","赖是人心犹未泯，深衣迎奉入书堂。"]},{"t":"上元再题","f":"七言绝句","c":["梅残万点路傍雪，桃露一班梢上红。","惆怅六鳌山已去，了无情绪答春风。"]},{"t":"下营晓行二首 其二","f":"七言绝句","c":["月淡云浓弄晓晴，草中白处路微明。","垂鞭缓辔十馀里，始听鸣鸡第一声。"]},{"t":"下营晓行二首 其一","f":"七言绝句","c":["霜锲驼裘耳欲冰，谁家先我已宵兴。","道傍篱落遮丛筱，隔火荧荧见一灯。"]},{"t":"久过重阳菊英粲然即事十首 其十","f":"七言绝句","c":["江南菊花差晚开，把酒前兰复后梅。","天公何尝负此老，天下腐儒臣方回。"]},{"t":"久过重阳菊英粲然即事十首 其九","f":"七言绝句","c":["有酒泛菊釂美酒，无酒嗅菊倚阑干。","时人谁会先生意，常把霜枝子细看。"]},{"t":"久过重阳菊英粲然即事十首 其八","f":"七言绝句","c":["把之手香嚼齿香，饫之燕之香肺肠。","金英满泛日百盏，何必帝乡姑醉乡。"]},{"t":"久过重阳菊英粲然即事十首 其七","f":"七言绝句","c":["风霜无畏最耐久，粪壤不资真自然。","正则夕餐骨已换，凌江端作跨鳌仙。"]},{"t":"久过重阳菊英粲然即事十首 其六","f":"七言绝句","c":["菊芳兰秀幸同时，汾水刘郎语最悲。","谁果肖兰谁肖菊，未知黄落又为谁。"]},{"t":"久过重阳菊英粲然即事十首 其五","f":"七言绝句","c":["平生我解量人品，元亮真成晋伯夷。","我欲招魂无别物，剩将酒洒菊花枝。"]},{"t":"久过重阳菊英粲然即事十首 其四","f":"七言绝句","c":["紫阳山下园五亩，一半教儿种菊花。","霜渐浓时花更好，六年何事未还家。"]},{"t":"久过重阳菊英粲然即事十首 其三","f":"七言绝句","c":["倏过重阳几一月，菊花更觉有精神。","必重阳日始赏菊，此是人间最俗人。"]},{"t":"久过重阳菊英粲然即事十首 其二","f":"七言绝句","c":["种就株株攒万蕊，摘多干干茁三桠。","此诗两句烦君听，不是閒花是菊花。"]},{"t":"久过重阳菊英粲然即事十首 其一","f":"七言绝句","c":["早伴茱萸插帽纱，尚堪荐酒更堪茶。","花边行立花边坐，不是閒花是菊花。"]},{"t":"大衍易吟四十首 其四十","f":"五言绝句","c":["凶人凶其吉，吉人吉其凶。","曳轮能自信，揲策勿求通。"]},{"t":"大衍易吟四十首 其三十九","f":"五言绝句","c":["全卦定凶吉，逐爻殊否臧。","顷刻有变易，纵横无典常。"]},{"t":"大衍易吟四十首 其三十八","f":"五言绝句","c":["易乃一量秤，铢铢分重轻。","百千亿万事，义理是权衡。"]},{"t":"大衍易吟四十首 其三十七","f":"五言绝句","c":["屡厄未济旅，难逢既济丰。","巽谦能自降，蹇困讵为穷。"]},{"t":"大衍易吟四十首 其三十六","f":"五言绝句","c":["震动对艮止，革故继鼎新。","饮啐随时义，天机信屈伸。"]},{"t":"大衍易吟四十首 其三十五","f":"五言绝句","c":["原筮而后比，无疑方可升。","不食匪井患，有言奚困亨。"]},{"t":"大衍易吟四十首 其三十四","f":"五言绝句","c":["六籍火未熄，龙兴芒砀云。","呼韩朝渭上，已纳王政君。"]},{"t":"大衍易吟四十首 其三十三","f":"五言绝句","c":["五王复唐祚，不杀武三思。","苋陆察爻义，惜哉张柬之。"]},{"t":"大衍易吟四十首 其三十二","f":"五言绝句","c":["损其不善者，惟善则益之。","自然获天祐，可受十朋龟。"]},{"t":"大衍易吟四十首 其三十一","f":"五言绝句","c":["在险惟反己，出险即及人。","让夷急病者，蹇解二忠臣。"]},{"t":"大衍易吟四十首 其三十","f":"五言绝句","c":["一女卦反对，不同而后同。","始知天下事，苟合最为凶。"]},{"t":"大衍易吟四十首 其二十九","f":"五言绝句","c":["夜闇勿遽戚，昼光无疾行。","自昭惟进德，用晦岂伤明。"]},{"t":"大衍易吟四十首 其二十八","f":"五言绝句","c":["姤阴进不已，吾遁其奚言。","阳壮过于泰，□虞羝触藩。"]},{"t":"大衍易吟四十首 其二十七","f":"五言绝句","c":["咸取男下女，恒言妇事夫。","始感终当□，君臣其谨诸。"]},{"t":"大衍易吟四十首 其二十六","f":"五言绝句","c":["习坎德天险，重离文日新。","明内始照外，亨心方发身。"]},{"t":"大衍易吟四十首 其二十五","f":"五言绝句","c":["大过本末弱，厄运逢瞒奴。","文举有死耳，渊明其归乎。"]},{"t":"大衍易吟四十首 其二十四","f":"五言绝句","c":["艮上戒舌驷，震初羞指鼋。","细观颐内外，口是祸之门。"]},{"t":"大衍易吟四十首 其二十三","f":"五言绝句","c":["无妄均所与，大畜患不多。","性岂无知者，心如未尽何。"]},{"t":"大衍易吟四十首 其二十二","f":"五言绝句","c":["午月至子复，书云七日来。","六日七分说，观天何隘哉。"]},{"t":"大衍易吟四十首 其二十一","f":"五言绝句","c":["仁道成已极，体元乾长人。","独休不远复，当且学回仁。"]},{"t":"大衍易吟四十首 其二十","f":"五言绝句","c":["剥三与复四，皆处五阴中。","自拔弃其类，吾推道是从。"]},{"t":"大衍易吟四十首 其十九","f":"五言绝句","c":["离明用狱四，噬嗑贲旅丰。","中孚夹离卦，两画玩虚中。"]},{"t":"大衍易吟四十首 其十八","f":"五言绝句","c":["俯下知临吉，其如仰观何。","相孚不待荐，一盥已为多。"]},{"t":"大衍易吟四十首 其十七","f":"五言绝句","c":["泰变即为蛊，否变仅为随。","元祐绍圣事，至今心骨悲。"]},{"t":"大衍易吟四十首 其十六","f":"五言绝句","c":["谦卑六位得，豫乐四爻非。","庄敬与安肆，冥冥祸福几。"]},{"t":"大衍易吟四十首 其十五","f":"五言绝句","c":["大有同人盛，离柔寓戒辞。","无威斯近弱，不广即为私。"]},{"t":"大衍易吟四十首 其十四","f":"五言绝句","c":["盛夏靡草死，岁寒松柏贞。","泰须防陂复，否有大人亨。"]},{"t":"大衍易吟四十首 其十三","f":"五言绝句","c":["履若蹈虎尾，五刚亨厥躬。","乾三独柔变，是以咥人凶。"]},{"t":"大衍易吟四十首 其十二","f":"五言绝句","c":["小畜过无坎，胡为以雨云。","互观藏兑泽，止水亦兴云。"]},{"t":"大衍易吟四十首 其十一","f":"五言绝句","c":["讼吉观西伯，师中验太公。","得人师不战，反己讼无终。"]},{"t":"大衍易吟四十首 其十","f":"五言绝句","c":["德盛时逢险，乾刚坎在前。","谚云姑少待，乐饮岂徒然。"]},{"t":"大衍易吟四十首 其九","f":"五言绝句","c":["屯初康险难，蒙上觉昏童。","开辟乾坤后，君师大有功。"]},{"t":"大衍易吟四十首 其八","f":"五言绝句","c":["十年女乃字，守节以胜情。","凡诸卦用六，观兹利永贞。"]},{"t":"大衍易吟四十首 其七","f":"五言绝句","c":["用九不为首，阳画位屯初。","百八十五变，刚爻可舍诸。"]},{"t":"大衍易吟四十首 其六","f":"五言绝句","c":["六阴升已极，坤下战乎乾。","建亥阳生处，居然复卦前。"]},{"t":"大衍易吟四十首 其五","f":"五言绝句","c":["阳爻极六位，进退贵因时。","德则何忧亢，神而不可知。"]},{"t":"大衍易吟四十首 其四","f":"五言绝句","c":["乾坤用九六，义例析为三。","朱子申欧说，开编请细探。"]},{"t":"大衍易吟四十首 其三","f":"五言绝句","c":["谓今三画卦，不自偶奇生。","便指三为八，徒劳口舌争。"]},{"t":"大衍易吟四十首 其二","f":"五言绝句","c":["太极元无极，先天异后天。","今人不识此，读易岂其然。"]},{"t":"大衍易吟四十首 其一","f":"五言绝句","c":["卦下观一彖，卦中求六爻。","今人仅知此，著眼未为高。"]},{"t":"小本兰亭二种","f":"七言绝句","c":["子云可拟易论无，颇似兰亭细字模。","始信圣经非小艺，不羞依样画葫芦。"]},{"t":"山茶花","f":"七言绝句","c":["石楠岩桂万年枝，方驾分花占四时。","犀甲鹤头傲霜雪，入春犹见岁寒姿。"]},{"t":"中秋雨","f":"七言绝句","c":["瘴疠干戈脱此生，一隅略见旧承平。","上元灯火中秋月，但苦人心不肯晴。"]},{"t":"中秋前夕三首 其三","f":"七言绝句","c":["山头月到天心小，林下秋生夜半寒。","不待明朝已三五，四更仍续五更看。"]},{"t":"中秋前夕三首 其二","f":"七言绝句","c":["稍穿疏树残光碎，徐碾晴空素艳流。","交过子时是明日，搀先半夜赏中秋。"]},{"t":"中秋前夕三首 其一","f":"七言绝句","c":["中秋无酒定醒然，清赏今宵月已圆。","喜我小儿才五岁，犹能倚户望高天。"]},{"t":"中望吴山下一汀是为杭州","f":"七言绝句","c":["秦皇系缆北山头，一抹江边海变洲。","百万生人无葬处，蜗争蚁战不如休。"]},{"t":"为孙同签瓒题赵子昂马","f":"七言绝句","c":["画马当年李伯时，长怀鲁直子瞻诗。","朝廷□道人才盛，元祐风流再见之。"]},{"t":"为牟德范题石湖遗墨意有未尽复赋五首 其五","f":"七言绝句","c":["日长饥雀窥铛釜，雨过跳蛙上灶炉。","莫笑晒书亡玉轴，荆州还识半人无。"]},{"t":"为牟德范题石湖遗墨意有未尽复赋五首 其四","f":"七言绝句","c":["传道府中浇茗碗，灵坚陇畔炷薰炉。","银钩茧纸闲舒卷，锥也无时未是无。"]},{"t":"为牟德范题石湖遗墨意有未尽复赋五首 其三","f":"七言绝句","c":["不寻蓬岛求仙药，肯羡铜山侈赐炉。","独有平生嗜古癖，谁知东郭履全无。"]},{"t":"为牟德范题石湖遗墨意有未尽复赋五首 其二","f":"七言绝句","c":["汉陵往事馀金碗，湘步空名尚铁炉。","地下中郎今不作，典刑真属虎贲无。"]},{"t":"为牟德范题石湖遗墨意有未尽复赋五首 其一","f":"七言绝句","c":["青春日月羁尘鞅，朱夏乾坤炽暑炉。","略对风檐紬古卷，閒愁吹得一星无。"]},{"t":"为吴太初题初邻斋二首 其二","f":"七言绝句","c":["三两茅庐一径深，略知住处未知心。","元来有物先天地，难向君家屋畔寻。"]},{"t":"为吴太初题初邻斋二首 其一","f":"七言绝句","c":["此宅元无一物遮，问君隔壁是谁家。","伏羲未画前头事，篱落傍边靠得些。"]},{"t":"为徐企题李伯时马","f":"七言绝句","c":["此画良真李伯时，形容飞动卒难诗。","但将元祐苏黄作，开卷焚香朗诵之。"]},{"t":"为魏塘王居士留三日二首 其二","f":"七言绝句","c":["魏塘酒贱蟹螯肥，久要人情忍重违。","呼妓访僧俱不必，醉三昼夜可言归。"]},{"t":"为魏塘王居士留三日二首 其一","f":"七言绝句","c":["水乡熟处未全饥，舟楫安行盗亦稀。","乘兴聊为三日客，魏塘酒贱蟹螯肥。"]},{"t":"予丁亥生壬寅年七十六留杭十二年","f":"七言绝句","c":["吾生已是三分过，此地胡为一纪留。","万事无心偶然耳，久将身世付浮休。"]},{"t":"五月二夜闻雨大□□日至杭","f":"七言绝句","c":["□凉唤起酒醒人，听雨更阑得句新。","儿子远来作生□，□□□十六年身。"]},{"t":"今春苦雨初有春半曾无十日晴之句去立夏无几日愈雨足成五诗 其一","f":"七言绝句","c":["小楼欲下怕泥行，春半曾无十日晴。","老眼看花如隔雾，只消卧听卖花声。"]},{"t":"今春苦雨初有春半曾无十日晴之句去立夏无几日愈雨足成五诗 其三","f":"七言绝句","c":["青梅未了已朱樱，春尽曾无十日晴。","稍欲出城问蚕麦，生愁城外杜鹃声。"]},{"t":"今春苦雨初有春半曾无十日晴之句去立夏无几日愈雨足成五诗 其四","f":"七言绝句","c":["湖头准拟赏新晴，雨过风号万马声。","宋玉未誇巫峡梦，杜陵翻作渼陂行。"]},{"t":"今春苦雨初有春半曾无十日晴之句去立夏无几日愈雨足成五诗 其二","f":"七言绝句","c":["今年草草过清明，春莫曾无十日晴。","担上牡丹犹许见，城中浑不识莺声。"]},{"t":"今春苦雨初有春半曾无十日晴之句去立夏无几日愈雨足成五诗 其五","f":"七言绝句","c":["读书听雨过三更，定是明朝又不晴。","就枕未鼾饥鼠出，掀书舐砚上灯檠。"]},{"t":"元夕前雨不已二首 其二","f":"七言绝句","c":["兰膏画炬出贫民，宝马香车属贵人。","月姊雨师暗商榷，不须妆点上元春。"]},{"t":"元夕前雨不已二首 其一","f":"词","c":["节届烧灯奈若何，客楼三夜听霶?。","春风有意催花信，小雨如酥不用多。"]},{"t":"午节","f":"七言绝句","c":["年年节与物相符，笋已成竿燕欲雏。","客里不知端午近，卖花担上见菖蒲。"]},{"t":"月月红花","f":"七言绝句","c":["十二循环换律筒，芳葩长是笑春风。","山家不识尧蓂荚，日历聊凭月月红。"]},{"t":"木香花","f":"词","c":["海南药物木香重，何似?松高架花。","春晚日长香满院，天教富贵属诗家。"]},{"t":"水仙花画","f":"七言绝句","c":["□绘水仙陪鲁直，梅边更有子瞻形。","苏兄黄弟神游处，重筑人间顿有亭。"]},{"t":"王干三岭","f":"七言绝句","c":["澄练平皋水屈盘，青苍松栎拥峰峦。","霜晴村落全如画，一见都忘上岭难。"]},{"t":"见梅","f":"七言绝句","c":["翠竹阴森护槿篱，玉梅庭院粉墙攲。","几年避地无人住，犹有花开一两枝。"]},{"t":"丙申元日五绝 其二","f":"七言绝句","c":["五更春雨细无声，石路溅泥齿屐鸣。","后饮屠苏懒奔走，可能也喜鹁鸠晴。"]},{"t":"丙申元日五绝 其五","f":"七言绝句","c":["案上瓶梅阅两年，添花未有买花钱。","东风恰似怜穷客，吹到新诗四五篇。"]},{"t":"丙申元日五绝 其一","f":"七言绝句","c":["新年仍著旧年衣，老健深惭七十希。","一炷炉香拜天地，今春早早买船归。"]},{"t":"丙申元日五绝 其三","f":"七言绝句","c":["雪馀连雨满城泥，喝道宵行万马蹄。","昨夜隔年书未点，瓶梅灯畔一枝低。"]},{"t":"丙申元日五绝 其四","f":"七言绝句","c":["送寒迎暖柳梢知，风自东来著意吹。","百万人家贺新岁，几家荼垒有新诗。"]},{"t":"东坡真迹","f":"七言绝句","c":["欧苏一代两文忠，赖是滁阳起醉翁。","谁欲儋州杀坡老，靖康战血鼓腥风。"]},{"t":"兰花","f":"七言绝句","c":["雪尽深林出异芬，枯松槁槲乱纷纷。","此中恐是兰花处，未许行人著意闻。"]},{"t":"兰亭","f":"七言绝句","c":["细看僧字永和碑，谁见山阴落笔时。","想像捧心□□□，□间几本话西施。"]},{"t":"出城","f":"五言绝句","c":["久病欣初愈，长忙爱暂閒。","出城因送客，沿路得看山。"]},{"t":"北本兰亭","f":"七言绝句","c":["一千年想永和会，十九之传贞观摹。","此本中原今第一，真成一字一骊珠。"]},{"t":"北高峰屡欲登而辍","f":"七言绝句","c":["拟上高峰最上头，篮舆已赁又还休。","旧来诗眼如今别，添与江南一段愁。"]},{"t":"四月一日早闻莺","f":"五言绝句","c":["客里花都尽，初闻晓树莺。","莺声虽已老，毕竟是莺声。"]},{"t":"四月十二日饮陆君用见山堂","f":"七言绝句","c":["砚几书床茂树间，花深竹密地宽閒。","绿阴正是浓时节，遮尽人家只见山。"]},{"t":"四月初二日出兵恰满一月百姓未得下城","f":"五言律诗","c":["久谓兵当解，何知战未休。","属方甜笋蕨，遽已艳葵榴。","骨痛金疮作，心烦火色浮。","满城俱闭户，不但一人愁。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其十二","f":"七言绝句","c":["开禧嘉定擅权臣，地下眉头想更颦。","侂远传衣至亡国，止缘不用读书人。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其十一","f":"七言绝句","c":["考官蔡兹取三策，三奏赏音汪应辰。","天下未尝无识者，近来识者亦无人。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其十","f":"七言绝句","c":["澹庵老荐此诗人，屈道何妨可致身。","负鼎干汤公岂肯，本来馀事压黄陈。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其九","f":"七言绝句","c":["四世东南保太平，有君无相庙堂轻。","具知人眼识朱子，独赵汝愚陈俊卿。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其八","f":"七言绝句","c":["孟子告子辨内外，汉王项王争雌雄。","谁欤著定会陔录，梭象终输与遁翁。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其七","f":"七言绝句","c":["草制无知傅伯寿，问诗不答陈傅良。","王淮林栗胡纮辈，仲尼日月曾何伤。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其六","f":"七言绝句","c":["本无极老谓主静，不远复翁言内腴。","纸上仙方谁解服，尾公羽化上天衢。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其五","f":"七言绝句","c":["王道浪谈行霸说，儒言阴用佐禅机。","贪狼弧矢观星象，天遣吾公辟此非。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其四","f":"七言绝句","c":["乡国追封初岂意，师垣极品亦何心。","考功郎议一字□，□相斯文上帝临。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其三","f":"七言绝句","c":["独能有眼识延平，濂洛渊源集大成。","早负性资专问学，后生岂可少先生。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其二","f":"七言绝句","c":["颠杨仆墨诋苏张，推挽时君可帝王。","轲死不传今再见，一时无数起臧仓。"]},{"t":"正月十九日四更起读朱文公年谱至天大明赋十二首 其一","f":"七言绝句","c":["夜寐若无三斗酒，夙兴不待五更钟。","浩歌閒把铁如意，□慕先生忆卧龙。"]},{"t":"汉臣明府与公度使君话吾州山水之胜有诗次韵二首 其一","f":"七言绝句","c":["绣作群峰玉作川，笔端秋思浩无边。","赐金增秩从民借，会费将军九万笺。"]},{"t":"立夏五首 其五","f":"七言绝句","c":["南华六祖老卢能，宇宙千灯复万灯。","佛法平生吾不信，神交一二老诗僧。"]},{"t":"立夏五首 其四","f":"七言绝句","c":["路过偏岭暑风凉，草色连天七寸长。","无限牛羊无树木，青青六月地椒香。"]},{"t":"立夏五首 其三","f":"七言绝句","c":["说与江湖故旧知，不曾得句未为诗。","一更一至五更五，半是搔头不寐时。"]},{"t":"立夏五首 其二","f":"七言绝句","c":["齐侯北海楚南海，匹马扁舟我过之。","一事略如陆务观，囊中真有万篇诗。"]},{"t":"立夏五首 其一","f":"七言绝句","c":["吾家正对紫阳山，南向宜添屋数间。","百岁十分已过八，只消无事守穷閒。"]},{"t":"记正月二十五日西湖之游十五首 其十一","f":"七言绝句","c":["千山斫入亚夫营，佳墅名园怕近城。","赖是白公资佛力，小留苍翠作秋声。"]},{"t":"记正月二十五日西湖之游十五首 其六","f":"七言绝句","c":["空埋贞观兰亭字，再出文城玉枕书。","想见八梅冢无物，生前曾笑马相如。"]},{"t":"记正月二十五日西湖之游十五首 其八","f":"七言绝句","c":["炎炎赫赫忽荒寒，败瓦颓墙百顷宽。","谁识旧朝大丞相，手携红妓倚阑干。"]},{"t":"记正月二十五日西湖之游十五首 其二","f":"七言绝句","c":["情知太乙已西游，筑馆焉能强挽留。","此老平生让人者，佛来我去尚何求。"]},{"t":"记正月二十五日西湖之游十五首 其三","f":"七言绝句","c":["一夜缁郎刬醮坛，三清四圣化泥团。","也曾输与林灵素，顶上曾缨德士冠。"]},{"t":"记正月二十五日西湖之游十五首 其十五","f":"七言绝句","c":["苏公堤畔水如天，又见侵疆筑葑田。","遥望横斜似棋局，飞乌翘鹭自争先。"]},{"t":"记正月二十五日西湖之游十五首 其九","f":"七言绝句","c":["容堂何地可容人，一语忠规坐杀身。","母死明年尔亦死，盗名犹谓再庚申。"]},{"t":"记正月二十五日西湖之游十五首 其十三","f":"七言绝句","c":["相逢剑客曳长巾，曾道西湖看尽人。","石屋雨来春树暗，人琴两已作埃尘。"]},{"t":"记正月二十五日西湖之游十五首 其七","f":"七言绝句","c":["身为帝傅辩章公，慎恤奇丸侈后宫。","更欲长生汲丹井，山中笑倒葛仙翁。"]},{"t":"记正月二十五日西湖之游十五首 其四","f":"七言绝句","c":["千树梅花斫半无，有人更欲涸西湖。","曾思慎勿近前日，不看老彭观井图。"]},{"t":"记正月二十五日西湖之游十五首 其十二","f":"七言绝句","c":["业已通名敢退无，小为性命忍须臾。","十年朝士知何限，不许游湖许见湖。"]},{"t":"记正月二十五日西湖之游十五首 其十四","f":"七言绝句","c":["六桥箫鼓日喧天，谁料年来渐索然。","兴废荣枯都不识，一家活计一渔船。"]},{"t":"记正月二十五日西湖之游十五首 其五","f":"七言绝句","c":["石梁石柱石为碑，山拔泉飞石可移。","两玉堂仙一髡叟，自应名字万年垂。"]},{"t":"记正月二十五日西湖之游十五首 其一","f":"七言绝句","c":["来舆去马禁城空，丰乐楼消一炬红。","说与吴侬莫惆怅，龙墀犹化梵王宫。"]},{"t":"记正月二十五日西湖之游十五首 其十","f":"七言绝句","c":["一犁酥润万牛耕，饭碗人间系死生。","公子楼头赏春雨，杏花树上听新莺。"]},{"t":"先天易吟三十首 其二十八","f":"五言绝句","c":["嗜欲损为益，荣华降是升。","圆图观起处，生意伏阴凝。"]},{"t":"先天易吟三十首 其二十六","f":"五言绝句","c":["两重三画卦，半束百茎蓍。","避就殊凶吉，元无巧与奇。"]},{"t":"先天易吟三十首 其六","f":"五言绝句","c":["八卦各为八，枝从干上横。","厥初有何物，万物一根生。"]},{"t":"先天易吟三十首 其八","f":"五言绝句","c":["从来二生四，谁谓二生三。","迷路求玄牝，精微未许探。"]},{"t":"先天易吟三十首 其十七","f":"五言绝句","c":["六爻六画后，六位六虚中。","此处曾著眼，玄哉无极翁。"]},{"t":"先天易吟三十首 其一","f":"五言绝句","c":["不识第一画，羲皇运腕初。","凭空说仪象，枉著汗牛书。"]},{"t":"先天易吟三十首 其十","f":"五言绝句","c":["子半至午半，南方旋北方。","往来分逆顺，治乱判阴阳。"]},{"t":"先天易吟三十首 其二十一","f":"五言绝句","c":["天地囿于气，圣贤脩此心。","范围非有许，生聚尚斯今。"]},{"t":"先天易吟三十首 其二十二","f":"五言绝句","c":["水旱尧汤有，先天数可推。","圣君得贤相，翻是太平时。"]},{"t":"先天易吟三十首 其十九","f":"五言绝句","c":["先觉欲觉后，三峰列四图。","求精由蕴入，言说本来无。"]},{"t":"先天易吟三十首 其九","f":"五言绝句","c":["首言天地易，次语赞羲皇。","系传谁精玩，先看第一章。"]},{"t":"先天易吟三十首 其七","f":"五言绝句","c":["钟律及星历，军师兼井田。","方圆两图在，万古立鳌天。"]},{"t":"先天易吟三十首 其三","f":"五言绝句","c":["高下乾坤位，东西日月门。","正身当午立，一点认心源。"]},{"t":"先天易吟三十首 其二十九","f":"五言绝句","c":["独妙先天学，恭惟击壤翁。","返观心是易，万化出胸中。"]},{"t":"先天易吟三十首 其二十三","f":"五言绝句","c":["神农尝毒药，轩后设难经。","认取卦中意，仁心救未形。"]},{"t":"先天易吟三十首 其二十四","f":"五言绝句","c":["水平民不溺，谷播世无饥。","气数如寒暑，能无理转移。"]},{"t":"先天易吟三十首 其二十五","f":"五言绝句","c":["谁识归奇意，专为禦患谋。","将寒储纩絮，未暮贮膏油。"]},{"t":"先天易吟三十首 其二","f":"五言绝句","c":["舜禹昔禅位，曾将易问蓍。","即知重八卦，已自伏羲时。"]},{"t":"先天易吟三十首 其五","f":"五言绝句","c":["四象写老少，两仪书偶奇。","四从两上判，惟一邵翁知。"]},{"t":"先天易吟三十首 其二十七","f":"五言绝句","c":["画处本天地，占时通鬼神。","自然大道理，丝发不由人。"]},{"t":"先天易吟三十首 其十五","f":"五言绝句","c":["圆象天仪转，方侔地里分。","独超形器外，寂感一灵君。"]},{"t":"先天易吟三十首 其十四","f":"五言绝句","c":["瀛登唐治日，奎聚宋兴年。","子午复南北，一声啼杜鹃。"]},{"t":"先天易吟三十首 其十八","f":"五言绝句","c":["万世复万世，人心无改时。","此理本非古，伏羲先得之。"]},{"t":"先天易吟三十首 其二十","f":"五言绝句","c":["心法先天易，盍于离位求。","傥非明出地，长夜使人愁。"]},{"t":"先天易吟三十首 其十一","f":"五言绝句","c":["有画无言语，斯文岂易知。","人心对天一，更向画前窥。"]},{"t":"先天易吟三十首 其四","f":"五言绝句","c":["太极元无物，群生性命根。","一奇仍一偶，万象满乾坤。"]},{"t":"再题通政院王荣之八月杏花 其五","f":"七言绝句","c":["种传董奉术韩湘，顷刻能开锦绣香。","好画团圆明月夜，中秋天色变春光。"]},{"t":"再题通政院王荣之八月杏花 其一","f":"七言绝句","c":["红闹枝头二月寒，中秋还许两回看。","君家泮水宫墙畔，吾道重春孔子坛。"]},{"t":"再题通政院王荣之八月杏花 其二","f":"七言绝句","c":["半秋凉意转春寒，似曲江头紫陌看。","霜近核中仁再结，多调饧酪奉新欢。"]},{"t":"再题通政院王荣之八月杏花 其四","f":"七言绝句","c":["简斋诗老不重生，流月无声句绝清。","好个杏花疏影里，秋空吹笛到天明。"]},{"t":"再题通政院王荣之八月杏花 其三","f":"七言绝句","c":["早开菖叶劝耕辰，八月繁华又一新。","旧日举人应最喜，桂闱秋报杏园春。"]},{"t":"再赠周国祥言相","f":"七言绝句","c":["纷纷世上少全人，鹤睫分光照始真。","李相头颅君莫笑，神仙犹现羽禽身。"]},{"t":"同金汉臣徐蜚英小饮傍溪寺二首 其二","f":"七言绝句","c":["高凭远眺酒频斟，谁识风前快饮心。","州县长官胜邻境，秧畴水满树林阴。"]},{"t":"同金汉臣徐蜚英小饮傍溪寺二首 其一","f":"七言绝句","c":["万峰奇峭一川平，四月清和十日晴。","蚕麦丰登宜把酒，山城只欠艳歌声。"]},{"t":"后天易吟三十首 其三十","f":"五言绝句","c":["学者欲学易，当观羑里时。","如何是敬字，恐惧畏忧危。"]},{"t":"后天易吟三十首 其二十九","f":"五言绝句","c":["二五时难遇，沈沦下位多。","乾潜与坤履，退谨养天和。"]},{"t":"后天易吟三十首 其二十八","f":"五言绝句","c":["易经之下卷，何以始恒咸。","贞女家人利，如诗有二南。"]},{"t":"后天易吟三十首 其二十七","f":"五言绝句","c":["卦之凶者五，否剥未济三。","如姤与归妹，深防女败男。"]},{"t":"后天易吟三十首 其二十六","f":"五言绝句","c":["祖考精神散，子孙能聚之。","淫祠祭非鬼，萃涣义何居。"]},{"t":"后天易吟三十首 其二十五","f":"五言绝句","c":["亨嘉谁不愿，贞固士之常。","乾体充刚健，坤爻认直方。"]},{"t":"后天易吟三十首 其二十四","f":"五言绝句","c":["彖辞六十四，三十四言贞。","干事匪正固，难求心外亨。"]},{"t":"后天易吟三十首 其二十三","f":"五言绝句","c":["始屯终未济，世故信多艰。","维坎刚中吉，周旋险难间。"]},{"t":"后天易吟三十首 其二十二","f":"五言绝句","c":["乾坤始开辟，六坎首经纶。","士不知忧患，焉能免世氛。"]},{"t":"后天易吟三十首 其二十一","f":"五言绝句","c":["背于身不见，亦不见庭人。","物我俱无与，方知止处真。"]},{"t":"后天易吟三十首 其二十","f":"五言绝句","c":["亨到离时见，贞从坎处来。","归根培养熟，方解鼓风雷。"]},{"t":"后天易吟三十首 其十九","f":"五言绝句","c":["元亨犹利正，始可用纯乾。","未了一贞字，何由保性天。"]},{"t":"后天易吟三十首 其十八","f":"五言绝句","c":["次谦终以巽，九卦至三陈。","圣人有忧患，何况是凡人。"]},{"t":"后天易吟三十首 其十七","f":"五言绝句","c":["观身不见背，动体悉由心。","向阳负阴处，离坎细推寻。"]},{"t":"后天易吟三十首 其十六","f":"五言绝句","c":["细玩文王卦，如何法地方。","田从一井起，乡遂及要荒。"]},{"t":"后天易吟三十首 其十五","f":"五言绝句","c":["宗庙蒸尝礼，朝廷觐见仪。","无穷天下事，不过似农时。"]},{"t":"后天易吟三十首 其十四","f":"五言绝句","c":["八列方隅位，四周分至时。","画疆兴庶务，地矩囿天规。"]},{"t":"后天易吟三十首 其十三","f":"五言绝句","c":["阳生在十月，亥谓之天门。","战乎乾者物，乾实战于坤。"]},{"t":"后天易吟三十首 其十二","f":"五言绝句","c":["役物至未极，分明土王时。","嗣火孕金气，秋成方在兹。"]},{"t":"后天易吟三十首 其十一","f":"五言绝句","c":["君知已似嗣，音义古来同。","万物生相续，南薰鼓巽风。"]},{"t":"后天易吟三十首 其十","f":"五言绝句","c":["雷风火泽水，独艮不言山。","朔易指方位，万形消息间。"]},{"t":"后天易吟三十首 其九","f":"五言绝句","c":["万物天为大，中间地次之。","成功付诸子，父母似无为。"]},{"t":"后天易吟三十首 其八","f":"五言绝句","c":["天一实生水，冬藏坎次乾。","精神要休养，酝酿出春天。"]},{"t":"后天易吟三十首 其七","f":"五言绝句","c":["兑泽何言说，秋成看水田。","黄云万万顷，滋润作丰年。"]},{"t":"后天易吟三十首 其六","f":"五言绝句","c":["万物皆相见，文明午日中。","圣人南面立，品汇各亨通。"]},{"t":"后天易吟三十首 其五","f":"五言绝句","c":["震位东方木，胡为以帝言。","一芽观出处，主宰见天根。"]},{"t":"后天易吟三十首 其四","f":"五言绝句","c":["易名缘变易，周义取周流。","出震始终艮，当于此处求。"]},{"t":"后天易吟三十首 其三","f":"五言绝句","c":["世治常无乱，民安永不危。","尚须西伯演，羲画可无之。"]},{"t":"后天易吟三十首 其二","f":"五言绝句","c":["位须分对待，气即验流行。","羲体兼文用，俱由造化生。"]},{"t":"后天易吟三十首 其一","f":"五言绝句","c":["万古未来事，先天逆已知。","卦中无不有，却要后天推。"]},{"t":"后秋思五言五首 其五","f":"五言绝句","c":["五房十昆仲，独许一身存。","今日重阳日，登楼欲断魂。"]},{"t":"后秋思五言五首 其四","f":"五言绝句","c":["诗与风骚迫，文兼史汉长。","半山非不尔，僻学汴梁亡。"]},{"t":"后秋思五言五首 其三","f":"五言绝句","c":["黄陈今不作，天地少诗人。","不是诗人少，诗人未必真。"]},{"t":"后秋思五言五首 其二","f":"五言绝句","c":["诗老吾衰矣，秋风又飒然。","黄花香五度，八十太公年。"]},{"t":"后秋思五言五首 其一","f":"五言绝句","c":["多病全然懒，微凉尚未寒。","偶然无一事，蛛网雨中看。"]},{"t":"庆陆仁重举男四首 其四","f":"七言绝句","c":["积善悬知庆有馀，芝兰衮衮秀阶除。","紫阳一滴泉源远，早聘名儒授四书。"]},{"t":"庆陆仁重举男四首 其三","f":"七言绝句","c":["升平重见上元天，箫鼓声中璧月圆。","惟有高门更多喜，金盘分送洗儿钱。"]},{"t":"庆陆仁重举男四首 其二","f":"七言绝句","c":["相门佳气夜葱葱，早已凭熊更梦熊。","二十此郎作文赋，乃翁仍是黑头公。"]},{"t":"庆陆仁重举男四首 其一","f":"七言绝句","c":["治郡年才半买臣，青春天上送麒麟。","鼎来好事由阴德，曾活澄江十万人。"]},{"t":"戏书","f":"七言绝句","c":["万有非真偶有之，倏无合悟本无时。","伯夷季札轻千乘，肯著春风护柳枝。"]},{"t":"早桃花","f":"七言绝句","c":["刘郎异种出天台，雪里夭夭解早开。","邻舍觅花聊折送，祇应遥认是红梅。"]},{"t":"朱字兰亭","f":"七言绝句","c":["倾城国色著胭脂，红字兰亭又出奇。","比换鹅书更姿媚，一杯卯酒醉西施。"]},{"t":"杂书五首 其五","f":"七言绝句","c":["饶君遒紧日千篇，未办骊珠出九渊。","欲诣彭城陈正字，须参南岳赵章泉。"]},{"t":"杂书五首 其四","f":"七言绝句","c":["一毫不敢昧苍天，生世明年七十年。","自恨肉身无报答，日常饱饭夜安眠。"]},{"t":"杂书五首 其三","f":"七言绝句","c":["细修佳传酬知己，曲就微生赖若人。","一点报恩心独在，时时常见梦中身。"]},{"t":"杂书五首 其二","f":"七言绝句","c":["卜世周家谓过之，从来历数亦难知。","岂期河洛亡三翮，不比房心续续微。"]},{"t":"杂书五首 其一","f":"七言绝句","c":["鼻涕垂颐银竹冻，脑脂遮眼黑花飞。","此身尚觉非吾有，焉问人间万事非。"]},{"t":"次韵汉臣闵口渡","f":"七言绝句","c":["岁月匆匆雁往回，马头西去又东来。","不知自有乾坤后，几度芦花谢复开。"]},{"t":"次韵芝田上人子虚二首 其二","f":"七言绝句","c":["为问葛藤禅律论，口钳舌结更无言。","何如了办眼前事，且说诗家不二门。"]},{"t":"次韵芝田上人子虚二首 其一","f":"七言绝句","c":["年长山僧五十秋，每携诗卷过吾楼。","老衰英妙心相似，灵隐亭前水不流。"]},{"t":"次韵吴僧魁一山十绝 其七","f":"七言绝句","c":["长安应制住红楼，浪惹玄都紫陌愁。","天目有山无捷径，落花莫放出溪流。"]},{"t":"次韵吴僧魁一山十绝 其一","f":"七言绝句","c":["百结袈裟破唐帽，子为何物我为谁。","孰知各有直钩钓，解出珊瑚海底枝。"]},{"t":"次韵吴僧魁一山十绝 其二","f":"七言绝句","c":["天河泻水洗心君，瞎眼能观聩亦闻。","不是唐皇迎佛骨，大颠焉得见韩文。"]},{"t":"次韵吴僧魁一山十绝 其三","f":"七言绝句","c":["潘江陆海一笑唾，暂借禅衣隐此身。","坡谷两翁合为一，座间始可著斯人。"]},{"t":"次韵吴僧魁一山十绝 其九","f":"七言绝句","c":["东南衲子密如云，何限参寥与惠勤。","泉下欧苏今不作，伽佗祇夜乱纷纷。"]},{"t":"次韵吴僧魁一山十绝 其十","f":"七言绝句","c":["高安僧宝姚圆至，盐水谁其成酱冰。","莫为猢狲打筋斗，回头不记读书灯。"]},{"t":"次韵吴僧魁一山十绝 其六","f":"七言绝句","c":["己学故学天隐说，多因误剃镜中头。","戏拈当日颜良案，两足何堪踏两舟。"]},{"t":"次韵吴僧魁一山十绝 其八","f":"七言绝句","c":["隋朝桧下访仙真，五十年前夜榻身。","至道宫前天目顶，羡公去作卧云人。"]},{"t":"次韵吴僧魁一山十绝 其五","f":"七言绝句","c":["筠溪四十三岁夭，师弟与兄传夜衣。","国手棋高更有著，百年政恐疾于飞。"]},{"t":"次韵张鹏飞三绝 其三","f":"七言绝句","c":["雪天人品最高者，蓑笠江干一钓竿。","才有侍儿焉识此，党晖陶谷总酸寒。"]},{"t":"次韵张鹏飞三绝 其二","f":"七言绝句","c":["酒箴酒颂日夜读，后喜伯伦前子云。","浪说平生三万卷，一言无用总虚文。"]},{"t":"次韵张鹏飞三绝 其一","f":"七言绝句","c":["舐犊区区笑老牛，阿瞒焉恤一杨彪。","英雄误理大床话，卖药惟应学伯休。"]},{"t":"次韵陈正之团扇画一鱼二首 其二","f":"五言绝句","c":["妙得濠梁趣，任公犗肯吞。","□泉如有待，头角上天门。"]},{"t":"次韵陈正之团扇画一鱼二首 其一","f":"五言绝句","c":["莫想银丝脍，冰盘一醉吞。","好为玉带佩，朝谒九重门。"]},{"t":"次韵金汉臣见雪闻雁二首 其二","f":"七言绝句","c":["月暗云迷度杳冥，飞鸣未肯落寒汀。","得无田里声相似，独此长官能细听。"]},{"t":"次韵金汉臣见雪闻雁二首 其一","f":"七言绝句","c":["山城酒薄客愁浓，卧厌秋霖万事慵。","九月十月忽飞雪，北人南人俱笑容。"]},{"t":"次韵赵宾旸见寄长句","f":"七言绝句","c":["百忧攻心成白首，不少自宽死已久。","我初作郡犹未贫，□□比□□□□。"]},{"t":"次韵徐赞府蜚英八首 其八","f":"七言绝句","c":["老农持底报君公，十日甘霖五日风。","夜静山中看天象，福星偏许照江东。"]},{"t":"次韵徐赞府蜚英八首 其七","f":"七言绝句","c":["屏除呵殿少人知，随马囊诗更有谁。","五百不来村落静，自然生齿似螽斯。"]},{"t":"次韵徐赞府蜚英八首 其六","f":"七言绝句","c":["摩拊茕嫠达下情，领州作县总书生。","清诗要自清心出，比自新安水更清。"]},{"t":"次韵徐赞府蜚英八首 其五","f":"七言绝句","c":["骑入州城出县城，不须人送不须迎。","连峰峻岭崎岖极，政自胸中掌样平。"]},{"t":"次韵徐赞府蜚英八首 其四","f":"七言绝句","c":["悬崖复岭间冈坡，如此天边远碧何。","谁道此中曾得句，道傍老树阅人多。"]},{"t":"次韵徐赞府蜚英八首 其三","f":"七言绝句","c":["树形万怪石千奇，我亦曾行亦有诗。","焉得一官如长吏，出郊长是看山时。"]},{"t":"次韵徐赞府蜚英八首 其二","f":"七言绝句","c":["高低田水入溪流，溪岸閒横野渡舟。","麦饭家家甑中有，永无犊佩起山头。"]},{"t":"次韵徐赞府蜚英八首 其一","f":"七言绝句","c":["长官行县课农书，耕叟治田贾趁虚。","上到岭头望应喜，人烟今密旧时疏。"]},{"t":"次韵康庆之催借所著及谢见过 其一","f":"七言绝句","c":["闻道公家所著书，担囊荷箧喘肩夫。","定应未肯轻传借，良贾深藏有若无。"]},{"t":"次韵康庆之催借所著及谢见过 其二","f":"七言绝句","c":["胸涵太古恐无邻，面著微埃讵许亲。","顾肯城南访穷巷，松风时煮一瓯春。"]},{"t":"次韵康庆之题予桐江诗卷 其一","f":"七言绝句","c":["每愧诗无古风调，背山楼阁晒花裈。","稍知海若吞河伯，敢眩蹄涔一勺浑。"]},{"t":"次韵阎学士靖轩赠受益山居二首 其二","f":"七言绝句","c":["八月涛江五月湖，画图一见粟生肤。","君家奄有两奇观，更觉天真胜画图。"]},{"t":"次韵阎学士靖轩赠受益山居二首 其一","f":"七言绝句","c":["十里方诸影绿鬟，空濛潋滟一窗间。","天河不洗读书眼，未可同君上此山。"]},{"t":"江行大雨水涨四首 其四","f":"七言绝句","c":["何处岸颓漂大树，明朝水落阁平滩。","村民争剪为薪去，万事从前预料难。"]},{"t":"江行大雨水涨四首 其三","f":"七言绝句","c":["踏竿倒挂似飞猱，水长船行拂树梢。","忽讶平途成峻濑，更怜危石没深涛。"]},{"t":"江行大雨水涨四首 其二","f":"七言绝句","c":["一夜水高丈五六，移舟稳傍渔家宿。","矶头浪急上滩难，舟子索钱赛神福。"]},{"t":"江行大雨水涨四首 其一","f":"七言绝句","c":["客路由来但喜晴，山深何况更舟行。","孤篷酒醒三更雨，滴碎愁肠是此声。"]},{"t":"牟德范题范石湖墨迹次韵","f":"七言绝句","c":["亨衢进补华虫衮，暮景归调姹女炉。","此老笔端今或有，乾淳蹉了后来无。"]},{"t":"红蔷薇花","f":"七言绝句","c":["月桂金沙各斗春，蔷薇红透更精神。","虽然面似佳人笑，满体锋铓解刺人。"]},{"t":"至节前一日六首 其六","f":"七言绝句","c":["心情诗卷无佳句，时节梅花有好枝。","较似后山更平澹，一生爱诵石湖诗。"]},{"t":"至节前一日六首 其五","f":"七言绝句","c":["客子光阴诗卷里，杏花消息雨声中。","我谓简斋此奇句，元来出自后山翁。"]},{"t":"至节前一日六首 其四","f":"七言绝句","c":["莼羹鲈鲙鉴湖风，想像依稀老放翁。","惜为平原多一出，诗名元已擅无穷。"]},{"t":"至节前一日六首 其三","f":"七言绝句","c":["灯前一影客中身，鸡未鸣时起已频。","每日盆梅千百担，倚楼閒作看花人。"]},{"t":"至节前一日六首 其二","f":"七言绝句","c":["征羌汉将赵充国，赐履齐侯周太公。","虚叟纪年亦云尔，五湖四海一诗穷。"]},{"t":"至节前一日六首 其一","f":"七言绝句","c":["少陵早是沧浪客，马援真成矍铄翁。","四十五年忝科第，一生心与布衣同。"]},{"t":"舟行青溪道中入歙十二首 其十二","f":"七言绝句","c":["歙州民与睦州民，比似吴儿大较贫。","为问山中有何好，山中剩有读书人。"]},{"t":"舟行青溪道中入歙十二首 其十一","f":"七言绝句","c":["蕨拳欲动茗抽芽，节近清明路近家。","五日缓行三百里，夹溪随处有桃花。"]},{"t":"舟行青溪道中入歙十二首 其十","f":"七言绝句","c":["青溪元是歙东乡，吾祖于时肯宝黄。","避地江南结庐处，同时邻舍有严光。"]},{"t":"舟行青溪道中入歙十二首 其九","f":"七言绝句","c":["花间预想到家时，笋蕨堆盘荐酒卮。","点检儿童参小学，招呼朋友说新诗。"]},{"t":"舟行青溪道中入歙十二首 其八","f":"七言绝句","c":["野桃篱落鹊双鸣，春晓微寒放嫩晴。","汛扫松楸家已近，犹馀七日是清明。"]},{"t":"舟行青溪道中入歙十二首 其七","f":"七言绝句","c":["刺桐花发草如蓝，欲卸绵袍剪纻衫。","一夜春霜忽如雪，江南天气不宜蚕。"]},{"t":"舟行青溪道中入歙十二首 其六","f":"七言绝句","c":["夜寒如觉有猿吟，积翠重苍万壑深。","下水轻舟弦脱箭，盘山细路线穿针。"]},{"t":"舟行青溪道中入歙十二首 其五","f":"七言绝句","c":["晚风微劲喜新晴，夜半船窗漏月明。","卧看孤篷摇水影，悠然枕上一诗成。"]},{"t":"舟行青溪道中入歙十二首 其四","f":"七言绝句","c":["水杨梢上欲绵飞，犹觉春寒未解围。","为怕江风吹客梦，船篷缺处塞蓑衣。"]},{"t":"舟行青溪道中入歙十二首 其三","f":"七言绝句","c":["乘时盗贼起风尘，战血苔痕几度春。","古庙仅能存大树，荒山犹自少行人。"]},{"t":"舟行青溪道中入歙十二首 其二","f":"七言绝句","c":["立岸儿童看客过，人烟近处放牛多。","万株漫自栽桑柘，一缕何曾织绮罗。"]},{"t":"舟行青溪道中入歙十二首 其一","f":"七言绝句","c":["覆野春阴不肯晴，舟中无酒亦无饧。","故教客子知寒食，时有梨花一树明。"]},{"t":"芍药花","f":"七言绝句","c":["眼中不复见姚黄，从古扬州亚洛阳。","何止中郎虎贲似，政堪花相相花王。"]},{"t":"行于潜县南田中","f":"七言绝句","c":["曾蹑危桥入县行，萧然无处觅诗情。","不如涉浅田南过，天目山长一抹横。"]},{"t":"行宫西门","f":"七言绝句","c":["翠华东幸缔和盟，从此君王罢北征。","宿卫周庐无处所，野人畦菜傍宫城。"]},{"t":"西斋","f":"五言绝句","c":["偶得西斋字，向西开此斋。","人间诗眼少，天下夕阳佳。"]},{"t":"西湖答","f":"七言绝句","c":["浓妆淡抹比蛾眉，多谢苏仙内翰诗。","若使朝廷无宰嚭，未妨宫掖有西施。"]},{"t":"观丧事","f":"七言绝句","c":["悠悠谁到百年身，百万杭民一聚薪。","棺内棺前争几许，挽郎自是白须人。"]},{"t":"观蚁迁知雨","f":"七言绝句","c":["行行密密复疏疏，衔子沿阶粟粒如。","几夜夏寒疑未雨，槐安国有五行书。"]},{"t":"过长安市","f":"七言绝句","c":["算橘租菱小市哗，堰头桥尾约千家。","人家已尽无人处，时见芙蓉一岸花。"]},{"t":"过石门","f":"七言绝句","c":["麦田下种稻田乾，秋尽江南亦未寒。","水净风微船牵慢，莼花蕴草尽堪看。"]},{"t":"过临平二首 其二","f":"七言绝句","c":["行在名存一梦惺，西湖路近六长亭。","陈桥驿与临平镇，兴废何人了汗青。"]},{"t":"过临平二首 其一","f":"七言绝句","c":["临平山下汎归船，何必荷花五月天。","记取五更霜□□，□芳桥买小鱼鲜。"]},{"t":"过临平镇","f":"七言绝句","c":["楼船载甲晓闻钲，知是何营将校行。","百五十年兴废事，韩家军马战临平。"]},{"t":"过崇德县","f":"七言绝句","c":["枯柳无风影不摇，败墙颓屋意萧萧。","忽然唤醒承平梦，犹有红栏夹画桥。"]},{"t":"过湖口望庐山","f":"七言绝句","c":["江行初见雪中梅，梅雨霏微棹始回。","莫道无人肯相送，庐山犹自过湖来。"]},{"t":"闭户","f":"七言绝句","c":["闭户瓶梅满屋香，小楼微醉月昏黄。","三更独坐犹无寐，更欲移花近枕傍。"]},{"t":"问西湖","f":"七言绝句","c":["谁将西子比西湖，旧日繁华渐欲无。","始信坡仙诗是谶，捧心国色解亡吴。"]},{"t":"两邻家一主人群姬歌饮至夜半一母妻哭官检魇死者","f":"七言绝句","c":["歌喉弦指粉红腮，群拥山翁醉玉颓。","政恐真欢犹是假，不如邻妇哭真哀。"]},{"t":"别后","f":"七言绝句","c":["朋簪连日醉如泥，别后临流意自迷。","语燕驻空相尔汝，飞花吹岸各东西。"]},{"t":"听航船歌十首 其十","f":"七言绝句","c":["船头船尾唱歌声，苏秀湖杭总弟兄。","喝拢喝开不相照，阿牛贼狗便无情。"]},{"t":"听航船歌十首 其九","f":"七言绝句","c":["赌钱输了阿侬哥，黄草单衫破孔多。","相趁缩砂红豆客，霜风九月上淮河。"]},{"t":"听航船歌十首 其八","f":"七言绝句","c":["南姚村打北姚村，鬼哭谁怜枉死魂。","争似梢工留口吃，秀州城外鸭馄饨。"]},{"t":"听航船歌十首 其七","f":"七言绝句","c":["雇载钱轻载不轻，阿郎拽牵阿奴撑。","五千斤蜡三千漆，宁馨时年欲夜行。"]},{"t":"听航船歌十首 其六","f":"七言绝句","c":["南到杭州北楚州，三江八堰水通流。","牵板船篙为饭碗，不能辛苦把锄头。"]},{"t":"听航船歌十首 其五","f":"七言绝句","c":["十千债要廿千偿，债主仍须数倍强。","定是还家被官缚，且将贯百寄妻娘。"]},{"t":"听航船歌十首 其四","f":"七言绝句","c":["四千五百魏塘船，结拆船牙解半千。","一千修柁贯三米，三日盘缠无一钱。"]},{"t":"听航船歌十首 其三","f":"七言绝句","c":["家住斜塘大户边，时荒米贵欠他钱。","从此驾船归不得，无钱且驾小航船。"]},{"t":"听航船歌十首 其二","f":"七言绝句","c":["莫笑船家生事微，新红米饭绿蓑衣。","一声欸和一声乃，谁识人间有是非。"]},{"t":"听航船歌十首 其一","f":"七言绝句","c":["北来南去雁还飞，四十年间万事非。","惟有航船歌不改，夜深老泪欲沾衣。"]},{"t":"孚舟亭新成赋十绝 其九","f":"七言绝句","c":["向来人唤老梢工，解使帆樯八面风。","今日钓鱼亦无力，劣能听雨卧船篷。"]},{"t":"孚舟亭新成赋十绝 其一","f":"七言绝句","c":["岸人胆落傍船看，鼍吐鲸吞一叶寒。","鬼伯神官莫狂荡，灵台无愧自平安。"]},{"t":"孚舟亭新成赋十绝 其二","f":"七言绝句","c":["南北东西四面看，舸轩虽窄自心宽。","永无金马门边梦，岂有黄牛峡里滩。"]},{"t":"孚舟亭新成赋十绝 其六","f":"七言绝句","c":["心许天知不愧天，酣风醉月仰天眠。","自疑略似知章马，人道还如太乙莲。"]},{"t":"孚舟亭新成赋十绝 其八","f":"七言绝句","c":["人间踏地有风波，归老山林莫问他。","身是我船心是柁，早寻岸泊奈侬何。"]},{"t":"孚舟亭新成赋十绝 其三","f":"七言绝句","c":["春浓面面透花香，秋皎团团转月光。","窗户总空天是壁，如吾肺腑没遮藏。"]},{"t":"孚舟亭新成赋十绝 其七","f":"七言绝句","c":["不须有客问张凭，且要无人觅庾冰。","好是夜寒风浪静，月明空载一孤僧。"]},{"t":"孚舟亭新成赋十绝 其五","f":"七言绝句","c":["傍石横陈八柱亭，一篷撱矮似船形。","松声浪作风涛吼，何处风涛不惯经。"]},{"t":"孚舟亭新成赋十绝 其四","f":"七言绝句","c":["六爻虚实相为用，二位高卑各有宜。","顺抚说随心不爽，风漂罗刹有还时。"]},{"t":"寿昌郑生入天目山礼僧","f":"七言绝句","c":["欲作空门补处人，如何头上裹头巾。","曹溪一夜传衣钵，元是当年行者身。"]},{"t":"张棕仲实见惠江阴丘本","f":"七言绝句","c":["绝喜他乡见似人，颇如画手善传神。","忽思今昔无穷事，十五回经癸丑春。"]},{"t":"李仲宾墨竹四首 其四","f":"七言绝句","c":["渭川千亩入毫端，子美临风野色寒。","不是画师即诗客，可能收拾与人看。"]},{"t":"李仲宾墨竹四首 其三","f":"七言绝句","c":["心空节劲翠筠浓，冷笑凡花诲冶容。","可是人间秋水碧，东方七宿应苍龙。"]},{"t":"李仲宾墨竹四首 其二","f":"七言绝句","c":["春生夏长出墙头，含箨新梢玉版抽。","宜雪宜霜无不可，如椽且与貌宜秋。"]},{"t":"李仲宾墨竹四首 其一","f":"七言绝句","c":["乾坤各各变三爻，坎兑相依似泰交。","认得易中甘节卦，箨龙贞干写烟梢。"]},{"t":"李花","f":"七言绝句","c":["仙根判耦得无差，春对夭桃夏对瓜。","此岂轻浮閒果子，白花亦复胜红花。"]},{"t":"村女","f":"七言绝句","c":["青荷叶伞茜裙红，随母归宁省外翁。","莫笑梳装未京样，兵馀犹见太平风。"]},{"t":"村路有呼予老朝奉者","f":"七言绝句","c":["真公真相自难诬，非相非公亦好谀。","谁忽谓予老朝奉，心知不是赝称呼。"]},{"t":"杨花","f":"七言绝句","c":["燕忙莺懒听芳词，忆醉西湖画舫时。","山墅不知春早晚，隔墙数点堕书帷。"]},{"t":"泛浙江二首 其二","f":"七言绝句","c":["海门山到富春山，碍石冲沙水几湾。","不是此江故盘屈，雪涛何得诧吴蛮。"]},{"t":"泛浙江二首 其一","f":"七言绝句","c":["不为潮从海上生，元来水浅浪波平。","屈曲盘旋船百转，始知从古浙江名。"]},{"t":"纸窗","f":"七言绝句","c":["梅水仙花插古铜，纸窗通日不通风。","天香何假龙涎爇，地暖无劳兽炭烘。"]},{"t":"辛丑九日五首 其五","f":"七言绝句","c":["往岁金台屡据鞍，居庸雁字仰天看。","中秋蟹断□花绝，红叶西山九日寒。"]},{"t":"辛丑九日五首 其四","f":"七言绝句","c":["何事清秋已衣绵，微寒最怯倚楼天。","江南今岁黄花早，醉嚼重阳半月前。"]},{"t":"辛丑九日五首 其三","f":"七言绝句","c":["五度秋光过古希，节名良是叹人非。","吾州大火前辛丑，问政山头伐木归。"]},{"t":"辛丑九日五首 其二","f":"七言绝句","c":["世间何事不空无，万古年年九日徂。","最忆吾家先叔父，塘头一树紫茱萸。"]},{"t":"辛丑九日五首 其一","f":"七言绝句","c":["政恐登高枉断肠，今年恰值雨重阳。","晨兴中酒情怀懒，满眼黄花满屋香。"]},{"t":"连夜书 其四","f":"七言绝句","c":["腐儒休致懒弹冠，楼倚新秋午夜阑。","木德临参照南斗，江湖一稔百忧宽。"]},{"t":"连夜书 其一","f":"七言绝句","c":["独倚西楼夜渐深，下弦月欲近觜参。","立秋是日微微雨，病暑衰翁稍慰心。"]},{"t":"连夜书 其二","f":"七言绝句","c":["斜向西南月半弯，五更正值毕叉间。","朝来骤有风兼雨，红晕饶添一大环。"]},{"t":"连夜书 其三","f":"七言绝句","c":["秋凉断是合还家，三伏今年暑倍加。","病痛百般营药草，精神一半减菱花。"]},{"t":"饮归","f":"七言绝句","c":["潋滟红深百盏浇，醉归不觉路迢迢。","临分情味殷勤甚，暗遣人扶过画桥。"]},{"t":"饮孤山六一泉有感","f":"七言绝句","c":["解后犹存石柱梁，周家九鼎尚沦亡。","此泉只是寻常水，为有欧苏姓字香。"]},{"t":"和李鹤田乙未赠李个庵","f":"七言绝句","c":["这个庵中这个人，莫将两个认心身。","一个亦无羲□□，□于此处玩天真。"]},{"t":"垂欲归主客皆至","f":"七言绝句","c":["荒林野冢古原头，倚树何人识故侯。","幽僻阒寥变欢笑，针锋芥子忽相投。"]},{"t":"夜读","f":"七言绝句","c":["楼西落照炫新晴，檐雨犹馀点滴声。","信手取书开数叶，秋凉初喜夜灯明。"]},{"t":"始暖","f":"七言绝句","c":["垢汗熏蒸虮虱肥，花前未洗雪泥衣。","到家儿女应相讶，四载漂零仅一归。"]},{"t":"松下茅屋图","f":"七言绝句","c":["一株松下一茅屋，何处山中此景无。","煨芋老翁常闭户，世人从此画成图。"]},{"t":"武林书事九首 其九","f":"七言绝句","c":["我有敝庐在何许，南紫阳山北黄山。","烟耕雨钓付儿辈，一榻高枕松声间。"]},{"t":"武林书事九首 其八","f":"七言绝句","c":["兰阇兰阇一弹指，高鼻人人俱喜欢。","北客近知郎罢语，南人许拜乞银官。"]},{"t":"武林书事九首 其七","f":"七言绝句","c":["论斤买齑遗俗在，街头商贾问童儿。","不知此菜从何采，指似深宫故殿基。"]},{"t":"武林书事九首 其六","f":"七言绝句","c":["岁在戊午正月五，代宰臣供万寿诗。","凤凰山下芙蓉阁，龙础无踪世不知。"]},{"t":"武林书事九首 其五","f":"七言绝句","c":["狐狸夜号歌舞地，荆棘非复向朱门。","有人政自不可测，一斛槟榔五百裈。"]},{"t":"武林书事九首 其四","f":"七言绝句","c":["公田坐谪魏京兆，一往不招江上魂。","天道无知善人哑，全家死盗五孙存。"]},{"t":"武林书事九首 其三","f":"七言绝句","c":["金石典古吕伯可，风霜清耸方巨山。","尚见八音合韶乐，早能九鼎象神奸。"]},{"t":"武林书事九首 其二","f":"七言绝句","c":["竹林七贤六有子，何独无闻刘伯伦。","梦想先师授书处，城东风雨卧荒坟。"]},{"t":"武林书事九首 其一","f":"七言绝句","c":["明年老子六十一，最忆只身三十时。","岂料衰迟脱离乱，三孙三女四男儿。"]},{"t":"苦雨","f":"七言绝句","c":["拟勒移文问雨龙，麦秋忍不念吾农。","黄云万顷成泥烂，偏与閒檐活瓦松。"]},{"t":"雨馀早起五首 其五","f":"七言绝句","c":["懒照青铜雨垫巾，试将攲正问傍人。","含羞小婢无言去，应笑髭须总似银。"]},{"t":"雨馀早起五首 其四","f":"七言绝句","c":["浓绿园林晓雨新，莺啼近树不疑人。","千枝罂粟红如锦，谁谓侬家已送春。"]},{"t":"雨馀早起五首 其三","f":"七言绝句","c":["密树阴阴小石台，雨馀更绿几痕苔。","蜗牛上到葵花顶，日出如何下得来。"]},{"t":"雨馀早起五首 其二","f":"七言绝句","c":["枝枝红药蕊头偏，应是难禁宿雨湔。","好物不扶扶恶物，已耘死草更昂然。"]},{"t":"雨馀早起五首 其一","f":"七言绝句","c":["灯暗窗明暖又寒，破鞋不待藓痕乾。","惜花爱笋人谁解，冒雨行来百匝看。"]},{"t":"鱼亭观山","f":"七言绝句","c":["人间第一歙州山，绝妙鱼亭古道间。","描取此奇入诗句，西游端的不虚还。"]},{"t":"信州道士萧了空坐逝或见其在湘潭总府贰萧公用之为作赞亦自号悟空 其二","f":"七言绝句","c":["可能吸露更餐风，一悟悬知了万空。","何似老夫酒肉汉，死时合眼闭棺中。"]},{"t":"南高峰至其下不高","f":"七言绝句","c":["远望生愁陟降劳，峥嵘窣堵据金鳌。","今朝身到南山下，渐近元来总不高。"]},{"t":"复记乙酉重九","f":"七言绝句","c":["无酒无钱不可赊，穷居犹胜走天涯。","晴轩小圃篱门掩，时有人来觅菊花。"]},{"t":"春日小园即事十首 其十","f":"七言绝句","c":["身隐山中聊复尔，诗传海外岂其然。","□间日有人携酒，□恼如天亦醉眠。"]},{"t":"春日小园即事十首 其九","f":"七言绝句","c":["四十九时初作郡，帆风笠雨十馀年。","野花山鸟应相笑，依旧归来无一钱。"]},{"t":"春日小园即事十首 其八","f":"七言绝句","c":["莳药移花撰石名，稍加心匠可经营。","天真不假人为力，绿树啼莺一两声。"]},{"t":"春日小园即事十首 其七","f":"七言绝句","c":["颓然无用一憨痴，虽老元来未可欺。","鼻涕垂颐病拥塞，幽花香处最先知。"]},{"t":"春日小园即事十首 其六","f":"七言绝句","c":["傍宅荒山几许长，荛夫芸子纵牛羊。","何当尽与栽桃李，叠石周遭筑短墙。"]},{"t":"春日小园即事十首 其五","f":"七言绝句","c":["城中谁道有花村，吟出园门醉入门。","共笑老人骑老马，病身俱瘦壮心存。"]},{"t":"春日小园即事十首 其四","f":"七言绝句","c":["摘花不恤种花难，几日工夫一日残。","最是好花留不得，不如只种菜花看。"]},{"t":"春日小园即事十首 其三","f":"七言绝句","c":["长忆江湖看雨时，插天挂尾玉龙垂。","归来老手今无用，养小鱼虾掘小池。"]},{"t":"春日小园即事十首 其二","f":"七言绝句","c":["小亭新筑赏天香，恍惚春风旧洛阳。","人道此翁畦菜手，元来亦解种姚黄。"]},{"t":"春雨不已甚忧蚕麦二首 其二","f":"七言绝句","c":["笼炊汤沸饼如银，辛苦焉知种麦人。","今岁夏初似高凤，黄云欲割半沉沦。"]},{"t":"春雨不已甚忧蚕麦二首 其一","f":"七言绝句","c":["提篮采叶雨淋淋，蚕妇无言恨自深。","绮陌惜花小儿女，愁眉相似不同心。"]},{"t":"春晚杂兴十二首 其十二","f":"七言绝句","c":["芳草茸茸没屦深，清和天气润园林。","霏微小雨初晴处，暗数青梅立树阴。"]},{"t":"春晚杂兴十二首 其十一","f":"七言绝句","c":["城市尘埃不见诗，西村东坞可寻谁。","夏前十日尝新麦，政是江南最好时。"]},{"t":"春晚杂兴十二首 其十","f":"七言绝句","c":["桐花落尽熟朱樱，无数珍禽绕树鸣。","绣羽翠衿政堪玩，伊谁轻著弹丸惊。"]},{"t":"春晚杂兴十二首 其九","f":"七言绝句","c":["溪鱼山笋佐新篘，大胜长安上酒楼。","春老犹寒宿酲困，酴醾花下拥绵裘。"]},{"t":"春晚杂兴十二首 其八","f":"七言绝句","c":["尪羸老马尚堪骑，象笏金章已属谁。","政使死时无一物，清心壮胆有天知。"]},{"t":"春晚杂兴十二首 其七","f":"七言绝句","c":["随分栽蔬复种花，逐时温酒又煎茶。","两儿能售严州屋，便可归来共一家。"]},{"t":"春晚杂兴十二首 其六","f":"七言绝句","c":["岂有耶溪父老钱，无朝无暮在樽前。","樱桃豌豆分儿女，草草春风又一年。"]},{"t":"春晚杂兴十二首 其五","f":"七言绝句","c":["漫浪桐江一把麾，往来今积十年诗。","次山自序舂陵集，岂望夔州杜二知。"]},{"t":"春晚杂兴十二首 其四","f":"七言绝句","c":["午亭春醉耸吟肩，终是风流不愧天。","屑麦调酥慢熬火，牡丹花共菊芽煎。"]},{"t":"春晚杂兴十二首 其三","f":"七言绝句","c":["卖茶犹说有征讥，蕨菜何为入市稀。","往往提篮采山者，怕逢猛虎竟空归。"]},{"t":"春晚杂兴十二首 其二","f":"七言绝句","c":["林下萧然一秃翁，吟髭全白醉颜红。","米盐薪炭时时绝，自古诗人例合穷。"]},{"t":"春晚杂兴十二首 其一","f":"七言绝句","c":["七年守郡罢三年，卖尽山中五顷田。","书籍可捐衣可典，犹能醉面仰看天。"]},{"t":"春寒","f":"七言绝句","c":["灯节萧条雷后雪，花天料峭雨馀霜。","经旬不出无情绪，恰见鹅儿似酒黄。"]},{"t":"秋日","f":"七言绝句","c":["尽日秋园掩竹扉，小堂临砌坐斜晖。","有心觅句无心得，畦叟浇花蚱蜢飞。"]},{"t":"秋日古兰花十首 其十","f":"七言绝句","c":["楚词兰有晦翁注，模写真容本陆玑。","不待花开著囊贮，紫茎绿叶可熏衣。"]},{"t":"秋日古兰花十首 其九","f":"七言绝句","c":["一干一花山谷语，今兰不是古时兰。","重阳菊畔千丝紫，隆准曾孙却解看。"]},{"t":"秋日古兰花十首 其八","f":"七言绝句","c":["雪丝松细紫团栾，今代无人识古兰。","本草图经川续断，今人误作古兰看。"]},{"t":"秋日古兰花十首 其七","f":"七言绝句","c":["纫兰为佩楚忠臣，直道从来不屈身。","为报拖金鸣玉者，如君多是折腰人。"]},{"t":"秋日古兰花十首 其六","f":"七言绝句","c":["椒浆桂酒蕙蒸殽，学子人能诵楚骚。","惟有籍兰无识者，老夫对尔首频搔。"]},{"t":"秋日古兰花十首 其五","f":"七言绝句","c":["大似斯文不遇时，无人采佩世无知。","援琴与鼓猗兰操，五百年间一退之。"]},{"t":"秋日古兰花十首 其四","f":"七言绝句","c":["玉露金风喜乍凉，紫茎绿叶荐秋芳。","今年最好中秋月，更著秋兰月下香。"]},{"t":"秋日古兰花十首 其三","f":"七言绝句","c":["远闻香淡近闻浓，紫穗丝丝吐雪茸。","不识幽人殢姝子，儿曹方醉木芙蓉。"]},{"t":"秋日古兰花十首 其二","f":"七言绝句","c":["可待清秋菊共芳，春苗夏叶已先香。","握兰故事人谁识，夙世庞眉汉署郎。"]},{"t":"秋日古兰花十首 其一","f":"七言绝句","c":["绿叶梢头紫粟攒，离骚经里古秋兰。","时人误唤孩儿菊，惟有诗翁解细看。"]},{"t":"秋后渐凉","f":"七言绝句","c":["楼东清晓起参旗，火伏三金喜应期。","车马尘中犹苦热，故山已是早凉时。"]},{"t":"秋思七言八首 其八","f":"七言绝句","c":["菊殿百花梅第一，重阳节过小春来。","年年岁岁身长健，摆去穷愁醉几杯。"]},{"t":"秋思七言八首 其七","f":"七言绝句","c":["七旬有二传凶问，九月初三记诞辰。","客里偶然逢此日，淮思江望泪痕新。"]},{"t":"秋思七言八首 其六","f":"七言绝句","c":["早遇鹤山先生子，晚登和义郡王门。","静翁道翁两知己，恸哭新坟接旧坟。"]},{"t":"秋思七言八首 其五","f":"七言绝句","c":["郎官己未老秋崖，丞相庚申老讷斋。","己亥□螭竹坡老，吾乡三老挂予怀。"]},{"t":"秋思七言八首 其四","f":"七言绝句","c":["将相共扶黄道日，神仙独隐紫阳山。","云深夜注参同契，身在虚无缥缈间。"]},{"t":"秋思七言八首 其三","f":"七言绝句","c":["大庾岭头梅挂月，居庸关外草连天。","马牛风古不相及，障雾饕风一梦然。"]},{"t":"秋思七言八首 其二","f":"七言绝句","c":["重阳时节黄花近，老子情怀白发新。","点检客囊无一物，江湖七十五年身。"]},{"t":"秋思七言八首 其一","f":"七言绝句","c":["久不作诗诗律废，时须饮酒酒皆悭。","翠微云外宣平宅，一棹归欤隐此山。"]},{"t":"荠菜花","f":"七言绝句","c":["斗草吴王眩越娃，终然输与老陶家。","雪挑霜煮春无尽，不似吾园荠菜花。"]},{"t":"虽然吟五首 其五","f":"七言绝句","c":["屋上炊烟屋下灯，客来汲井具瓶绳。","虽然此是寻常物，不是承平见不能。"]},{"t":"虽然吟五首 其四","f":"七言绝句","c":["大妇银钗小绿裙，采茶洗菜踏溪云。","虽然此是寻常物，一旦无踪为过军。"]},{"t":"虽然吟五首 其三","f":"七言绝句","c":["桑柘阴阴间苧麻，店前下马便斟茶。","虽然此是寻常物，乱后空村没一家。"]},{"t":"虽然吟五首 其二","f":"七言绝句","c":["沽酒人家短竹篱，门前三两牧牛儿。","虽然此是寻常物，军马才过不见之。"]},{"t":"虽然吟五首 其一","f":"七言绝句","c":["林下机声复碓声，时时犬吠又鸡鸣。","虽然此是寻常物，村落闻之即太平。"]},{"t":"送方岩夫四首 其四","f":"七言绝句","c":["紫阳山下一灯寒，曾守桐庐七里滩。","空手去官□一物，诗名聊得继方干。"]},{"t":"送方岩夫四首 其三","f":"七言绝句","c":["巨山蒙仲昔同官，对峙诗家两将坛。","昭武即今闻有子，文星高照七闽寒。"]},{"t":"送方岩夫四首 其二","f":"七言绝句","c":["同姓同年绾左符，岭南万里送孀孤。","先君遗墨今犹在，为问封州有后无。"]},{"t":"送方岩夫四首 其一","f":"七言绝句","c":["河南徙歙徙浮光，逮徙莆田派愈长。","六出长官刺史百，端平最数铁庵方。"]},{"t":"送李震鹤田侄就题其诗集","f":"七言绝句","c":["驷马未多疏受去，竹林且拟阮咸游。","想见天风鹤鸣和，月临蕙帐夜山秋。"]},{"t":"送汪庭芝高士如严州 其二","f":"七言绝句","c":["书符咒水空多事，辟谷熬铅苦用心。","閒读异书痛饮酒，佳时亦复一弹琴。"]},{"t":"送汪庭芝高士如严州 其三","f":"七言绝句","c":["我致仕年死期近，汝出家时生理难。","沧海桑田何可料，一杯别酒莫留残。"]},{"t":"送汪庭芝高士如严州 其一","f":"七言绝句","c":["四海无家只一身，桐江西上访仙真。","七年太守吾聊尔，况汝穷山管道人。"]},{"t":"送徐似之归新城","f":"七言绝句","c":["趁潮小缓转船头，不枉湖山十日留。","喜得阎徐二学士，为传佳句过中州。"]},{"t":"送黟县学官江归上饶石湖精舍","f":"七言绝句","c":["小桃源住饭不足，夜鹤传声趣驾还。","细嚼紫阳山色饱，馋涎犹睨应天山。"]},{"t":"重阳后绝句五首 其五","f":"七言绝句","c":["九月重阳菊未开，十月小春梅又来。","赏过日长添一线，一瓶菊伴一瓶梅。"]},{"t":"重阳后绝句五首 其四","f":"七言绝句","c":["难开笑口忆小杜，今岁江湖雁未飞。","政使菊花无可□，□当烂醉更忘归。"]},{"t":"重阳后绝句五首 其三","f":"七言绝句","c":["九日若无诗与酒，人生如此定凡人。","我师子美牧之者，郪县齐山句尚新。"]},{"t":"重阳后绝句五首 其二","f":"七言绝句","c":["昨朝卯酒醉至酉，不记满斟凡几巡。","莫问担头青蕊菊，且迎座上白衣人。"]},{"t":"重阳后绝句五首 其一","f":"七言绝句","c":["梧桐疏叶间微黄，年例江南未肯凉。","菊自此花三两月，樽前日日是重阳。"]},{"t":"重阳吟五首 其五","f":"七言绝句","c":["战尘漠漠草荒荒，兵过村空菊自黄。","死尽亲知身偶在，干戈丛里见重阳。"]},{"t":"重阳吟五首 其四","f":"七言绝句","c":["衣冠南渡紫微郎，流落天涯事可伤。","不是诗人终不会，乱山深处过重阳。"]},{"t":"重阳吟五首 其三","f":"七言绝句","c":["此身生死国兴亡，摇落年年本是常。","无奈潘郎解悽怨，满城风雨近重阳。"]},{"t":"重阳吟五首 其二","f":"七言绝句","c":["心炎何处不南荒，瘴海烟深有玉堂。","随地著身无得丧，菊花开日即重阳。"]},{"t":"重阳吟五首 其一","f":"七言绝句","c":["射蛇戏马老刘郎，不为乾坤减战场。","三径寒华空怅望，閒居无酒对重阳。"]},{"t":"重赠王相士","f":"七言绝句","c":["是人家有些儿屋，何处山无这个云。","浪走江湖□□□，□边云肯强随君。"]},{"t":"闻谤","f":"七言绝句","c":["脩身可用要人知，暗室孤灯敢自欺。","赤口烧城市有虎，熨平寸地听群儿。"]},{"t":"倚楼二首 其二","f":"七言绝句","c":["楼头独立到昏鸦，尽日丝空小雨斜。","何补乾坤浪生死，青青无数瓦松花。"]},{"t":"倚楼二首 其一","f":"七言绝句","c":["西风迎面晚凉新，略展青铜正幅巾。","独倚阑干偶无事，閒看楼下奕棋人。"]},{"t":"唐侯举摹刊诗卷牟献之文赵子昂字","f":"七言绝句","c":["金马文章坡颍氏，玉堂字画献羲之。","得兼裒施枣此刻，价倍湖州校正诗。"]},{"t":"晓发富阳县","f":"七言绝句","c":["长山砻石片帆斜，小雨初晴日眩沙。","回首遥看富阳县，青烟低罩一丛花。"]},{"t":"桐花","f":"七言绝句","c":["怅惜年光怨子规，王孙见事一何迟。","等閒春过三分二，凭仗桐花报与知。"]},{"t":"浙西园苑","f":"七言绝句","c":["壁间墨客扫龙蛇，所写诗佳字亦佳。","忽见一诗增感慨，吾家宗伯老秋崖。"]},{"t":"海棠花","f":"七言绝句","c":["锦城春色万人迷，饭颗无心著品题。","实不如华谩秾艳，秋霜谁觑海棠梨。"]},{"t":"索云叔新茶","f":"七言绝句","c":["谷雨已过又梅雨，故山犹未致新茶。","清风两腋玉川句，三百团应似太誇。"]},{"t":"衮绣毬花","f":"七言绝句","c":["舞姬初试薄罗衣，趁蝶随蜂玩午晖。","各折一枝入深院，欢声赢得绣毬归。"]},{"t":"读陶集爱其致意于菊者八因作八首 其一 一曰秋菊盈园而持醪靡由","f":"七言绝句","c":["陶公爱菊满园秋，甚欲持醪竟靡由。","世事重华那复尔，无钱更觉少陵愁。"]},{"t":"读陶集爱其致意于菊者八因作八首 其七 七曰秋菊有佳色裛露掇其英","f":"七言绝句","c":["饮酒成诗二十篇，诗成多在菊花边。","秋英掇取枝头露，想见朝朝起卯前。"]},{"t":"读陶集爱其致意于菊者八因作八首 其二 二曰空服九华","f":"七言绝句","c":["金英足可换君骨，绿醑宁当腐我肠。","空服九华无九酝，帝乡何似醉为乡。"]},{"t":"读陶集爱其致意于菊者八因作八首 其八 八曰松菊犹存","f":"七言绝句","c":["种松今世见松老，种菊常年见菊开。","十一月霜花欲槁，巾车岂可更迟回。"]},{"t":"读陶集爱其致意于菊者八因作八首 其三 三曰菊为制颓龄","f":"七言绝句","c":["自性不随黄落去，始能为尔制颓龄。","涪翁具眼曾拈出，我为重吟换鬼听。"]},{"t":"读陶集爱其致意于菊者八因作八首 其五 五曰芳菊开林耀青松冠岩列怀此贞秀姿卓为霜下杰","f":"七言绝句","c":["人间红叶去无踪，膏沐谁为百草容。","霜杰同时谥贞秀，抗衡惟许老蟠龙。"]},{"t":"读陶集爱其致意于菊者八因作八首 其四 四曰尘爵耻虚罍寒华徒自荣","f":"七言绝句","c":["杯空无酒非瓶耻，耻在虚罍敢怨嗟。","想见此翁不憔悴，天寒犹自有荣花。"]},{"t":"读魏鹤山先生渠阳集五首 其五","f":"七言绝句","c":["瀛登湘渡偶皆同，一了乾坤此两翁。","前后身吾虽未信，俱遭权孽肆奸凶。"]},{"t":"读魏鹤山先生渠阳集五首 其四","f":"七言绝句","c":["投荒弥远凶徒炽，出督清之狡计行。","得柄欺君例如此，国亡徒剩正人名。"]},{"t":"读魏鹤山先生渠阳集五首 其三","f":"七言绝句","c":["汉唐台阁画功臣，何似宣尼从祀人。","欲绘两贤继张吕，临邛魏老建安真。"]},{"t":"读魏鹤山先生渠阳集五首 其二","f":"七言绝句","c":["濂翁传到紫阳朱，复见嘉端此大儒。","一论道原一原道，他求伦拟汉唐无。"]},{"t":"读魏鹤山先生渠阳集五首 其一","f":"七言绝句","c":["登门四十九年多，细读公书百遍过。","今岁摘抄靖州作，遁翁堪配不传轲。"]},{"t":"钱舜举瓜画","f":"七言绝句","c":["老钱工作赵昌花，残绿依稀姤五瓜。","正叔晦翁凡六说，始知辅嗣大争差。"]},{"t":"偶书二首 其二","f":"五言绝句","c":["一昨悬车后，蹉跎又五年。","常书乞米帖，犹费买花钱。"]},{"t":"偶书二首 其一","f":"五言绝句","c":["磊落终休矣，艰难晚见之。","罔知当世事，殊悔少年时。"]},{"t":"偶题五言绝句五首 其五","f":"五言绝句","c":["自古有治乱，谁家无是非。","晓床听邻语，琐琐诉寒饥。"]},{"t":"偶题五言绝句五首 其四","f":"五言绝句","c":["为客弹长铗，□□□短衣。","奈何年不肯，五过古来希。"]},{"t":"偶题五言绝句五首 其三","f":"五言绝句","c":["春秋踰致仕，南北粗知名。","有客来相问，如何不治生。"]},{"t":"偶题五言绝句五首 其二","f":"五言绝句","c":["落木包生意，来鸿定去期。","如何萧瑟气，有许楚臣悲。"]},{"t":"偶题五言绝句五首 其一","f":"五言绝句","c":["不寐常攲枕，无言独倚楼。","江淹犹匪恨，庾信始为愁。"]},{"t":"寄同年宗兄桐江府判去言五首 其五","f":"七言绝句","c":["好山多处说严陵，官事閒时定一登。","野寺岂无僧十百，爱僧须是爱诗僧。"]},{"t":"寄同年宗兄桐江府判去言五首 其四","f":"七言绝句","c":["子陵滩上一诗翁，七十四年双耳聋。","第一老穷吟第一，一樽时与酹江风。"]},{"t":"寄同年宗兄桐江府判去言五首 其三","f":"七言绝句","c":["不识康庐真刺史，可怜德祐假平章。","木绵老鬼死遗臭，万古秋崖姓字香。"]},{"t":"寄同年宗兄桐江府判去言五首 其二","f":"七言绝句","c":["秋崖犹子蛟峰弟，同榜三人老弟兄。","君玉中尝辞直指，去言晚乃佐专城。"]},{"t":"寄同年宗兄桐江府判去言五首 其一","f":"七言绝句","c":["联翩同挂别闱名，尚得秋崖病体轻。","三十四年如一瞬，梦中时见老先生。"]},{"t":"寄阎承旨靖轩","f":"七言绝句","c":["相逢偶值寄梅人，今岁江南暖未匀。","报与玉堂真学士，小诗聊当一枝春。"]},{"t":"寄题休宁赵氏云屋省心翠侍问道亭有有堂五首 其五","f":"七言绝句","c":["贯朽青钱粟腐红，何如心不愧天公。","一方寸里无馀物，却笑敖仓武库穷。"]},{"t":"寄题休宁赵氏云屋省心翠侍问道亭有有堂五首 其四","f":"七言绝句","c":["三叉路口驻车轮，莫讶知津更问津。","何限出门向西笑，忙行不似慢行人。"]},{"t":"寄题休宁赵氏云屋省心翠侍问道亭有有堂五首 其三","f":"七言绝句","c":["青疏老瘦碧孱颜，杳杳深深万翠间。","侍坐侍行仍侍立，雪松霜竹雨馀山。"]},{"t":"寄题休宁赵氏云屋省心翠侍问道亭有有堂五首 其二","f":"七言绝句","c":["心属何人省者谁，自家主宰自家知。","从来此地惺惺处，不要医工用药医。"]},{"t":"寄题休宁赵氏云屋省心翠侍问道亭有有堂五首 其一","f":"七言绝句","c":["不品官班但品人，深云藏屋屋藏身。","就中别有难藏者，名震京师郑子真。"]},{"t":"寄题陈公辅听雨轩","f":"七言绝句","c":["知时润物最关心，不作珠帘暮捲吟。","龙过惊回攲枕梦，檐声点点是商霖。"]},{"t":"寄题感应夫人庙","f":"七言绝句","c":["观世音化马郎妇，西王母嘲方朔儿。","乾坤大幻万千变，□我敬之而远之。"]},{"t":"寄赠介石沈高士 其一","f":"七言绝句","c":["荦确崎岖峭壁间，险过巫峡更潼关。","石头莫待微相磕，便合收心早早还。"]},{"t":"寄赠介石沈高士 其二","f":"七言绝句","c":["两边巇险我居中，岂可挨西又捺东。","冷笑主人忘曲突，泥梁燕燕说春风。"]},{"t":"惜砚中花","f":"七言绝句","c":["花担移来锦绣丛，小窗瓶水浸春风。","朝来不忍轻磨墨，落砚香粘数点红。"]},{"t":"探菊二首 其二","f":"七言绝句","c":["心最怜渠旱菊苗，蕊青如粟间如椒。","小劳汲井何妨事，有酒吾当着酒浇。"]},{"t":"探菊二首 其一","f":"七言绝句","c":["秋旱今年冷意乖，将无断送老生涯。","山田百谷俱焦槁，一雨何妨为菊花。"]},{"t":"断桥西人家三首 其三","f":"七言绝句","c":["望极苏堤欲尽头，丛篁老柳水天秋。","船中遥看家家好，却恐君来住亦愁。"]},{"t":"断桥西人家三首 其二","f":"七言绝句","c":["主人傥不粗能吟，辜负湖天水竹林。","我若移家来此住，诗人无数日相寻。"]},{"t":"断桥西人家三首 其一","f":"七言绝句","c":["无数菰蒲间藕花，万丝垂柳曳风斜。","竹篱茅舍浑如画，最爱桥西第一家。"]},{"t":"晚春客愁五绝 其一","f":"五言绝句","c":["江外芦芽老，城中柳絮飞。","春风犹几日，谁与濯征衣。"]},{"t":"晚春客愁五绝 其五","f":"五言绝句","c":["老身何可病，客舍只宜晴。","晓鼎催煎药，窗间又雨声。"]},{"t":"晚春客愁五绝 其三","f":"五言绝句","c":["想归归未得，悔醉醉还频。","不料湓江上，题诗送晚春。"]},{"t":"晚春客愁五绝 其二","f":"五言绝句","c":["春老鱼苗动，江肥雪水来。","大孤山下路，何日泛舟回。"]},{"t":"晚春客愁五绝 其四","f":"五言绝句","c":["十载干戈后，辛勤莳牡丹。","岂知身是客，借与别人看。"]},{"t":"望西太乙宫四圣观半为僧寺","f":"七言绝句","c":["红墙半旧粉墙新，泥塑金涂各有神。","僧道不须閒计较，等为和靖守坟人。"]},{"t":"梨花","f":"七言绝句","c":["仙姿白雪帔青霞，月淡春浓意不邪。","天上嫦娥人未识，料应清雅似梨花。"]},{"t":"淳熙戊申丘寿隽新昌石氏本","f":"七言绝句","c":["颇如画手善传神，绝喜他乡见似人。","俯仰之间已陈迹，如何千载尚如新。"]},{"t":"淳熙甲午东阳郡斋兰亭","f":"七言绝句","c":["大唐天子绐孤僧，转瞬人间几废兴。","一幅永和故茧纸，入昭陵又出昭陵。"]},{"t":"淳熙癸卯钱伸东阳本","f":"七言绝句","c":["永和贞观晋沿唐，奉诏临摹老遂良。","展转流传非一手，虎贲犹得似中郎。"]},{"t":"清江濯手","f":"七言绝句","c":["属镂愤气已销平，江入新安水至清。","净洗长安遮日手，更容尘土到冠缨。"]},{"t":"清明大雪三日","f":"七言绝句","c":["半月雕梁燕子归，怯寒著尽旧绵衣。","何人醉眼西湖路，错认杨花作雪飞。"]},{"t":"清湖早春 其一","f":"七言绝句","c":["晓窗初起望春云，天色阴晴未十分。","小雨漫空浑不觉，平湖点点见圆纹。"]},{"t":"清湖早春 其二","f":"七言绝句","c":["岸边老树柳犹枯，红入桃花果有无。","一夜绿从冰底起，谁将蓝汁染晴湖。"]},{"t":"清湖春早二首 其二","f":"七言绝句","c":["楼上春阴覆晓云，一河天净碧沄沄。","雨宜不骤风宜细，閒倚阑干看水纹。"]},{"t":"清湖春早二首 其一","f":"七言绝句","c":["半河楼影半河天，未有行人趁早船。","閒听卖花声自好，可须多费买花钱。"]},{"t":"猗兰秋思三首 其三","f":"七言绝句","c":["老子今年忽不贫，价方玉佩有兰纫。","一枝半朵悬衣带，肯羡腰间大羽人。"]},{"t":"猗兰秋思三首 其二","f":"七言绝句","c":["绿叶枝头紫粟丛，素花抽雪细茸茸。","国香政要枯如腊，旋买离骚置册中。"]},{"t":"猗兰秋思三首 其一","f":"七言绝句","c":["猗兰奕叶晓疏晴，栩栩秋光小蝶轻。","皂翅绣花三五点，庾郎无句画难成。"]},{"t":"野庙","f":"七言绝句","c":["金甲朱衣画壁昏，军声不到暂开门。","数家祈福来浇奠，剪纸糊灯作上元。"]},{"t":"雪条花","f":"七言绝句","c":["槁若丛蓍未见妍，一条条雪半春天。","醉鞍把玩归来晚，蒲市人惊玉马鞭。"]},{"t":"黄浦门解缆有怀川无竭","f":"七言绝句","c":["旧守烦人送酒钱，江边五夜泊归船。","就中最忆南山好，一老癯僧伴醉颠。"]},{"t":"黄蔷薇花","f":"七言绝句","c":["春工借露染莺裳，欲学东篱一样黄。","输与菊花在何处，止禁晴暖不禁霜。"]},{"t":"寓意","f":"七言绝句","c":["季路三都不尽隳，城狐尚许脱阽危。","一日西家鼠运去，太丘忽有社亡时。"]},{"t":"湖口阻风","f":"七言绝句","c":["涛江白雪喷苍旻，晚日红金缘翠云。","天著此奇刮诗眼，略须掇实张吾军。"]},{"t":"湖山堂再修仅有","f":"七言绝句","c":["飞鸟穿堂柱半攲，春晴犹不似春时。","上梁文记临邛魏，天目洪家却立碑。"]},{"t":"湖曲细嚼梅花咽酒","f":"七言绝句","c":["梅心微苦似梅仁，细嚼香须酒入唇。","笑指逋仙坟上土，一杯好与酹芳辛。"]},{"t":"猴牛尾狸图","f":"七言绝句","c":["宣城牛尾雪天狸，梅老馋涎为赋诗。","曾与沐猴戏相得，脂膏争奈猎人知。"]},{"t":"登上竺兴福寺新阁五首 其五","f":"七言绝句","c":["燕蛰蜂瘖菊始开，秋凉入骨病堆豗。","吟僧欲约山中宿，后夜须携絮被来。"]},{"t":"登上竺兴福寺新阁五首 其四","f":"七言绝句","c":["乳窦峰前路不穷，穿林踰岭浙江通。","紫阳山雨钓台月，消得潮头几信风。"]},{"t":"登上竺兴福寺新阁五首 其三","f":"七言绝句","c":["跳过西湖万万重，半天蓬鬓洗松风。","自惭不得留终日，又向船中入市中。"]},{"t":"登上竺兴福寺新阁五首 其二","f":"七言绝句","c":["面面峰峦杰阁新，好山借我倚栏身。","商量壁记留名易，未是题诗第一人。"]},{"t":"登上竺兴福寺新阁五首 其一","f":"七言绝句","c":["狮子峰高侧见巅，怒飞危欲堕檐前。","千松万竹阑干畔，瘦骨秋寒似雪天。"]},{"t":"紫荆花","f":"七言绝句","c":["疏枝坚瘦骨为皮，忽迸红英簇紫蕤。","娇女乍看齿生液，分明茜糁缀饧枝。"]},{"t":"谢客二首 其二","f":"七言绝句","c":["时脱蓑衣当酒钱，江天身世一渔船。","七旬衰老人无识，林下休官十五年。"]},{"t":"谢客二首 其一","f":"七言绝句","c":["梦到红云玉殿来，骨凡无路住蓬莱。","鹤身欲向仙官舞，病翅缡褷展不开。"]},{"t":"跋吴初邻山谷临风笛真迹","f":"七言绝句","c":["临风玉笛调孙郎，百字尘昏纸尚香。","细认黄家元祐脚，似人殊喜见他乡。"]},{"t":"跋张明府独乐园图二首 其二","f":"七言绝句","c":["独乐人闻新法新，定应翻作独愁人。","墓碑一仆党碑立，已觉园花埋战尘。"]},{"t":"跋张明府独乐园图二首 其一","f":"七言绝句","c":["熙宁相住半山寺，元祐人宗独乐园。","早起庵中钓鱼手，未应宣靖失中原。"]},{"t":"跋郝仲雨游梁百韵","f":"七言绝句","c":["读君百咏魏中梁，始僭诸侯又僭王。","孟子两言无识者，六王亡更七王亡。"]},{"t":"□□□ 其二","f":"七言绝句","c":["句圆字稳削陈言，诗律吾曹合细论。","五藁端能压南岳，后村死后有前村。"]},{"t":"集贤堂已无","f":"七言绝句","c":["旧日三贤又集贤，看人歌舞过湖船。","一时去取非公论，到底终难昧老天。"]},{"t":"新晴","f":"七言绝句","c":["女伴新晴喜晒衣，老人閒步览春晖。","隔篱一树桃花发，初见今年粉蝶飞。"]},{"t":"瑞云院大树林中二首 其二","f":"七言绝句","c":["万万松杉万竹枝，人间应是少人知。","数僧潇洒相逢处，一鹤昂藏独立时。"]},{"t":"瑞云院大树林中二首 其一","f":"七言绝句","c":["城中遥望万重云，今日蝉声始一闻。","略计此山松竹数，汉时应比百封君。"]},{"t":"漫兴九首 其二","f":"五言绝句","c":["老岂堪从仕，穷应不为诗。","死生元有命，病亦莫求医。"]},{"t":"漫兴九首 其五","f":"七言绝句","c":["阴阴白昼似昏黄，平地愁城万里长。","稻卧三秋常是雨，菊残十月尚无霜。"]},{"t":"漫兴九首 其七","f":"五言绝句","c":["袍絮无堪换，柴钱久未还。","有人来问字，赊酒醉花间。"]},{"t":"漫兴九首 其四","f":"七言绝句","c":["饿信黥英遇汉皇，攀龙附凤化侯王。","河豚鱼毒亡身耳，何至身亡族亦亡。"]},{"t":"漫兴九首 其三","f":"五言绝句","c":["我欲培修竹，新添笋几根。","徘徊看不已，爱惜似儿孙。"]},{"t":"漫兴九首 其二","f":"七言绝句","c":["汹汹战场元不惧，恓恓贫巷亦无忧。","千金浪费如泥土，今日何人识故侯。"]},{"t":"漫兴九首 其九","f":"五言绝句","c":["欲跨羸骖去，江村访酒家。","杖头无阿堵，肯听锦囊赊。"]},{"t":"漫兴九首 其五","f":"五言绝句","c":["静院幽花馥，空庭皓月明。","春寒夜更好，未有一虫鸣。"]},{"t":"漫兴九首 其一","f":"五言绝句","c":["索文僧送纸，赌酒客争棋。","定要全无事，何由更有诗。"]},{"t":"漫兴九首 其九","f":"七言绝句","c":["新莽穷奸卓极凶，奸人更有阿瞒雄。","纷纷竖子成何事，野火山林一烧空。"]},{"t":"漫兴九首 其六","f":"五言绝句","c":["索果娇儿怒，胹羹老仆顽。","欲嗔仍复笑，掩卷看南山。"]},{"t":"漫兴九首 其三","f":"七言绝句","c":["才到黄花有酒倾，今人动欲作渊明。","瓶无储粟夜无被，此事知君学未成。"]},{"t":"漫兴九首 其八","f":"五言绝句","c":["淡齑淘大麦，甘酪荐含桃。","风调谁优劣，田家似颇高。"]},{"t":"漫兴九首 其七","f":"七言绝句","c":["向人开口便言閒，每一题诗便说山。","请俸坐曹食粱肉，又闻满考转官班。"]},{"t":"漫兴九首 其一","f":"七言绝句","c":["吐纳谁能较故新，更须大药锻金银。","有诗传世书传子，自是人间不死人。"]},{"t":"漫兴九首 其六","f":"七言绝句","c":["枕上半醒中酒病，楼前时过卖花声。","千门万户俱更换，惟此依稀旧太平。"]},{"t":"碧桃花","f":"七言绝句","c":["一种玄都旧种花，谁将缟雪换蒸霞。","群仙醉啖瑶池果，况核曾封白玉砂。"]},{"t":"鄱阳汤仲材以其家息庵存斋东涧三大老鄂州黄龙寺僧惠璋入石诗装为一轴求士大夫赞颂紫阳山下方回之先人字元章嘉定甲戌与晦静先生同年为下偈言而不及此意可乎仲材能作祇夜回作伽佗可也 其三","f":"七言绝句","c":["晦静先生甲戌榜，元章先子幸同年。","升沈一付六如梦，休赋青云紫陌篇。"]},{"t":"鄱阳汤仲材以其家息庵存斋东涧三大老鄂州黄龙寺僧惠璋入石诗装为一轴求士大夫赞颂紫阳山下方回之先人字元章嘉定甲戌与晦静先生同年为下偈言而不及此意可乎仲材能作祇夜回作伽佗可也 其二","f":"七言绝句","c":["息存东涧三汤老，文我平生尽见之。","身到黄龙山几度，却惭欠读惠璋碑。"]},{"t":"鄱阳汤仲材以其家息庵存斋东涧三大老鄂州黄龙寺僧惠璋入石诗装为一轴求士大夫赞颂紫阳山下方回之先人字元章嘉定甲戌与晦静先生同年为下偈言而不及此意可乎仲材能作祇夜回作伽佗可也 其四","f":"七言绝句","c":["水绕芝山过紫阳，倒流不解上南昌。","两家俱有传灯子，始信真源气脉长。"]},{"t":"鄱阳汤仲材以其家息庵存斋东涧三大老鄂州黄龙寺僧惠璋入石诗装为一轴求士大夫赞颂紫阳山下方回之先人字元章嘉定甲戌与晦静先生同年为下偈言而不及此意可乎仲材能作祇夜回作伽佗可也 其一","f":"七言绝句","c":["黄鹤矶头百战尘，黄龙诗刻尚如新。","终然岘首碑安在，羊祜元非死朽人。"]},{"t":"酴醾花","f":"七言绝句","c":["未用炉薰燃笃耨，何须粉面佐娉婷。","通宵痛饮此花下，露滴杯中酒更醒。"]},{"t":"酴醾盛开二绝 其二","f":"七言绝句","c":["雪色联飞蝶过廊，乌衣交语燕归梁。","酴醾花下午酲解，春静人閒白日长。"]},{"t":"酴醾盛开二绝 其一","f":"七言绝句","c":["罗雀閒门未寂寥，小园花事自春饶。","日葵霜菊踰千本，更有酴醾十万条。"]},{"t":"樱桃花","f":"七言绝句","c":["浅浅花开料峭风，苦无妖色画难工。","十分不肯精神露，留与他时著子红。"]},{"t":"蕙花","f":"七言绝句","c":["药辨君臣医或误，花旌王后俗徒奢。","早兰晚蕙真兄弟，我与二难分等差。"]},{"t":"题王义之云隐","f":"七言绝句","c":["心天界限绝尘氛，廛市虽喧耳不闻。","大隐从来非小隐，可须深入万重云。"]},{"t":"题王春阳效王晋卿山水图","f":"七言绝句","c":["烟江叠嶂子能学，都尉后身王姓同。","诗画惊逢两奇丽，赏音吾愧玉堂翁。"]},{"t":"题王起宗大横披水墨作远淡势","f":"七言绝句","c":["卧龙峰下草庐幽，门外桥横水自流。","潇洒王郎只数笔，淡云疏树一天秋。"]},{"t":"题王起宗小横披水墨作工密势","f":"七言绝句","c":["秋光一片冷于冰，山寺云深隐几僧。","画出江村太平意，渔樵无事岁丰登。"]},{"t":"题叶兰坡居士兰","f":"七言绝句","c":["一花一干秀春风，此论黄家太史公。","若问灵均旧纫佩，零陵香出古湘中。"]},{"t":"题龙虎山高士毛和叔愚泉诗稿","f":"七言绝句","c":["暂住身如鹤在松，忽然飞去又无踪。","閤皂山头曾不睡，夜寒看月到晨钟。"]},{"t":"题孙廷玉藏李仲宾墨竹","f":"七言绝句","c":["仲宾笔底招君子，廷玉胸中敬正人。","更著紫阳虚叟句，两公烱烱见精神。"]},{"t":"题江君天泽古脩堂三首 其三","f":"七言绝句","c":["文言当日演韦编，夕惕爻观变兑乾。","进德立诚说方法，定曾参到杏坛前。"]},{"t":"题江君天泽古脩堂三首 其二","f":"七言绝句","c":["尧付诸冯药一丸，养心谁续执中丹。","三千年后人能服，圣处工夫似不难。"]},{"t":"题江君天泽古脩堂三首 其一","f":"七言绝句","c":["大虚空重片光悬，何异初开混沌天。","能办辛勤磨玉斧，不愁缺月不团圆。"]},{"t":"题米元晖寒林","f":"七言绝句","c":["善书善画古来希，前辈风流日渐微。","开卷令人忆羲献，米元章更米元晖。"]},{"t":"题许宣平南山故居","f":"七言绝句","c":["一庵依旧翠微中，身在蓬莱第几宫。","羽卫夜归人不识，满山松桧响清风。"]},{"t":"题达磨渡江画","f":"七言绝句","c":["祖灯传到老卢奴，解道元来一物无。","葱岭笑伊携只履，渡江更要一枝芦。"]},{"t":"题冻雀著色梅花","f":"七言绝句","c":["一枝玉蕊艳□□，□雀双跧冻翼香。","谁识绿毛挂么凤，坡仙诗眼醉南□。"]},{"t":"题吴山长文英野舟五首 其五","f":"七言绝句","c":["世多汉水昭王事，谁辨乌江亭长心。","君知此处真堪托，天下无波可得深。"]},{"t":"题吴山长文英野舟五首 其四","f":"七言绝句","c":["大才定复不求售，至宝政须能自珍。","一篙用著方知贵，只恐悠悠懒问津。"]},{"t":"题吴山长文英野舟五首 其三","f":"七言绝句","c":["我有孤舟自天地，沙头问渡苦无人。","谁家贾舶浮溟渤，脱命蛟龙亦损神。"]},{"t":"题吴山长文英野舟五首 其二","f":"七言绝句","c":["下邽老子扶黄屋，直上澶州城北楼。","辽阳铁骑惊相问，旧日巴东野水舟。"]},{"t":"题吴山长文英野舟五首 其一","f":"七言绝句","c":["春潮滞雨横舟晚，成就苏州一段奇。","向使有人争此渡，韦郎眼底定无诗。"]},{"t":"题庐山白莲社十八贤图","f":"七言绝句","c":["六老臞儒十二僧，柴桑醉士肯为朋。","葫芦自与葫芦缠，更要閒人缠葛藤。"]},{"t":"题李仲宾竹二幅","f":"七言绝句","c":["可是笔端如与可，亦须胸次有东坡。","自从举世誇崔白，似觉无人识李颇。"]},{"t":"题李伯时赤脚仙","f":"七言绝句","c":["可是驴蹄复马蹄，忍将玉雪污污泥。","世情巇险君知否，满地人间铁蒺藜。"]},{"t":"题杨叔雅水墨百花图","f":"七言绝句","c":["梅梢前后两枝春，百世中间各写真。","忽见花王大如斗，始知天地有君臣。"]},{"t":"题陆君雁鹭图","f":"七言绝句","c":["菰米飘香白小肥，汀鸿沙鹭狎晴晖。","太湖天接吴松阔，莫近能言鸭畔飞。"]},{"t":"题陈正之兰亭","f":"七言绝句","c":["十六回更癸丑春，兰亭临本尚如新。","学书良易人难学，聊喜他乡见似人。"]},{"t":"题坡仙求心斋三字","f":"七言绝句","c":["千圣相传止一机，常惺惺法免危微。","但于方寸求吾事，莫问坡书是与非。"]},{"t":"题画马","f":"七言绝句","c":["刍秣丰肥十二闲，笔追韩干此图间。","谁描驴瘦更诗瘦，首与双肩共一山。"]},{"t":"题罗云叔周昉宫女","f":"七言绝句","c":["颠倒三郎养禄儿，当年想是此蛾眉。","不须真有聊须画，或可东城出一奇。"]},{"t":"题宣和黄头画","f":"七言绝句","c":["石绿藤黄间麝煤，半枯瘦筱羽毰毸。","一时艮岳天颜笑，乞与宣和印押来。"]},{"t":"题唐人按乐图","f":"七言绝句","c":["鼓笛笙箫鬨舞茵，伶官和尚杂宫人。","黄番绰共唐三藏，彷佛相传未必真。"]},{"t":"题徐赞府不负堂 其一","f":"七言绝句","c":["哦松人与职俱清，时见春郊雨又晴。","所学政应如陆九，只消一语了平生。"]},{"t":"题徐赞府不负堂 其二","f":"七言绝句","c":["官无大小各分忧，可但专为七尺谋。","说著此身便非是，寄声多谢薛嘉州。"]},{"t":"题钱选木芙蓉","f":"七言绝句","c":["东篱相伴殿西风，我识花神品藻公。","秋老别无第三品，傲霜黄处拒霜红。"]},{"t":"题钱舜举著色山水","f":"七言绝句","c":["堆青积翠耸□□，□□峥嵘古寺深。","此画老钱暮年笔，真成一纸直千金。"]},{"t":"题陶介夫见山轩 其二","f":"五言绝句","c":["湖上山如故，湖边客总非。","容堂今不见，凉夜草萤飞。"]},{"t":"题陶介夫见山轩 其一","f":"五言绝句","c":["湖上山如画，何人解见山。","此心无一事，尽日捲帘间。"]},{"t":"题戚子云五云山图","f":"七言绝句","c":["不浓不淡烟中树，如有如无雨外山。","尺素展看空想像，何由身著画图间。"]},{"t":"题曹舍人文龙墨竹扇仲宾息斋写","f":"七言绝句","c":["文湖州笔欠坡诗，便面潇潇雨一枝。","暑汗轻摇骨□□，□间谁识庾元规。"]},{"t":"题黄君以发拟文公书院梁文及赋","f":"七言绝句","c":["滔天笔势百川东，小待清霜万壑空。","能草子虚上林赋，更须收敛入檀弓。"]},{"t":"赠小窗黄君","f":"七言绝句","c":["浑天星斗胸中转，动地风雷舌上生。","想见少年读书夜，短檠膏尽小窗明。"]},{"t":"赠五星梅獬孙","f":"七言绝句","c":["运极螟蛉绍雀儿，太平早有窦郎知。","市门屠贩规温饱，何足烦君子细推。"]},{"t":"赠学易耕心","f":"七言绝句","c":["佛书曾画牛犁舌，以易耕心却不然。","一寸地中栽□□，□将三寸舌谈天。"]},{"t":"赠范君用笔工五首 其四","f":"七言绝句","c":["未誇长管入手便，政须短管护铦锋。","未染濡时常著帽，忽□脱帽走蛟龙。"]},{"t":"赠范君用笔工五首 其一","f":"七言绝句","c":["汉庭上方斩马剑，子制毛锥端似之。","未办朱云请此物，笔诛市挞佞臣谁。"]},{"t":"赠相士王秀溪","f":"七言绝句","c":["不惜佳人国为倾，髑髅头盖野狐精。","丈夫更有何郎粉，老眼须君业镜明。"]},{"t":"赠相士戚淳祖","f":"七言绝句","c":["朝匹吴君暮越臣，一颦何用訾东邻。","阿承丑女五噫妇，似胜苧萝山下人。"]},{"t":"赠砚工杨全","f":"七言绝句","c":["人间渐少老书生，真赝谁能别旧坑。","磨墨挥毫自奇怪，可须一砚苦求精。"]},{"t":"赠高相士二首 其二","f":"七言绝句","c":["贩商公事名才吏，钞掠平人号战多。","相貌奇厖心惨刻，天生此辈欲如何。"]},{"t":"赠高相士二首 其一","f":"七言绝句","c":["武安何谓锐头将，贞观才无福手民。","世上封侯人不少，封侯人是杀人人。"]},{"t":"赠数学吴桂子","f":"七言绝句","c":["先天有数妙蓍龟，诧鬼誇神满卷诗。","独一许翁可吾意，预占晴色赏酴醾。"]},{"t":"蟏蛸","f":"七言绝句","c":["窗眼蟏蛸粟许微，早能结网伺虫飞。","都来口腹容多少，狼虎操心伏杀机。"]},{"t":"一笑","f":"七言律诗","c":["棘为篱落板为扉，堂上春山碧四围。","前后相承花百种，往来自在燕双飞。","卖田不耻因偿债，耽酒无厌更典衣。","人道家贫诗却富，先生一笑久忘机。"]},{"t":"乙巳三月十五日监察御史王东溪节宿戒方回万里饮灵隐冷泉亭赵宣慰君实赵提举子昂灵隐寺知事晦坛治具西方僧四人两提领北人放泉喷雪观猿掷果予醉先退赋诗五首记之 其三","f":"七言律诗","c":["世间春暖此间寒，万树阴阴万竹攒。","骢马来游人不避，画龙谁写我频看。","馀生久已忘三黜，高会犹容预四难。","閒赏孤山梅五绝，樽前剩爱一枝酸。"]},{"t":"乙巳三月十五日监察御史王东溪节宿戒方回万里饮灵隐冷泉亭赵宣慰君实赵提举子昂灵隐寺知事晦坛治具西方僧四人两提领北人放泉喷雪观猿掷果予醉先退赋诗五首记之 其五","f":"七言律诗","c":["三月晴过半月春，真成好景与良辰。","簪花骑马多游女，掷果呼猿不畏人。","湖山行乐有心赏，天地太平无战尘。","两纪逃名作閒客，乐哉七十九年身。"]},{"t":"乙巳三月十五日监察御史王东溪节宿戒方回万里饮灵隐冷泉亭赵宣慰君实赵提举子昂灵隐寺知事晦坛治具西方僧四人两提领北人放泉喷雪观猿掷果予醉先退赋诗五首记之 其二","f":"七言律诗","c":["渊静涛飞亦壮哉，冷泉亭右闸初开。","一时变作跳空雪，万众惊闻喷壑雷。","老鹤远过彭祖寿，巨杉何啻盛唐栽。","吾生八十重游此，身健犹堪酒一杯。"]},{"t":"乙巳三月十五日监察御史王东溪节宿戒方回万里饮灵隐冷泉亭赵宣慰君实赵提举子昂灵隐寺知事晦坛治具西方僧四人两提领北人放泉喷雪观猿掷果予醉先退赋诗五首记之 其一","f":"七言律诗","c":["年年时节美春三，谁识湖山绿似蓝。","万户栋梁双语燕，千村桑柘两眠蚕。","鼓钟下竺寺连上，香火北高峰胜南。","除却咸平处士外，何人更此筑吟庵。"]},{"t":"乙巳三月十五日监察御史王东溪节宿戒方回万里饮灵隐冷泉亭赵宣慰君实赵提举子昂灵隐寺知事晦坛治具西方僧四人两提领北人放泉喷雪观猿掷果予醉先退赋诗五首记之 其四","f":"七言律诗","c":["休兵三十有馀龄，铁马曾来似不曾。","寒士喜从贤御史，閒人许识老名僧。","画船处处歌春雪，厦屋遥遥贮腊冰。","保得西湖如此好，心知明首遇良肱。"]},{"t":"乙未十二月二十四日立丙申春予忝七十","f":"七言律诗","c":["十岁端平旧丙申，元贞重见丙申春。","几灾几难到今日，诸父诸兄皆古人。","未及悬车官已解，不能负贩子俱贫。","细思多少同庚者，地下先埋富贵身。"]},{"t":"乙未六月大暑","f":"五言律诗","c":["平分天四序，最苦是炎蒸。","在我须无欲，于斯患不能。","又应当闵雨，谁识始藏冰。","人力回元造，生生实所凭。"]},{"t":"乙未生日二首 其二","f":"七言律诗","c":["虚叟惭非饮八仙，举杯属客每陶然。","重逢今日初生日，预算明年致仕年。","元亮有儿聊慰意，斛斯为话且随缘。","老衰不竞黄陈律，前日诗如白乐天。"]},{"t":"乙未生日二首 其一","f":"七言律诗","c":["南北间关万死身，今年六十九年人。","偶容有酒仍容健，不叹无官肯叹贫。","遣礼送诗烦故旧，借楼市馔请比邻。","还闻共说虚翁寿，似陆严州过八旬。"]},{"t":"乙未岁除二首 其二","f":"七言律诗","c":["五十五时官早休，即今七十复何求。","亦思稍为儿孙计，政恐深贻祖父羞。","岂不忆家良有说，偶然得酒更无忧。","诸公富贵新桃版，我是春前旧土牛。"]},{"t":"乙未岁除二首 其一","f":"七言律诗","c":["岂料身为七十翁，开怀且放醉颜红。","身存惟恨恩难报，世换还惊事总空。","百岁尚馀三帙数，万诗枉费一生工。","盍簪列炬浑如梦，不似今年筑底穷。"]},{"t":"丁亥十一月初八日南至二首 其二","f":"七言律诗","c":["涉险骑危一纪强，四惊阳复寓钱塘。","山深黟歙生涯薄，水溢苏湖岁事荒。","暂遣归宁怜小婢，尚迟绝少抚诸郎。","官壶岂似无灰酒，有客携来亦尽觞。"]},{"t":"丁亥十一月初八日南至二首 其一","f":"七言律诗","c":["閒客何庸早起忙，高眠懒复问云祥。","宦情不作葭灰动，吟笔宁争绣线长。","逆旅四年逢此节，徒行六日可吾乡。","冲风踏雪须归去，荠菜肥甜白酒香。"]},{"t":"丁亥元日二首 其二","f":"五言律诗","c":["孰不闻钟起，吾犹拥褐眠。","家人分两地，客邸跨三年。","果蓏思携幼，粢盛忆祀先。","故山归去好，当及挂灯前。"]},{"t":"丁亥元日二首 其一","f":"五言律诗","c":["元日如常日，閒人更老人。","后杯真寿酒，便服胜朝绅。","何物称三品，今朝过六旬。","候门怜稚子，莫放杏梢春。"]},{"t":"丁亥生日纪事五首 其五","f":"七言律诗","c":["杯酒谁欤可共挥，残年心事转多违。","颇闻铜柱征蛮急，孰念葵丘遏籴非。","典质衣裳今已尽，留连舟楫可无归。","故园堪共吾儿灌，政恐淫霖岁亦饥。"]},{"t":"丁亥生日纪事五首 其四","f":"七言律诗","c":["先君俊誉早飙驰，晚落蛮陬祸事奇。","六十年前生子日，三千里外忆亲时。","霍光擅汉人皆恐，侯景归梁国欲危。","埋骨瘴烟抱冤愤，蓬莱水浅定前知。"]},{"t":"丁亥生日纪事五首 其三","f":"七言律诗","c":["我生之日忆我父，痛甚少游眠古藤。","忍见金汤今堕甑，劣容诗礼尚传灯。","策名作郡了无益，罔利肥家终不能。","决定归欤守先墓，种瓜聊得似东陵。"]},{"t":"丁亥生日纪事五首 其二","f":"七言律诗","c":["山路访僧规已定，晓楼闻雨事还非。","今年生日无人识，几度儿曹望我归。","清茗半瓯浮雪乳，古香一剂炷烟霏。","割牲酾酒贫难办，只待天晴浣虱衣。"]},{"t":"丁亥生日纪事五首 其一","f":"七言律诗","c":["千世谋生百念捐，穷空肯复受人怜。","九还未悟长生诀，七帙初开本命年。","寡欲自来甘淡薄，忘机时或放狂颠。","归舟已办赍粮绝，犹欲经营买鹤钱。"]},{"t":"丁酉生日二首 其二","f":"七言律诗","c":["未苏残醉茗频煨，夙荷诸公载酒来。","照镜所存唯雪鬓，典衣已尽况银杯。","色婴单豹偶然耳，带索启期焉怨哉。","弱水元无三万里，此心安处是蓬莱。"]},{"t":"丁酉生日二首 其一","f":"七言律诗","c":["今年五月冷非常，拥袖无聊一老尪。","应俗但宜司马好，全生不必次公狂。","绛人甲子差相近，皇考庚寅暗自伤。","病酒客楼听泥屐，愁边更用雨淋浪。"]},{"t":"七十翁五言十首 其十","f":"五言律诗","c":["紫阳山下住，问字足儒生。","鲜果枝头熟，新醅瓮面清。","学师朱仲晦，诗友许宣平。","焉得孟能静，沧浪共濯缨。"]},{"t":"七十翁五言十首 其九","f":"五言律诗","c":["诗家自有律，高处在平中。","能使生为熟，何愁拙不工。","严祠七里濑，汉鼎一丝风。","敢谓方虚叟，还如陆放翁。"]},{"t":"七十翁五言十首 其八","f":"五言律诗","c":["父母嗟难报，乾坤荷曲成。","居然生寿相，颇亦窃诗名。","箕子九畴范，太公三略兵。","老身宁坎止，时彦或流行。"]},{"t":"七十翁五言十首 其七","f":"五言律诗","c":["故人书见问，近况复如何。","酒病沉绵剧，诗愁感慨多。","胫枯全似鹤，髻小仅如螺。","更许十年活，渔矶破几蓑。"]},{"t":"七十翁五言十首 其六","f":"五言律诗","c":["只影兼孤喙，攒眉更结喉。","一生无大喜，万种有閒愁。","冠豸羞言路，凭熊齿郡侯。","休官十六载，不报破家雠。"]},{"t":"七十翁五言十首 其五","f":"五言律诗","c":["七堠长亭路，前程已不多。","最欺吾老者，绝奈后生何。","去晚陶弘景，迷凶马伏波。","幸逢黄菌耦，且赋紫芝歌。"]},{"t":"七十翁五言十首 其四","f":"五言律诗","c":["瘴疠金蚕毒，干戈铁马群。","一生逃万死，百岁仅三分。","遑恤恒饥子，姑留自祭文。","醺醺人笑我，方寸不醺醺。"]},{"t":"七十翁五言十首 其三","f":"五言律诗","c":["五月炎歊早，冰盘未荐瓜。","客中如许热，林下岂无家。","体炙巾缯火，肤斑点铁砂。","一杯庆七十，汗滴暮楼霞。"]},{"t":"七十翁五言十首 其二","f":"五言律诗","c":["愁与忧全异，欢于乐尚遥。","百年元易度，一日却难消。","玉叵圭中必，桐犹爨下焦。","襟怀殊郁郁，纵目却飘飘。"]},{"t":"七十翁五言十首 其一","f":"五言律诗","c":["岂谓真成老，元来总堕虚。","它乡身似雁，永夜眼如鱼。","未觉知几早，惟嫌料事疏。","纵无三阁馔，犹有五车书。"]},{"t":"七十翁吟七言十首 其十","f":"七言律诗","c":["颓龄侥倖古来稀，休致多年但欠归。","决不再思龟左顾，幸犹免赋雉朝飞。","江山如旧几寒暑，天地无情多是非。","能办东篱一杯酒，可须疏傅有金挥。"]},{"t":"七十翁吟七言十首 其九","f":"七言律诗","c":["三十科名续父灯，岂知七十老无能。","儿童半长馀犹幼，门户中衰久未兴。","南亩尽捐犹有宅，白头垂秃已如僧。","平生诗力秋尤健，万里霜天击怒鹰。"]},{"t":"七十翁吟七言十首 其八","f":"七言律诗","c":["几夜楼东晓望时，长庚缺月傍参旗。","江湖已满焉能久，天地将秋更不疑。","暑渐变凉差可喜，老难重少自堪悲。","年来辈行凋零尽，诗卷中多赋挽诗。"]},{"t":"七十翁吟七言十首 其七","f":"七言律诗","c":["神奇臭腐变穷通，宇宙纷纭醉眼中。","邓禹第堪文学掾，刘歆早作国师公。","干戈世故千岐异，礼乐民彝万古同。","造化岂应全聩聩，秋来依旧有西风。"]},{"t":"七十翁吟七言十首 其六","f":"七言律诗","c":["幼孤何敢事儿嬉，闻道惟惭性钝迟。","早尚虚文迷释老，晚参实学溯濂伊。","五更灯火芸千卷，两世冠裳桂一枝。","梦幻无成吾不怨，庾愁江恨鬓丝丝。"]},{"t":"七十翁吟七言十首 其五","f":"七言律诗","c":["千古斯文未陆沉，夏因周继太骎骎。","瓜分缪主獾郎学，灰烬阴传桧贼心。","江总不惭同北狩，钟仪何限尚南音。","一龛花院伤前事，犹胜棺穿蔓草深。"]},{"t":"七十翁吟七言十首 其四","f":"七言律诗","c":["饱观代谢四时成，勿讶阴晴小变更。","何许三牲聊淡食，向来五马亦徒行。","长哦王粲登楼作，浪得朱云请剑名。","我死故应非短命，彼饕谁果是长生。"]},{"t":"七十翁吟七言十首 其三","f":"七言律诗","c":["一鸣场屋老书生，晚节蹉跎百不成。","旧试卷忘涂注乙，新吟藁漫草真行。","柄臣全似逢崔胤，座主徒劳识李程。","第五阿房关许事，樊川终自有诗名。"]},{"t":"七十翁吟七言十首 其二","f":"七言律诗","c":["自笑衰颓七十翁，全将拙钝易豪雄。","犹贤乎已思诗苦，不失其驰饮酒恭。","女嫁男婚俱失望，廷胪殿对总书空。","倚楼夜夜看星斗，未了昏钟又晓钟。"]},{"t":"七十翁吟七言十首 其一","f":"七言律诗","c":["莫笑衰颓七十翁，老来柔外尚刚中。","评诗青眼时虽白，借酒苍颜也自红。","轻薄交游翻手雨，艰难仕宦打头风。","休官至此六逢闰，能忍穷人不送穷。"]},{"t":"七月二十三日闻城南火午至夜半怀归","f":"七言律诗","c":["月近参旗欲下弦，倚楼半夜独看天。","故园入梦将千日，朝服离身已七年。","汹汹火惊何不去，嗷嗷籴贵更堪怜。","汉庭使者求民瘼，汲黯应须识后先。"]},{"t":"七月初一日早起","f":"五言律诗","c":["太白星初上，参旗井钺连。","新秋知几日，酷暑极今年。","足不能离地，心常欲契天。","水乡差得稔，亢旱念山田。"]},{"t":"九日","f":"七言律诗","c":["楼前楼后独徘徊，便当登高百尺台。","海内共知吾辈老，江南未见菊花开。","细思去岁人谁健，遥想中原雁已来。","我似少陵亦赊酒，不妨剩举两三杯。"]},{"t":"九日无酒","f":"七言律诗","c":["陶杜休官窘可知，更怜坡老惠州时。","三人九日俱无酒，一笑千年各有诗。","我辈固穷生事拙，今秋悭雨菊花迟。","典衣不办杯中物，空嗅青英有所思。"]},{"t":"九日北山寺二首 其二","f":"七言律诗","c":["白云苍藓尚知心，野径荒泉许重寻。","一马出城元近近，万松藏寺已深深。","同游似觉无先到，半醉谁知政独吟。","十度重阳如瞬息，足知往古与来今。"]},{"t":"九日北山寺二首 其一","f":"七言律诗","c":["松阴佳处路宜迟，裹袖寒鞭马上垂。","邂逅同倾九日酒，凄凉暗诵十年诗。","试回白首思前事，未觉青山减旧时。","节后骚英应好在，煮茶更与野僧期。"]},{"t":"九日归自南山","f":"五言律诗","c":["山寒小雨晴，落叶献秋声。","酒可诸僧共，诗须此老评。","钩帘脩竹净，辟户远江横。","相送依依意，丹青画不成。"]},{"t":"九日有感再书","f":"七言律诗","c":["荒山过雨薄寒新，洗尽西风扇底尘。","萍梗江湖今故国，干戈天地几遗民。","向来佳节都如梦，不谓衰年剩此身。","草草儿曹一杯酒，谁欤可与话酸辛。"]},{"t":"九日约冯伯田王俊甫刘元煇","f":"七言律诗","c":["山雨初开一望之，似无筋力可登危。","每重九日例凄苦，垂七十年更乱离。","今岁江南犹有酒，吾曹天下谓能诗。","肯来吊古酣歌否，恰放黄花一两枝。"]},{"t":"九日即事","f":"七言律诗","c":["閒居九日意何穷，落木长江感旧同。","佳句致多惟杜老，良辰专美只陶翁。","为问从人游戏马，何如对物咏来鸿。","无萸无菊无螃蟹，亦可随宜酒一中。"]},{"t":"九日汪元卿送酒亦有相拉者以病嗽不出","f":"七言律诗","c":["紫兰黄菊园丁送，亦有邻翁送酒来。","何忽于斯须煮药，不然夫岂怯衔杯。","登高朋友空相觅，抱病情怀未易开。","过了重阳更堪醉，霜天螃蟹小春梅。"]},{"t":"九日诗冯伯田王俊甫刘元煇杨泰之见和复次韵二首 其二","f":"七言律诗","c":["归来誓墓学羲之，政坐机张触处危。","久已光芒韬巨阙，更能文采眩长离。","奏书方朔三千牍，饮酒渊明二十诗。","索米长安饥欲死，何如终保傲霜枝。"]},{"t":"九日诗冯伯田王俊甫刘元煇杨泰之见和复次韵二首 其一","f":"七言律诗","c":["空经虚纬费来之，弦急常由瑟柱危。","壮似阴山歌敕勒，悲于易水和渐离。","崎岖万古无穷事，酩酊重阳几句诗。","剩喜故人会吾意，东篱何日酹残枝。"]},{"t":"九日南山寺","f":"五言律诗","c":["佳节携壶意，全如杜牧之。","百年谁不死，九日可□□。","□□差能饮，平生政坐痴。","胸中不酩酊，未许野人知。"]},{"t":"九月一日稍佳演作五十六字终不及少陵牧之","f":"七言律诗","c":["少陵哦后牧之□，□□篇章可谓过。","真是能专诗笔否，似应无奈菊花何。","雁来秋老江湖落，病感风寒涕唾多。","自古死生元有命，满斟且复醉颜酡。"]},{"t":"九月二十五书事二首","f":"七言律诗","c":["苍颜未怯冷风吹，过了残秋更自奇。","细嚼菊花吞美酒，閒拈柿叶写新诗。","繄谁屡贺参元火，与客仍消李远棋。","七十馀龄能有几，开怀切勿皱愁眉。"]},{"t":"九月八日宾旸携酒西斋晚登秀亭次前韵 其一","f":"七言律诗","c":["深钳笑口似难开，顿喜诗仙载酒来。","此道孰为今老笔，吾庐适有古荒台。","焉知晚节逢陈厄，忽听高歌类郢哀。","倚石自怜吟不就，频将拄杖划莓苔。"]},{"t":"九月八日宾旸携酒西斋晚登秀亭次前韵 其二","f":"七言律诗","c":["楚调悠然抑更扬，四愁平子五噫梁。","身同落叶常无定，□比寒花似较长。","但喜有乡频得醉，不知何药号为狂。","芬香臭腐俱尘土，莫问桑田与海洋。"]},{"t":"九月十二日得蟹小酌","f":"七言律诗","c":["莫欺虚谷太凄凉，短发频搔意自长。","万古江山宜晚景，一番宇宙更秋光。","东篱把菊非尘世，左手持螯可醉乡。","二物于吾犹莫逆，达人何日不重阳。"]},{"t":"九月三十日汉臣置酒次日有诗次韵","f":"七言律诗","c":["槁梧策策晚风秋，始觉天边雨意休。","扫尽阴霾供一醉，豁开空阔慰双眸。","青铜未至无王老，红袖何嫌有莫愁。","我亦放颠插残菊，不羞衰老雪盈头。"]},{"t":"九月五日所乘小骢不起","f":"七言律诗","c":["瘦骨如山老病骢，圉邕治药竟无功。","岂徒倜傥权奇惜，曾与艰难险阻同。","万里风沙来往外，十年宾旅送迎中。","□□一失真难得，宁少人间女颊红。"]},{"t":"九月初一日","f":"七言律诗","c":["满城风雨夜初长，晓径衣单野圃荒。","秋著此寒欺老我，诗将何句待重阳。","山容竞爽穿疏树，菊意高骞迓早霜。","人事日非物良是，悲来谁办铁为肠。"]},{"t":"九月初八日","f":"七言律诗","c":["今年未见菊花枝，老恐登高亦不宜。","但得明朝须有酒，可能我辈更无诗。","身閒天下朋游少，秋暑江南雁到迟。","宗武宗文佐觞咏，几家伯道叹无儿。"]},{"t":"九月初五日","f":"七言律诗","c":["暮雨萧萧鼓角风，草枯木落雁横空。","每逢九日不胜感，垂近七旬无奈穷。","螃蟹今年犹未有，茅柴我辈亦堪中。","篱边瘦菊青如粟，已胜芙蓉万朵红。"]},{"t":"九月初六日客报吾州初一日大火城中俱尽吾家亦尽七八九报皆然初十日始报吾家幸免拆毁屋十馀间二十五日得王山长亲家书始知仅存州治州仓州学书院吾家免焚馀所免不过数十家","f":"七言律诗","c":["生死由来一念间，回头不落鬼门关。","细思上策莫如醉，稍据要津焉得閒。","婢仆冻饥犹恋主，儿童婚嫁合还山。","一穷惹起无穷事，独乐吾惟学巷颜。"]},{"t":"九月初四日大风雨近重阳无酒夜成二首 其二","f":"七言律诗","c":["秋霖欲洗庾公尘，不管楼头客恨新。","塞雁又为江左客，菊花曾识晋时人。","百年虚谷先生老，一纪严州太守贫。","几向客中度重九，苦无佳句答良辰。"]},{"t":"九月初四日大风雨近重阳无酒夜成二首 其一","f":"七言律诗","c":["怕见秋深秋又深，青灯白发厌愁霖。","百年剩几重阳日，万事都无一称心。","自揣老怀饶感慨，可须佳节强登临。","在陈自郐哦韩句，敢望空罍有浊斟。"]},{"t":"二十一甲子晴","f":"五言律诗","c":["昨日大风声，今朝甲子晴。","整襟衣顿爽，开匣镜偏明。","早就鲸鲵筑，终全燕雀成。","清和旧时节，新面入山城。"]},{"t":"二十七日又大雪凡半月","f":"七言律诗","c":["茂林枯树总模糊，半月檐声乍有无。","天鼓北风神转王，地穷南海瘴全苏。","战鼙戍角夜烽火，旅棹征鞍朝道途。","辛苦一生亦奇绝，暮年犹许画寒炉。"]},{"t":"二十九日岁除","f":"七言律诗","c":["六十年前幼学儿，端平明日改嘉熙。","黟川亡妹来归日，歙陇先君改葬时。","学问文章成画饼，科名官爵著饶棋。","细思未觉家声坠，能忍穷人不是痴。"]},{"t":"二十八日残雪不消怀旧","f":"七言律诗","c":["老眼今犹见雪明，几番绝景慰生平。","三高祠畔吴江棹，百战军前鄂汉城。","颠沛艰难垂欲死，登临慷慨谩多情。","骆驼乳紫青貂暖，老矣无由再玉京。"]},{"t":"二十三日天气绝佳西军还二十四日东如绩溪","f":"五言律诗","c":["独坐绿阴下，追思秋日春。","眠蚕方放大，早麦欲尝新。","岂意贼生贼，忍闻人食人。","何时兵遂解，纵遣上城民。"]},{"t":"二月十一日晓发龙山风顺","f":"七言律诗","c":["繁华销歇市朝空，此地何堪著固穷。","久似坎蛙居井底，忽如野鹤出笼中。","宿酲夜解催花雨，归棹春乘上水风。","及得清明到家否，新芽茶绿牡丹红。"]},{"t":"二月十七日偕宾旸市饮二首 其二","f":"七言律诗","c":["无官岂畏犯金科，饮量真能海纳河。","人老自于春色淡，花开最恨雨声多。","向来伴侣今都尽，乃后光阴复几何。","更挈残樽趋曲巷，小姬摘阮和燕歌。"]},{"t":"二月十七日偕宾旸市饮二首 其一","f":"七言律诗","c":["误著儒冠玷甲科，休官重到旧沙河。","未妨缓步微行好，犹恐傍观窃议多。","我辈相逢唯酒可，桃花如许奈春何。","雪儿人物今难得，一曲离骚醉自歌。"]},{"t":"二月十五晚吴江二亲携酒","f":"七言律诗","c":["今日山城好事新，客来誇说齿生津。","喜晴郊外多游女，归暮溪边尽醉人。","鲜笋紫泥开玉版，嘉鱼碧柳贯金鳞。","一壶就请衰翁饮，亦与花朝报答春。"]},{"t":"二月十六日夜独酌思归四首 其四","f":"七言律诗","c":["楼前春水欲生蛙，楼上无眠夜忆家。","官道靴鸣知有雨，故溪船去好移花。","耆年极荷神祇借，直性难禁世俗哗。","便可真归不须梦，烂烹新笋煮新茶。"]},{"t":"二月十六日夜独酌思归四首 其三","f":"七言律诗","c":["不谢车尘觅饷偎，前行后指亦危哉。","一贫牵绊似绳缚，百怪攻攒如箭来。","自倚此中惟拙直，未知何故每惊猜。","是尧非桀俱尘土，且可深杯更浅杯。"]},{"t":"二月十六日夜独酌思归四首 其二","f":"七言律诗","c":["聊复埋身面糵昏，倘来倘去肯销魂。","瓦犹幸有三间屋，绢可全无二丈裈。","壮士笑谈跻将相，寒儒衰老误儿孙。","社公雨作春灯暗，独尽花前酒一樽。"]},{"t":"二月十六日夜独酌思归四首 其一","f":"七言律诗","c":["閒忆山中一片云，归欤莫待草风薰。","老身岂可为形役，俗语何堪著耳闻。","乍醉乍醒终郁郁，孰非孰是几纷纷。","颠寒踣饿男儿事，已办渊明自祭文。"]},{"t":"二月三十日","f":"五言律诗","c":["酒病专欺老，诗材苦欠新。","客窗庐阜雨，故圃洛花春。","岁运江声急，家人夜梦频。","遥知扫松处，笋茗正芳辛。"]},{"t":"入五月病二七日","f":"五言律诗","c":["病已捐蒲酒，寒犹拥絮衣。","形骸元自劣，气候每相违。","人死朝朝有，吾衰事事非。","尪羸存喘息，聊复信天机。"]},{"t":"八月二十日天晓","f":"五言律诗","c":["清晓潮初过，西风猎弊裘。","肯为贫士地，偏觉老人愁。","蟋蟀声弥急，梧桐色渐愁。","残星馀几点，吾独倚吾楼。"]},{"t":"八月二十日赵西湖携酒夜醒二更记事 其一","f":"七言律诗","c":["社袄初穿暑气收，今朝五日过中秋。","隔湖我每思□□，□市公能顾小楼。","斗酒只鸡承厚意，扁舟匹马约閒游。","吾侪不与人间事，肯挂眉头一点愁。"]},{"t":"八月二十日赵西湖携酒夜醒二更记事 其二","f":"七言律诗","c":["酒醒更深独倚楼，天清地静俯河流。","梧桐影转三更月，蟋蟀声催万象秋。","自古有生皆有死，即今无喜亦无忧。","更著四年当八十，我于人世复何求。"]},{"t":"八月二十四日宾旸华父同登秀亭二首 其二","f":"七言律诗","c":["两公诗思欲飞扬，颇似繁台俯大梁。","潇洒道装衣袖阔，昂藏寿相耳毫长。","持身未惯全随俗，玩世何嫌略放狂。","我有平生八叉手，兴来举酒尚洋洋。"]},{"t":"八月二十四日宾旸华父同登秀亭二首 其一","f":"七言律诗","c":["垂垂三径晚香开，二妙端能为我来。","老瓦尚堪沽浊酒，破鞋何惜上高台。","十年心事霜髯短，万□秋声画角哀。","海内诗人有公等，悬崖待与斸苍苔。"]},{"t":"八月十二夜对月","f":"七言律诗","c":["胡床正面紫阳山，净扫晴阶掩夜关。","金气渐寒风露下，冰轮欲满斗牛间。","衰怀突兀来千感，暮齿逍遥保一閒。","天役万形仍自役，何为西堕又东还。"]},{"t":"八月十八日天晓二首 其二","f":"五言律诗","c":["河中船已动，岸亦有人行。","城北钟声断，楼东鬼宿明。","倚□□酒醒，搔首小诗成。","□□中秋热，今朝始渐清。"]},{"t":"八月十八日天晓二首 其一","f":"五言律诗","c":["木犀花正盛，吹入满楼香。","不是人无寐，焉知夜已长。","树鸣秋雨急，潮过海天凉。","自觉衣裘少，侵寻近肃霜。"]},{"t":"八月十五夜对月","f":"七言律诗","c":["散发披襟一再窥，未甘兀兀守书痴。","月圆照尽天圆处，秋半凉当夜半时。","人世无灯方作梦，山翁有酒更能诗。","此心除却嫦娥外，惟许崚嶒瘦影知。"]},{"t":"八月三十日晓晴","f":"七言律诗","c":["高树号风始欲丹，秋晴诗老试凭栏。","食贫破砚惊犹在，身瘦寒衣觉渐宽。","家里儿孙音问好，客中僮仆使令难。","雪前霜后归吾圃，瘦菊疏梅尽耐看。"]},{"t":"八月五日病中","f":"五言律诗","c":["于心敢自欺，但恐不精思。","未觉扶颠易，方惊悔过迟。","病堪长作客，贫可荐招医。","观井如彭祖，闻诸丱角时。"]},{"t":"八月初一日","f":"五言律诗","c":["吾生遽如此，六十一衰翁。","功过差相掩，时几大不同。","冥冥终日雨，忽忽半秋风。","食尽囊无物，今年始是穷。"]},{"t":"八月初一日","f":"七言律诗","c":["秋风几日尚无诗，政坐炎歊转赫曦。","閒被贫为魔搅挠，病须凉当药医治。","薄田董穫收新粟，老圃开包献巨梨。","顾此亦差胜穷宦，回头何啻十年迟。"]},{"t":"八月初二日","f":"七言律诗","c":["蝉声渐渐怯西风，閒撚青枝玩菊丛。","老去一身都是病，寤来万梦总成空。","喜分果饵小儿女，浪费薪蔬顽仆僮。","严濑家人报船至，更营樽酒恼衰翁。"]},{"t":"八月朔后雨昼夜不止","f":"五言律诗","c":["□蔑丝毫暑，何庸一再霖。","秋阴酸病骨，夜滴碎归心。","剧盗应旁睨，馀田或尽沉。","无灯黑如漆，臆度近更深。"]},{"t":"力学","f":"五言律诗","c":["力学衰犹进，治生晚不雠。","操心元自定，忤俗果何由。","涂抹馀千纸，浮沉等一沤。","忍穷兼耐辱，失笑未包羞。"]},{"t":"十一月二十九日壬子喜雪","f":"七言律诗","c":["撚冰惊起冻髯翁，一色楼台晓未融。","酤肆定应昂酒价，篙工是处打船篷。","读书窗上纸偏白，跃马街头尘不红。","忧国愿丰心绝喜，可能儿女絮因风。"]},{"t":"十一月二十日南至二首 其二","f":"七言律诗","c":["至节今年始得归，祀先牲酒亦无几。","儿孙长大衣装少，婢仆顽慵廪饩微。","交阯虞翻犹不死，荆州王粲竟何依。","玉筒已想黄钟动，只有心灰自懒飞。"]},{"t":"十一月二十日南至二首 其一","f":"七言律诗","c":["风吹六十二年春，又见阳和一夜新。","兴废亲更三国事，死生暗易万城人。","种花纵好谁同赏，置酒良难自惯贫。","今独身为本宗长，思兄临节倍悲辛。"]},{"t":"十一月十五日","f":"五言律诗","c":["倏忽何庸诘，参差未易齐。","树枯元不死，雪尽竟为泥。","岂谓身才老，从来意欲西。","一穷宁骨立，九殒未头低。"]},{"t":"十一月十五夜","f":"五言律诗","c":["竟与鳏鱼似，无由浊蚁持。","百为元有命，一往复何疑。","残梦终难续，深忧暗自知。","邻雏夜啼急，吾亦忆吾儿。"]},{"t":"十一月十四夜听雨为霰听霰为雪久之雪后为骤雨自昏达旦无寐","f":"五言律诗","c":["雨声更霰雪，昏听达清晨。","自笑能吟客，常为不寐人。","絮寒勤拭涕，箦响惧翻身。","苦语知谁会，应堪泣鬼神。"]},{"t":"十一月初八日观雨","f":"七言律诗","c":["重阳晴过小春天，忽复萧骚雨可怜。","响入竹林全似雪，湿蒸茅舍最宜烟。","战尘洗净无传箭，客路泥深亦著鞭。","三月聚粮岂容易，临风殊觉意茫然。"]},{"t":"十七十八日犹雨","f":"五言律诗","c":["浮云几万里，白日闷晴晖。","稍觉波涛缩，犹闻点滴微。","两旬捐破扇，五月著寒衣。","老病忧时事，高门马自肥。"]},{"t":"十九日甲戌晴己卯晚又雨二首 其二","f":"五言律诗","c":["吴郡传犹庶，严滩报可惊。","田中车水出，城上驾船行。","旅屋仍筛漏，穷檐用盎盛。","幸而有雷电，此雨不难晴。"]},{"t":"十九日甲戌晴己卯晚又雨二首 其一","f":"五言律诗","c":["稍复桥痕旧，俄惊础汗非。","岂宜真汹涌，止可略霏溦。","河伯毋流毒，云师幸霁威。","劣能驱暑气，即愿吐晴晖。"]},{"t":"十九日始晴","f":"五言律诗","c":["今日檐仍滴，何人胆不寒。","晒帆船尚湿，扫市路才乾。","造化玄机转，生灵死命完。","传闻睦东馆，楼阁付惊湍。"]},{"t":"十九日斩贼十二人始明正典刑","f":"五言律诗","c":["兵兴欲两旬，三载气初伸。","汝既甘从贼，官非乐杀人。","早知膏白刃，何忍效黄巾。","拙速无奇策，登城悉市民。"]},{"t":"十二月十三日三桥小雪","f":"七言律诗","c":["晓楼衾薄梦回频，辟户寒光绝点尘。","各各一篷船未动，差差万瓦屋如新。","高门定有丰醪饩，下里畴能馈粲薪。","邻叟踏泥共煎茗，早云多有望晴人。"]},{"t":"十二月十五日去年以此日归","f":"五言律诗","c":["日月相望夕，西归昔问途。","焉知穷岁迫，重寓客楼孤。","压雪弥河舫，胶冰噤树乌。","遥怜万山里，儿女乏寒襦。"]},{"t":"十二月十五日晚宿馀杭步","f":"七言律诗","c":["孰令牵率到钱塘，朝暮随人作酒狂。","蜕壳喜离城市路，发蒙惊见水云乡。","四方上下乾坤阔，万里东西日月望。","向来楼居不得句，此夕叶舟吟兴长。"]},{"t":"十六日","f":"五言律诗","c":["来往江复浙，扰扰一年间。","有子犹相隔，无官亦未閒。","病嫌真药少，债准旧书还。","霁雪楼前立，依依忆故山。"]},{"t":"十六日水退雨不已次受益韵二首 其二","f":"五言律诗","c":["七年逢四潦，苟活到于今。","每值月离毕，难逢木守心。","江兼湖共满，忧与恨俱深。","万顷青秧没，田家泪湿襟。"]},{"t":"十六日水退雨不已次受益韵二首 其一","f":"五言律诗","c":["暑雨民咨怨，由来直匪今。","湿能蒸病骨，滴欲碎归心。","积水连村郭，前途昧浅深。","雄风楚台上，谁且独披襟。"]},{"t":"十月三日秀亭二首 其二","f":"七言律诗","c":["乱峰古垒一荒台，自笑衰翁去复来。","石怪更宜添薜荔，树枯犹许寄莓苔。","四天无壁供诗眼，万古皆空付酒杯。","惆怅远惭羊叔子，秋阴欲暮角声哀。"]},{"t":"十月三日秀亭二首 其一","f":"七言律诗","c":["天怜迟莫与清閒，閒上高山看远山。","世味已如玄酒淡，名场肯复左轮殷。","千争万竞尘埃里，古恨今愁莽苍间。","□□谁来问诗叟，应输老树识苍颜。"]},{"t":"十月六日小酌以自宝此身方有寿分韵得身字","f":"七言律诗","c":["一从鼙鼓沸烟尘，十士相逢八九贫。","梦境谁能为达者，醉乡犹幸属閒人。","剩留佳句传来世，谨护风寒养病身。","归去吾家有何物，岂无江水濯缁巾。"]},{"t":"又用前韵赋夜坐","f":"七言律诗","c":["酒醒招得醉魂归，深护炉熏键夕扉。","渴舌恶甜勤漱茗，癯肩耐冻懒添衣。","颇闻空暗无星出，小待更深定雪飞。","一字不圆终不寐，癖诗如我自应稀。"]},{"t":"又次韵张御史鹏飞","f":"七言律诗","c":["休致衰年暗自惊，閒呼张丈唤殷兄。","马尘往往逢新贵，鸥梦依依忆旧盟。","洛社绘图惭九老，汉庭绵蕝付诸生。","绣衣御史烦推毂，我有蓑衣永不更。"]},{"t":"又雨","f":"五言律诗","c":["霞红疑太早，果不是晴天。","市涨危侵户，村流喜入田。","昏昏邻寺鼓，滃滃晚厨烟。","明日应犹雨，宵甜一枕眠。"]},{"t":"万山堂呈史察使 其二","f":"七言律诗","c":["质肃英声盖九州，名孙吾获与之游。","胸中所学万青简，堂上有亲双黑头。","买砚新添行橐重，抄书勤过野庐幽。","雕鞍长剑纷纷是，人物如斯岂易求。"]},{"t":"万山堂饮归","f":"七言律诗","c":["追怀往者数贤侯，得得经营续续脩。","依旧夜栏低北斗，几番春絮委东流。","同游尽道山能好，半醉谁知我独愁。","乃后吾徒身亦死，题诗更有昔人不。"]},{"t":"三十年吟","f":"五言律诗","c":["三十年为世，吾今迫六旬。","儿时前辈尽，乱后善人贫。","未测前途闇，空追往迹陈。","所亲化埃土，犹入梦魂频。"]},{"t":"三月二十九日饮杭州路耿同知花园","f":"七言律诗","c":["巢燕春泥久已融，虞弦节近鼓薰风。","枝枝烂熟樱桃紫，朵朵争妍芍药红。","冠豸霁威贤御史，雕虫得隽老诗翁。","十分蚕麦今年稔，我辈何妨酒一中。"]},{"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其五","f":"七言律诗","c":["后生谁识旧西湖，除却山僧树总无。","何至梅仙坟亦掘，惟应葛岭鬼当诛。","红裙鞭镫追游女，白首端章笑腐儒。","两盏三杯更多感，不如烂醉眼模糊。"]},{"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其四","f":"七言律诗","c":["生长西湖死葬湖，兴言舟子与农夫。","全家衣食凭摇橹，历世儿孙学荷锄。","布衲劣兼蓑笠有，齑汤恐并酱醯无。","金盘玉箸环歌舞，午鬨昏空一任渠。"]},{"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其三","f":"七言律诗","c":["暮年无不与心违，节物过从事总非。","何处青梅尝煮酒，谁家红药试单衣。","半酣便合拿舟去，骤热犹容借扇归。","忽忆向来独立处，雪天閒看白鸥飞。"]},{"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其二","f":"七言律诗","c":["湖山春色已如斯，城市原来了不知。","百五韶华全似画，二三名胜总能诗。","忽惊我辈相携处，谁识吾人始到时。","五十四年前弱冠，设盆犹忆唱闽词。"]},{"t":"三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其一","f":"七言律诗","c":["第五桥通曲港船，直摇春水到门前。","休官久作渔竿客，扶老来寻鹤氅仙。","畴曩欢娱如昨日，今吾衰飒最高年。","旧坟新冢石羊马，且举残杯莫怆然。"]},{"t":"三月十七夜大雷雨用韵酬俞好问四首 其四","f":"七言律诗","c":["倦眠书砚付埃氛，烟尽当窗一篆云。","黠鼠谁令如鬼物，痴猫吾欲与弹文。","雨馀自揣薪槱绝，客里尤怜仆厮勤。","花尽春残不须惜，好谋归棹趁南薰。"]},{"t":"三月十七夜大雷雨用韵酬俞好问四首 其三","f":"七言律诗","c":["薄有盐醯胹竹孙，夜寒城郭似荒村。","远更已觉踰三鼓，独酌无聊罄一樽。","此道粗闻元自少，众人欲杀幸犹存。","盲风怪雨青灯暗，庄蝶难凭入梦魂。"]},{"t":"三月十七夜大雷雨用韵酬俞好问四首 其二","f":"七言律诗","c":["恶风夜汹疾雷频，稍卧还兴起倒身。","政复花时如此雨，谁知我辈本无春。","破衣垢腻疮饶痒，短被斜攲脚倦伸。","挨耐天明招敢叟，能来破闷赖斯人。"]},{"t":"三月十七夜大雷雨用韵酬俞好问四首 其一","f":"七言律诗","c":["彻夜无眠直到明，拟春晴又不春晴。","酒材劣致平原督，花事愁闻望帝声。","病体惯经寒热證，倦途浑忘短长程。","五年浩荡江湖梦，犹喜相逢得友生。"]},{"t":"三月十八日甲子晴","f":"七言律诗","c":["夜夜春寒渐觉轻，桐花十日过清明。","去年稔更今年稔，壬子晴兼甲子晴。","楼阁相望饶客醉，干戈不用保农耕。","老儒八十心无事，依旧吟窗剔短檠。"]},{"t":"三十年重到紫阳观","f":"七言律诗","c":["石路崎岖唤渡船，松萝穿尽望中烟。","缪为白发二千石，轻别紫阳三十年。","洞冷敛心归酒地，阁虚携眼上诗天。","丹砂九转犹多事，解饮能吟即是仙。"]},{"t":"三桥旅邸遇雪","f":"七言律诗","c":["酝云蒸雾暖如烘，一夜南风变北风。","不似寻常响窗纸，渐惊分寸压船篷。","粉妆已斗佳人白，酒面还输老子红。","记取今年呵冻笔，三桥西岸小楼中。"]},{"t":"上元立春","f":"七言律诗","c":["华灯綵胜两逢迎，美景良辰未易并。","花信风初回肃杀，柳梢月岂异承平。","神鳌观阙山何在，旅雁汀洲水复生。","可待紫姑问休咎，买牛西崦课儿耕。"]},{"t":"久苦春寒三月三日戏作俳体","f":"七言律诗","c":["似惜残红未放稀，佳人怯试薄罗衣。","桃花水涨冰犹凝，燕子泥融雪更飞。","老去寻芳元自懒，病来吹霎不如归。","常嫌禊帖书清朗，尔许奇寒可浴沂。"]},{"t":"久雨","f":"五言律诗","c":["肺病兼脾病，葵花复槿花。","閒犹常不乐，老欲更何加。","客讶添新犬，童喧断小蛇。","穷居非得句，持底谢年华。"]},{"t":"壬寅生日杨广文携示壬辰生日诗次韵","f":"七言律诗","c":["方寸天知地亦知，昂藏胸次了无奇。","山林独乐休官早，□县徒劳见事迟。","一影浪行千万里，十年未朽两三诗。","故□□□惊陈迹，旅次传抄付小儿。"]},{"t":"大风寒微晴","f":"五言律诗","c":["穷旅宽愁思，严寒作淡晴。","终须开日色，何可欠风声。","地白犹含冻，天青渐放明。","吴门稍和暖，应有故人迎。"]},{"t":"大北早行","f":"五言律诗","c":["重雾须髯湿，深林草树香。","山中人未起，马上晓偏凉。","晴屋悬新麦，寒田莳晚秧。","近来兵事息，烟火渐微茫。"]},{"t":"大雪出三桥寓楼","f":"七言律诗","c":["冻雀愁鸢噤不哗，漫天浩瀚逐风斜。","映楼横过三千丈，接屋平铺十万家。","静夜有窗皆贮月，寒空无树不开花。","诗成欲撚冰须断，聊举深杯答岁华。"]},{"t":"大雪约程以忠不至次日以诗问之","f":"七言律诗","c":["禦寒时著火文武，等醉岂拘杯圣贤。","土润春应萌有日，尘清野更洁于天。","谁呵冻笔诗能画，独上高岗意欲仙。","剩有篱根未消处，试裒枯筱取茶煎。"]},{"t":"小长桥书事","f":"七言律诗","c":["似觉晴光稍不同，天成奇句与衰翁。","雪滋死草芽先绿，冰浴新鹅掌倍红。","荏苒客途惊岁暮，凄凉家事忆江东。","小长桥畔谁知许，一棹孤舟万籁风。"]},{"t":"小至日书","f":"七言律诗","c":["谁知缇室动葭灰，总道阳从九地回。","年近六旬愁里过，身行万里死边来。","诗存瘦骨全如我，花倚春风不是梅。","偶有友朋仍有酒，看云聊与釂深杯。"]},{"t":"小园","f":"七言律诗","c":["累土为台就浚池，小园聊尔寄娱嬉。","栽花谁觉似贫户，煮菜自量无厌时。","月下秋声长不寐，水中树影最宜诗。","客来客去频欢喜，祇为能饶一着棋。"]},{"t":"小雪日观残菊有感","f":"五言律诗","c":["欲雪寻梅树，馀霜殢菊枝。","每嫌开较晚，不道谢还迟。","早惯饥寒困，频禁盗贼危。","少陵情味在，时讽浣花诗。"]},{"t":"小楼","f":"五言律诗","c":["乾坤今古事，尽在倚栏间。","初上似登塔，忽高都见山。","醉眸天共远，吟思暮忘还。","城市如岩壑，谁能共此閒。"]},{"t":"马军自杭至雨少止","f":"五言律诗","c":["春尽雨还雨，山寒云更云。","昼常无日色，夜不见星文。","蜂起此狂贼，马来皆劲军。","尅期可平尽，玉石恐难分。"]},{"t":"不寐","f":"七言律诗","c":["眇忽微茫一入思，穿天匝地遍垓维。","残秋夜静山深处，孤客灯昏酒醒时。","自宝此身方有寿，不穷我辈更无诗。","少陵同谷七歌在，每一歌之泪欲垂。"]},{"t":"不寐","f":"七言律诗","c":["孤灯独榻夜难晨，秋气初寒展转频。","每怪未尝成梦寐，自怜何苦费精神。","非关世事兼身事，欲学贤人与圣人。","更著冰霜当七十，向来虚费几青春。"]},{"t":"不寐十首 其十","f":"五言律诗","c":["细字昏难读，孤灯冷独挑。","黄齑馀口味，白豆验心苗。","玉枕方春梦，金门正早朝。","先生唯默坐，窗外雨萧萧。"]},{"t":"不寐十首 其九","f":"五言律诗","c":["竺国轮回说，诬民断勿疑。","还知已死后，即是未生时。","六道何凭考，三身故强推。","反终更原始，不寐试深思。"]},{"t":"不寐十首 其八","f":"五言律诗","c":["涉世形容悴，违时嗜好偏。","偶犹身未死，岂为己无眠。","道丧文趋刻，谈高学类禅。","申生真毙犬，望帝竟啼鹃。"]},{"t":"不寐十首 其七","f":"五言律诗","c":["雪声兼雨声，静听到残更。","为底常无寐，宁当有不平。","食多嫌气浊，衾薄觉神清。","万古书灯眼，心常与共明。"]},{"t":"不寐十首 其六","f":"五言律诗","c":["夜眠才合眼，即见此诸公。","骸骨已应朽，精神犹自通。","老怀常忽忽，暮景极匆匆。","知己恩难报，皇天识寸衷。"]},{"t":"不寐十首 其五","f":"五言律诗","c":["世间无限事，总不属閒人。","必欲伸公论，宁如爱老身。","武成难尽信，泰誓尚非真。","卫府公闾语，何哉彼鬼神。"]},{"t":"不寐十首 其四","f":"五言律诗","c":["无寐复无寐，自知仍自知。","少狂今始悔，宿疾尚堪医。","雪水消残酒，灯花送好诗。","元龙湖海气，老矣复何施。"]},{"t":"不寐十首 其三","f":"五言律诗","c":["暮年无寐意，灯与影应知。","谁复名三叛，空劳赋五噫。","今人难与语，来世尚堪期。","准易扬雄业，真成覆瓿为。"]},{"t":"不寐十首 其二","f":"五言律诗","c":["孤灯深夜半，何乃抚床为。","道左时难料，心方世岂知。","孰刊前代史，肯作近人诗。","黠鬼应相笑，乾坤一老痴。"]},{"t":"不寐十首 其一","f":"五言律诗","c":["清寒雪夜天，攲枕暗灯前。","总为多思虑，常令少睡眠。","著书传后世，讲学绍先贤。","老死将无日，空閒十二年。"]},{"t":"中秋夜喜晴","f":"七言律诗","c":["秋来剩赋倚楼吟，天慰衰翁此夜心。","霁色一轮升白玉，欢声万镒价黄金。","酒才半醉吾忘我，诗最难题古到今。","日□西流聊困卧，不知更浅与更深。"]},{"t":"中秋前一日雨送罂粟戎葵子与刘元煇","f":"七言律诗","c":["小雨翻锄土带沙，戎葵罂粟送诗家。","敢争天上中秋月，且种人间隔岁花。","小稔米今犹未贱，固穷酒可不须赊。","乘閒傥肯来相过，有水吾能自煮茶。"]},{"t":"丹阳道中大雪","f":"七言律诗","c":["轻船摇兀涕垂颐，我见人船更谓奇。","琐细穿篷仍急舞，迷漫渡水故斜吹。","孤村茅屋炊烟绝，匹马毡衫冻仆随。","此是老夫有声画，丹阳道上雪天诗。"]},{"t":"乌聊山庙登览","f":"七言律诗","c":["寒斋兀兀味残书，一上崔嵬计未疏。","下界喧卑离市井，平皋洒落见樵渔。","断鸿淮汉三江外，古树隋唐五代馀。","忽忆浮溪偃王句，顾瞻遗庙意踌躇。"]},{"t":"书所见","f":"五言律诗","c":["春风元在眼，雪定不难消。","冻杞垂红子，晴麰动绿苗。","行人相叫唤，旅雁忽惊飘。","古柱镌年号，承平旧石桥。"]},{"t":"书歙县楚明府送行诗轴","f":"五言律诗","c":["俸尽青钱少，衣惟白苧粗。","赁楼邻羽客，买锦护梅图。","棋每藏高著，诗曾断几须。","生祠谁画得，清苦一臞儒。"]},{"t":"予尝治郡屡平贼叹今所见不然","f":"五言律诗","c":["昔在专城日，吾尝破贼时。","土豪勤问探，民户感恩私。","公论必旁采，下情须尽知。","骑军远迎击，孰识一先棋。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其十","f":"五言律诗","c":["西湖湖外水，汹涌入城流。","比户升高阁，通衢塞大舟。","学泅儿辈喜，绝爨老夫忧。","会见蹄涔涸，鱼虾悔浪游。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其九","f":"五言律诗","c":["今日云霄客，何人禹稷思。","树高堪避溺，稻尽底充饥。","苦口非吾事，衰躯异昔时。","东溟容有限，细读后山诗。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其八","f":"五言律诗","c":["平地惊胥怒，滔天类鲧湮。","稍低三板水，不活百城人。","已拚过从绝，徒工徙倚频。","鹄形无白粲，蜂起有黄巾。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其七","f":"五言律诗","c":["蒸渍衣巾醭，拘挛臂膝顽。","老身何足恤，时事自多艰。","井满瓢堪汲，船高树可攀。","苍生百万亿，性命雨旸间。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其六","f":"五言律诗","c":["眼待稻花看，青苗浸急湍。","万家应恸哭，五月更恒寒。","政尔千仓足，犹云一饭难。","凶灾忽如此，容易便平安。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其五","f":"五言律诗","c":["能免尧捐瘠，端由稷播艰。","民生频不竞，世故政相关。","穴蚁移楼杪，田蛙产灶间。","丰凶卜檐溜，半月响潺湲。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其四","f":"五言律诗","c":["江南梅子雨，骚客古今愁。","岂意连年夏，频妨庶事秋。","为鱼民自痛，食肉尔何忧。","衰老那禁得，看天独倚楼。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其三","f":"五言律诗","c":["陆走无非水，楼居并是泥。","褰裳难跋涉，执盖困扶携。","国虑白圭壑，城危智伯堤。","旸乌果安在，转觉漏天低。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其二","f":"五言律诗","c":["波浪冒原田，群鱼不自全。","返常真足怪，行险绝堪怜。","骤作乘时快，遄成失势颠。","儿童拾鳗鳝，争著柳枝穿。"]},{"t":"五月九日甲子至月望庚午大雨水不已十首 其一","f":"五言律诗","c":["夜半观天象，无星定肯晴。","河流兼市没，船势与楼平。","未杀漂摇意，仍添飒洒声。","人膏饫鱼鳖，真宰忍忘情。"]},{"t":"五月二十一夜雨未止六昼夜水涨寇阻无人入城","f":"五言律诗","c":["昼夜雨滂沱，平畴变海河。","地如随水去，天岂厌人多。","讨叛犹输粟，攻坚未掩戈。","积阴凝杀气，玄造意如何。"]},{"t":"五月二十三日甲子交六月节稍晴三四五复大雨贼寨未下","f":"五言律诗","c":["每日看天色，今年厌雨声。","重新六甲换，喜得一朝晴。","疲卒淹穷谷，饥民守坏城。","竹深荷净处，犹忆旧承平。"]},{"t":"五月二十三日怀归二首 其二","f":"七言律诗","c":["生红一簇海榴枝，惭愧虚翁两鬓丝。","久客湖山何足恋，□□父子自相知。","江南江北千钟酒，身后身前万首诗。","连□□霖忽开朗，人生亦有晚晴时。"]},{"t":"五月二十三日怀归二首 其一","f":"七言律诗","c":["拔茅犹在盍归休，何事清河日倚楼。","百岁四分三已过，十朝九醉一无愁。","独遗蕙帐容逋客，谁向瓜田识故侯。","定是紫阳山下路，西风仙袂揖浮丘。"]},{"t":"五月十一日生朝三首 其三","f":"七言律诗","c":["强展愁眉进一杯，年年红熟见杨梅。","至亲阻寇全无信，时贵嫌贫近不来。","京兆旧游张敞马，督亢遥望剧辛台。","华荣寂寞手翻覆，好在徉狂老万回。"]},{"t":"五月十一日生朝三首 其二","f":"七言律诗","c":["本非高蹈挂朝冠，自是危途举足难。","世上十年人不识，山中五月夜犹寒。","感风垂死骨骸痛，止酒近旬杯杓乾。","牵率亲朋致嘉惠，时危敢作等閒看。"]},{"t":"五月十一日生朝三首 其一","f":"七言律诗","c":["浊醪儿辈尚能谋，且勿惊忧且勿愁。","不肯前朝峨豸角，可于当世较蝇头。","永无紫绶金章梦，甘与青鞋布袜休。","旦夕贼平岁中熟，茅柴杯外更何求。"]},{"t":"五月十一日早问政山房三首 其三","f":"五言律诗","c":["纵不烧丹汞，村人总是仙。","今朝才酒债，明日有柴钱。","指草能医病，争棋每让先。","活龙肯相赠，竹杖掘深鞭。"]},{"t":"五月十一日早问政山房三首 其二","f":"五言律诗","c":["四十里苍翠，中环万屈盘。","望城藏谷底，觅路上云端。","笋出一春醉，樵深三伏寒。","山翁无将相，祇是敬黄冠。"]},{"t":"五月十一日早问政山房三首 其一","f":"五言律诗","c":["道士携壶酒，相迎劝瓦卮。","野葩芳杖屦，林霭润须眉。","自说夜频醉，不知朝有饥。","问曾辟谷否，擘树嚼松芝。"]},{"t":"五月六月雨寒二十馀日","f":"七言律诗","c":["五月今年更索裘，穷山积雨冷于秋。","斯须变化真难料，宿昔沉绵幸少瘳。","老强读书犹有益，贫因知道故无忧。","葵花零落浑閒事，且望田家早稻收。"]},{"t":"五月初十日病体少苏","f":"七言律诗","c":["仙棋一局烂樵柯，尘世纷纷梦幻多。","病起镜中非复我，愁来酒外更无它。","逍遥悟解参庄叟，矍铄形容谢伏波。","忽省明朝又生日，暮年归计欲如何。"]},{"t":"五月初三日雨寒痰嗽","f":"七言律诗","c":["门外葵花一丈高，讵期端午更绵袍。","佩符岂有玉刚卯，挑药久无金错刀。","人老形骸宜瘦劣，时危心肺倍焦劳。","柴门昼掩身多病，听雨寒窗首屡搔。"]},{"t":"仇仁近之姑苏别后奉寄","f":"五言律诗","c":["诗眼到姑苏，今愁古恨俱。","台惊吴后鹿，江问汉时鲈。","矫夺风应息，怀襄气未苏。","梅边早回首，飞鹤望林逋。"]},{"t":"仇仁近母邢夫人挽诗","f":"五言律诗","c":["慈颜才一识，近获拜书楼。","忽化金棺火，应添石室筹。","乡邻传阃范，吊祭尽儒流。","令子今和靖，诗名甲此州。"]},{"t":"以桐江旧诗十五卷呈范君泽","f":"七言律诗","c":["人品悬知大不同，一丝羞见钓台风。","七年假守如虚叟，万首新诗似放翁。","贷死偶馀吟鬓白，每生犹想战尘红。","范侯胸次秋天碧，好借宽閒翼断鸿。"]},{"t":"元夕晴","f":"七言律诗","c":["渐暖风烟添软媚，新晴草木眩光晶。","天回地转春犹在，物是人非意自惊。","晚辈未宜欺老病，早年犹及见升平。","山城旧与钱塘似，灯火笙歌彻五更。"]},{"t":"元日小雨","f":"七言律诗","c":["红垂灯穗倍常明，缓缓晴须作好晴。","著柳春风微有色，催花夜雨细无声。","炉香早起蹒跚拜，杯酒朋来潋滟倾。","一日一诗旧年例，新年一日两诗成。"]},{"t":"元日感事","f":"七言律诗","c":["羞将白发见青春，世事何关虮虱臣。","去就时难千里梦，是非论定百年身。","偶然不死由天地，尚可无惭对鬼神。","敢问名垂汉唐史，萧曹房杜本何人。"]},{"t":"六十五春寒吟七首 其四","f":"七言律诗","c":["病骨春寒欠酒浇，关山满眼雁程遥。","有人恨过江淹赋，何处魂堪宋玉招。","六十五翁来日短，百千万事迅风飘。","平生知己惊俱尽，一影穷山伴寂寥。"]},{"t":"六十五春寒吟七首 其七","f":"七言律诗","c":["知旧惊嗟踵丧亡，劣容此老据藜床。","六旬有五犹穷健，百拙无双但醉狂。","莳菜连畦终岁饱，种梅匝屋满家香。","不须苦怨春寒恶，榾柮炉边味最长。"]},{"t":"六十五春寒吟七首 其六","f":"七言律诗","c":["性癖耽吟本不工，平生竟复坐诗穷。","状头浪说三千字，举手行为七十翁。","夜永自怜灯是伴，春寒最苦酒难中。","王侯蝼蚁终同尽，便出阳神也落空。"]},{"t":"六十五春寒吟七首 其五","f":"七言律诗","c":["清晓林禽百种鸣，春寒渐暖变新声。","向阳死草青先茁，解冻枯池绿再生。","太子四门何足怪，麻姑三海自堪惊。","回头最念儿童辈，不识灯宵旧太平。"]},{"t":"六十五春寒吟七首 其三","f":"七言律诗","c":["老眼閒中子细看，天公作剧故多端。","雪占岁稔何曾稔，雨作春寒断是寒。","酒尽闷多欢笑少，花开折易长成难。","暮年不喜金仙说，到此心才悟六观。"]},{"t":"六十五春寒吟七首 其二","f":"七言律诗","c":["当是平生取数多，穷途无力战群魔。","二千石滥知州事，三十年羞进士科。","人老决难重少壮，春寒毕竟渐晴和。","筹来算往终无益，且傍残梅作醉歌。"]},{"t":"六十五春寒吟七首 其一","f":"七言律诗","c":["日日春寒昼掩扉，惊嗟六十五年非。","未为白傅同州起，犹胜坡翁海外归。","斗分军兴群盗作，浙乡水患细民饥。","忍穷苟活犹閒管，痛惜残梅万点飞。"]},{"t":"六十吟五首 其五","f":"七言律诗","c":["昼暑微遒暮已凉，中秋近□更重阳。","少时痛饮不胜乐，老病积忧无此狂。","岁六十翁扶药饵，家三百指望裘裳。","空庭月侧荒山悄，起望星河夜慨慷。"]},{"t":"六十吟五首 其四","f":"七言律诗","c":["三十年将一世论，缪悠两世见儿孙。","纷纭往事皆如梦，漫浪虚名独许存。","蚤遣候虫忧敝絮，悬知寿客笑空樽。","径芜阶叶无人扫，卧听秋风昼掩门。"]},{"t":"六十吟五首 其三","f":"七言律诗","c":["开岁当为耳顺翁，知非又过十秋风。","尚多儿女婚姻□，□使田园伏腊空。","迎菊作诗先自喜，设茶当酒未为穷。","顽躯定不缘愁死，纵死还如不死同。"]},{"t":"六十吟五首 其二","f":"七言律诗","c":["六十曰耆七十稀，西山能有几□□。","宾鸿蛰燕秋如故，朗月清风事总非。","美酒难求周九鼎，丽人多僣管三归。","衰荣颠倒知何意，草上谁家露不晞。"]},{"t":"六十吟五首 其一","f":"七言律诗","c":["六十衰年万事尝，西风回首战争场。","科名官职俱虚幻，学问文章总废忘。","死见几人饶酷毒，生怜此老尚昂藏。","故应许似篱边菊，百种花残独傲霜。"]},{"t":"六月二十九夜","f":"五言律诗","c":["小阁微凉上，閒人半醉中。","双明萤度水，一向柳拖风。","委曲聊随俗，艰难敢讳穷。","香山吾不逮，犹胜杜陵翁。"]},{"t":"六月二十二日守陴百姓始下城","f":"五言律诗","c":["本不食官粟，亦令登敌楼。","鸣桴木杪急，传箭夜深愁。","暗蹑蛇缠膝，尘搔虱满头。","传闻贼寨破，今日得归休。"]},{"t":"六月二十八日立秋","f":"七言律诗","c":["平生为客太匆匆，已上西江又复东。","只信一朝飞舴艋，何知五度落梧桐。","绝怜牛女常遭谤，粗足莼鲈不叹穷。","世外世间异天壤，政须深谷卧秋风。"]},{"t":"六月二十三日立秋喜闻贼平镇将凯回归府官俱还","f":"五言律诗","c":["乱起杏花落，贼平梧叶飞。","顿忘三伏暑，竟解万山围。","大将伤流矢，诸军曳血衣。","先登不如此，焉得凯歌归。"]},{"t":"六月二十日雨","f":"五言律诗","c":["天怜野老饥，初不待人祈。","雷与奔腾骤，烟兼映带微。","已拚泥弊屣，更喜滴单衣。","暗想田塍上，禾秋蚱蜢飞。"]},{"t":"六月二十四日秋夜书","f":"五言律诗","c":["昨朝交末伏，今日立新秋。","故是凉犹未，终须热渐休。","酒醒兴午夜，月上倚西楼。","暍死端能免，江天问去舟。"]},{"t":"六月八日迁寓侍郎桥","f":"七言律诗","c":["梧桐楼外雨萧萧，客里迁居意不聊。","净土偶邻罗汉洞，閒人肯羡侍郎桥。","蠹鱼书少家何窘，行李船轻路匪遥。","此□十翁肯相送，典钱沽酒了今朝。"]},{"t":"六月十七日十八日大雨闻贼欲降","f":"七言律诗","c":["谁遣青天变漏天，人閒无复有平田。","女娲鍊石端何物，子产禜龙未必然。","死徙衔冤终不雪，生存忍饿更堪怜。","腐儒自笑穷今极，旬月曾无一醉眠。"]},{"t":"六月半屡雨","f":"五言律诗","c":["甘雨作丰年，尤宜近伏天。","水无过大海，旱不救良田。","六月茅檐滴，千村饭灶烟。","山城秋意早，新粒市香籼。"]},{"t":"六月初七日雨始止初八日始晴","f":"五言律诗","c":["昨夕星初见，兹晨雾亦披。","徯闻平贼报，先赋喜晴诗。","□□犹如旧，新蝉未觉迟。","皇天已悔祸，小丑复奚为。"]},{"t":"六月雨","f":"五言律诗","c":["六月今年雨，千山每日云。","稻登全可望，树密最宜闻。","预免忧饥色，先收破暑勋。","稍容骄蛤黾，且为屏蝇蚊。"]},{"t":"立秋","f":"七言律诗","c":["斗杓忽又指西楼，我独何为此滞留。","多事心情人转老，荒城风雨夜争秋。","一蓑屡费渔樵梦，杯酒难湔宇宙愁。","好趁微凉便归去，豆花篱落荻花洲。"]},{"t":"分韵实得閒字再赋","f":"五言律诗","c":["一城最高处，晚色引跻攀。","莽莽斗牛野，重重吴越山。","秋将佳句画，人共老僧閒。","聚首非容易，何妨酩酊还。"]},{"t":"壬寅生日别赋","f":"七言古诗","c":["南踰梅岭北冰天，跋涉艰危□□怜。","颇赖青州从事力，□过绛县老人年。","稍同气臭能□□，□□□□□□□。","□□八旬苦多病，且须烂醉海榴前。"]},{"t":"壬寅立春在辛丑十二月二十九日归□□□三宿","f":"五言律诗","c":["隔日春先立，崇朝岁始除。","去来身不定，好恶梦皆□。","□□千山外，舟车一月馀。","岂真休客担，犹□□家书。"]},{"t":"太公孔子","f":"七言律诗","c":["禔身涉世谩多忧，运去时来不自由。","孔子三千难变鲁，太公八十尚兴周。","星辰岁久常差度，江海潮生会倒流。","万有盈亏理如是，可须悭作醉乡游。"]},{"t":"太湖观雪","f":"七言律诗","c":["平生不信有升天，今日临风似欲仙。","海内百年诗客眼，雪中一叶太湖船。","绵绵草树渔汀远，续续茅茨野屋偏。","定是丹青不能画，一浇殊欠酒如泉。"]},{"t":"文公书院新创","f":"七言律诗","c":["新堂育士焕榱椽，突起文公故宅边。","孟子向来推亚圣，邹人谁不企先贤。","遗书会萃垂千古，缺典因循近百年。","为问杏坛旧邻里，颜曾以后岂无传。"]},{"t":"文公故居有怀","f":"七言律诗","c":["慷慨怀人独倚楼，定应故国此神游。","共知道派传洙泗，犹觉文星贯斗牛。","八佾舞移谁有鲁，两楹梦断已无周。","先生不遇关何事，更作离骚一段愁。"]},{"t":"方去言府判挽诗二首 其二","f":"五言律诗","c":["壬戌同登日，秋崖尚见之。","王家子敬字，谢氏惠连诗。","乡校六龙渡，宗盟七桂枝。","残碑麟笔绝，后死叹吾衰。"]},{"t":"方去言府判挽诗二首 其一","f":"五言律诗","c":["诸老非前日，吾宗有若人。","大圭全粹质，劲柏挺长身。","仓卒完乡县，艰难寝战尘。","深惭铭笔短，未足永坚珉。"]},{"t":"无物","f":"五言律诗","c":["一屋无他物，荒山此僻居。","小儿差类我，老马最怜渠。","久绝樽中酒，空堆架上书。","顽躯犹不死，晚节竟何如。"]},{"t":"日长至寓杭 其二","f":"七言律诗","c":["自从丱角至童颠，是事无心总听天。","今日喜逢长至日，来年恰遇古希年。","一官三纪閒居半，万马千军命偶全。","适有蜜蜂肯伴我，晴香烂醉玉梅前。"]},{"t":"日长至寓杭 其一","f":"七言律诗","c":["閒身不想入鹓行，家近何分客与乡。","所喜今年年最稔，又逢此日日初长。","云容顿改不为雨，雪意尚悭仍作霜。","岂意老翁开八帙，朋来聊与共清觞。"]},{"t":"水亭待孙元京遇之归途","f":"五言律诗","c":["独向水亭坐，未闻诗友来。","入城还偶遇，下马与同回。","各已泥双屦，终难致一杯。","菰蒲偃微雨，忽见野莲开。"]},{"t":"牛头岭下老人","f":"五言律诗","c":["九十前朝老，髯疏骨亦清。","相形宜老寿，说梦忆升平。","田屋临官道，孙男给递兵。","兴州馘狂贼，曾见捷旗行。"]},{"t":"见李提学所和诗次韵","f":"七言律诗","c":["南来藉藉已声先，遥挹清扬意谓然。","果见新诗金掷地，始知馀子管窥天。","三书光范门前拜，一斗长安市上眠。","旧日猖狂俱已矣，输君衡鉴政高悬。"]},{"t":"计桐江续稿九卷卷百首书其末","f":"五言律诗","c":["诗律中年悟，嫌工更恐肥。","独行无与语，每出又空归。","姜枣频煎药，袍衫屡换衣。","病身自无赖，犹忍泄天机。"]},{"t":"长安","f":"七言律诗","c":["客从函谷过南州，略说长安旧日愁。","仙隐有峰存紫阁，僧居无寺问红楼。","兰亭古瘗藏狐貉，椒壁遗基牧马牛。","万古不随人事改，独馀清渭向东流。"]},{"t":"长至日书","f":"七言律诗","c":["年年春至此胚腪，地上严凝地底温。","能几蟾蜍圆月魄，即须霹雳起雷门。","知时久偃蛟龙势，养气深培草木根。","表里阳和见天道，梅花别是一乾坤。"]},{"t":"丙申生日七十自赋二首 其二","f":"七言律诗","c":["一尺光阴七寸馀，暗惊前路恐无馀。","匹如月欠三分满，又似蓂飘六片初。","学问文章俱废忘，科名官职总空虚。","诸孙中有小丁亥，十岁应能读我书。"]},{"t":"丙申生日七十自赋二首 其一","f":"七言律诗","c":["先君无罪谪封川，天畀遗孤出瘴烟。","忽到古希年七十，犹思上大化三千。","苦吟足可编诗史，狂醉真宜号谪仙。","五子传家无一物，聊将书册当青毡。"]},{"t":"丙申重九前后得今日都无病一句成十首 其十","f":"五言律诗","c":["今日都无病，閒将往事思。","不为一己计，宁受百人欺。","老钝文章拙，温恭礼数卑。","临风一杯酒，此意未全衰。"]},{"t":"丙申重九前后得今日都无病一句成十首 其九","f":"五言律诗","c":["今日都无病，持杯得自如。","空行万里路，枉读一生书。","可奈多魔障，真当弃腐馀。","休官十六载，此计未全疏。"]},{"t":"丙申重九前后得今日都无病一句成十首 其八","f":"五言律诗","c":["今日都无病，重阳倏又过。","浊醪常醉好，佳菊未开多。","岂必皆时节，焉容不啸歌。","一樽二三友，风雨奈予何。"]},{"t":"丙申重九前后得今日都无病一句成十首 其七","f":"五言律诗","c":["今日都无病，黄花酒一觞。","登临怜老者，风雨过重阳。","稔岁真希有，南天始欲凉。","馀生容苟活，不敢昧苍苍。"]},{"t":"丙申重九前后得今日都无病一句成十首 其六","f":"五言律诗","c":["今日都无病，重阳酒满樽。","浅斟聊慰意，高枕恐消魂。","杜老萸难得，陶家菊尚存。","邻人送糕果，遥忆小儿孙。"]},{"t":"丙申重九前后得今日都无病一句成十首 其五","f":"五言律诗","c":["今日都无病，移盆看菊花。","极知诗易脔，唯苦酒难赊。","政用匆匆过，何妨小小差。","重阳七十度，大半在天涯。"]},{"t":"丙申重九前后得今日都无病一句成十首 其四","f":"五言律诗","c":["今日都无病，今年粗慰心。","西风田畯喜，南斗岁星临。","人老颜如雪，家贫菊似金。","典衣作重九，犹可一杯斟。"]},{"t":"丙申重九前后得今日都无病一句成十首 其三","f":"五言律诗","c":["今日都无病，沉吟算此生。","誓将全晚节，懒复问脩程。","畏事防忧患，收心入老成。","近时学康节，更敢竞时名。"]},{"t":"丙申重九前后得今日都无病一句成十首 其二","f":"五言律诗","c":["今日都无病，康强百不忧。","近霜黄菊月，过雨紫兰秋。","可醉岂容避，欲归遄复休。","寒衣浆补办，此外更何求。"]},{"t":"丙申重九前后得今日都无病一句成十首 其一","f":"五言律诗","c":["今日都无病，清晨独倚楼。","端能常自遣，孰谓不堪忧。","老谢人间事，寒添雨后秋。","江天诗满眼，可似贾胡留。"]},{"t":"丙戌十一月二十八日南至寓杭","f":"五言律诗","c":["卧厌邻人聒，晨兴亦喜晴。","心知云气好，眼眩日华明。","吾事元无节，南方暂偃兵。","新妆小儿女，谁识旧承平。"]},{"t":"丙戌元日二首 其二","f":"七言律诗","c":["歙山严濑寄荆扉，想见同时雪正飞。","柳动梅残惊岁换，儿寒女瘦望予归。","百年偏许诗名在，双鬓能知世事非。","社友踏泥肯相顾，酒钱更欲典春衣。"]},{"t":"丙戌元日二首 其一","f":"七言律诗","c":["犹忆儿时襁褓中，天南跋涉到江东。","间关岭海三千里，倏忽星霜六十翁。","追远无涯心事苦，苟生何益暮途穷。","雪消日薄寒尤力，独倚危楼数过鸿。"]},{"t":"丙戌除夕次韵仁近二首 其二","f":"五言律诗","c":["盆梅开欲尽，翠干已苔深。","物极容春蛰，人穷自陆沈。","钟知浮世事，灯识老儒心。","冶陌饶芳草，衰迟肯重寻。"]},{"t":"丙戌除夕次韵仁近二首 其一","f":"五言律诗","c":["岁穷犹此客，不早见几微。","岂易赊邻酝，何惭典故衣。","馀寒当有几，小忍未为非。","野烧回青润，春山饱蕨薇。"]},{"t":"东山庙","f":"七言律诗","c":["灵迹从来擅胜游，兹山亦复甲吾州。","杉腰一殿悬金屋，云脚千家耸画楼。","钟鼓邻僧新院宇，桑麻平世旧田畴。","乾坤大数谁能问，生者聊存死即休。"]},{"t":"东晋","f":"七言律诗","c":["刘琨劝进岂无闻，王猛临终亦有云。","秽史汝能诬正统，老伧谁实莅馀分。","山阴禊事流觞帖，彭泽归来植杖文。","二物万年终不泯，可能草木张吾军。"]},{"t":"乍归呈许君公度","f":"七言律诗","c":["东南天地早闻名，三载吾邦沸颂声。","山好更饶诗句好，江清未抵使君清。","涓涓流水秧田足，细细吹风麦陇晴。","客子归来问耕穫，故园似可养残生。"]},{"t":"代次韵闻砧","f":"七言律诗","c":["谁家秋夜捣衣声，遥忆良人在戍营。","野宿貔貅天一角，树移乌鹊月三更。","怨怀想像闺中切，逸韵悠扬枕上清。","砧杵催成岁迟暮，抚时亦觉壮心惊。"]},{"t":"出马家坞","f":"五言律诗","c":["野迥夏无暑，坞深朝更凉。","路随流水转，山背古城荒。","县宇攲红阁，僧庵缺粉墙。","暗惊兵乱后，犹有数莲塘。"]},{"t":"出歙港入睦界","f":"五言律诗","c":["岚气湿征衣，千滩落翠微。","悬崖樵屋小，破庙祭人稀。","岸犬看船立，溪禽贴水飞。","乡心与客思，向晚重依依。"]},{"t":"古店","f":"五言律诗","c":["古店看题壁，儒风岂易还。","匪因登贡籍，即为叩贤关。","腾踏云霄上，沉埋草莽间。","其人俱已矣，遗迹尚斑斑。"]},{"t":"句容道中","f":"五言律诗","c":["陂满风初漾，林明雪未残。","路泥尤觉远，野阁不胜寒。","军过开门少，村稀觅店难。","忽逢新日色，久别喜相看。"]},{"t":"叹士行","f":"五言律诗","c":["学问何难博，文词亦易工。","自非知道理，更是长奸雄。","饰首冠章甫，操心窃大弓。","金椎发冢辈，张竦与陈崇。"]},{"t":"叹笑","f":"五言律诗","c":["意外无忧恼，予心岂厌贫。","索钱纷债主，赊药愧医人。","坐丧高标尽，时惊俗态新。","残书亦懒读，满架付埃尘。"]},{"t":"四月二十九日早起行园","f":"七言律诗","c":["白发萧萧一秃翁，披襟扶杖早凉中。","偶因不饮全无寐，自笑能诗例得穷。","梅雨园林江橘绿，竹风庭院海榴红。","若非守禦孤城闭，谁有幽居似此公。"]},{"t":"四月二十二日别江州谢送者","f":"五言律诗","c":["出城烦送客，童稚亦相随。","貌比初来老，行因共语迟。","桥边分手后，马上转头时。","欲识阳关曲，唯须诵此诗。"]},{"t":"四月二十六日雨后添严军南击贼寨","f":"五言律诗","c":["端许忧差减，宁容病寖侵。","添兵薅草寇，垂早降梅霖。","寨破山无险，田高水亦深。","著书垂不朽，或可遂初心。"]},{"t":"四月二十日客言兵所不至麦有黑虫食之","f":"五言律诗","c":["望望遥峰外，行行茂树中。","愁添诗鬓白，旱觉战尘红。","已叹桑无茧，何期麦有虫。","南薰元不改，千古舜弦风。"]},{"t":"四月十三日立夏","f":"五言律诗","c":["百年春一年，四月月将圆。","客邸淹长日，归途逼暑天。","莺声时一啭，蚕事欲三眠。","节物还如旧，情怀自可怜。"]},{"t":"四月初九日清和绝佳闻贼焚歙南路蔓延五十馀里","f":"五言律诗","c":["小园无客至，独坐一绳床。","霁日千林净，薰风四月凉。","禽鱼完孕育，草木竞芬香。","姓命人难得，何为有战场。"]},{"t":"四月初十日得蜂虿茧丝之句","f":"五言律诗","c":["深言惧忤时，聊复一评之。","靡暇防蜂虿，惟工竭茧丝。","因循终不恤，平定岂无期。","麦赭秧田废，人家半忍饥。"]},{"t":"市行","f":"五言律诗","c":["徒步无车马，颓然一秃翁。","早班朝士底，还杂市人中。","所向都非旧，焉能独不穷。","否臧元自在，芳秽未俱空。"]},{"t":"平心胡秘监诞日","f":"七言律诗","c":["五朝遗老四专城，年号凡经十四更。","八帙即今踰少壮，七人从昔冠耆英。","冻窗映雪能坚坐，泥屐看山只步行。","清健如公天下少，平心心事十分平。"]},{"t":"平章吕公挽词二首 其二","f":"五言律诗","c":["燕颔逢荆鄂，于今四十秋。","始闻降鬼国，遄见拔泸州。","庙议颛私意，边围堕诡谋。","弃襄不令守，铁锁靠江流。"]},{"t":"平章吕公挽词二首 其一","f":"五言律诗","c":["难兄捐阃寄，无复救襄人。","半纪婴孤垒，中朝扼柄臣。","秦非里奚智，徐为偃王仁。","万事由天命，乾坤历数新。"]},{"t":"归兴","f":"七言律诗","c":["投老深知万事难，骨骸熬暑又煎寒。","暗量已觉穷无敌，退省犹须强自宽。","稚子能吟青玉案，异人初付紫金丹。","先生归去山中好，剩有閒云许细看。"]},{"t":"戊子元日丹阳道中二首 其二","f":"七言律诗","c":["轧轧箯舆猎晓霜，孤征无复共椒觞。","浮生物物身为累，垂老年年节是常。","稍听村田喧鼓笛，遥怜儿女欠衣裳。","于潜西上王干路，苦忆茅柴白酒香。"]},{"t":"戊子元日丹阳道中二首 其一","f":"七言律诗","c":["夜卧田家牯犊傍，晨兴籼饭煮葱汤。","阨穷未觉英豪耻，清苦应容寿命长。","客路天晴聊可喜，家园春动自难忘。","已欣旧岁交新岁，却向丹阳忆紫阳。"]},{"t":"戊子生日","f":"七言律诗","c":["去年苦雨客西湖，汤饼经营至午无。","穷老复能逢顺境，归林聊得保残躯。","亲情饮食烦相问，朋友歌诗似稍腴。","永感情怀更衰病，可怜儿辈事庖厨。"]},{"t":"戊戌元日三首 其三","f":"五言律诗","c":["彷佛晓钟鸣，家家起五更。","物宜春后暖，人喜岁初晴。","衰老犹能饮，虚空误得名。","题诗思旧日，无此好新正。"]},{"t":"戊戌元日三首 其二","f":"五言律诗","c":["炉香礼天地，再过古来稀。","此日仍逢节，何时定许归。","年高还拜怯，客窘久留非。","遥忆小儿女，新春只故衣。"]},{"t":"戊戌元日三首 其一","f":"五言律诗","c":["班春踰半月，献岁换新正。","马动人声喜，星明晓意晴。","寒袪和气胜，病愈老身轻。","七十二年事，沉吟暗自惊。"]},{"t":"戊戌生日二首 其二","f":"五言律诗","c":["客舍逢生日，邻家送寿星。","循彝须答礼，恃熟莫忘形。","把笔迟赓和，开樽共醉醒。","五儿一随侍，心窃愧椿庭。"]},{"t":"戊戌生日二首 其一","f":"五言律诗","c":["贪得真迷境，持平实悟门。","未妨人负我，各要子生孙。","动辄闻谁死，猗嗟幸独存。","荣华何足记，衰悴不须论。"]},{"t":"正月二十一日偶题","f":"七言律诗","c":["楼头日日倚危栏，来往人忙许静看。","老子无聊常□□，杏花欲动更春寒。","虚名畴昔三千字，险路平生百八盘。","挥翰玉堂有公相，閒人赢得把渔竿。"]},{"t":"正月十日始晴","f":"七言律诗","c":["穗历桃符漫告新，漆肌蓬鬓转成陈。","暮年多病全无赖，积雨初晴略似春。","香火荒山犹古庙，兵戈故国仅遗民。","承平旧俗吾能忆，差胜如今一辈人。"]},{"t":"正月三日立春","f":"五言律诗","c":["曾戴金幡胜，如今有几人。","尚能容白发，屡得见青春。","定力忘寒燠，冥怀任屈伸。","遥知残雪地，即复化为尘。"]},{"t":"正月四日大雨不已愈暖不寒","f":"七言律诗","c":["吴山胜概甲杭州，正旦晴明到上头。","红袖南人簪翡翠，金鞍北客骤骅骝。","丰年似觉春尤好，新岁何为雨不休。","自笑诗翁百念冷，尚侪痴子说閒愁。"]},{"t":"正月初二日晴过常州","f":"七言律诗","c":["客里三年问岁除，毗陵归路又正初。","自怜囊涩难沽酒，犹喜船宽可读书。","草比旧痕青已倍，雪成陈迹白无馀。","脱寒就暖真奇事，差觉穷途意气舒。"]},{"t":"正月初三日水西寺","f":"五言律诗","c":["不到水西久，十年怀梦思。","重行兵后路，暗觅壁间诗。","僧出房俱鐍，人游榼自随。","隔溪望城郭，未觉似春时。"]},{"t":"正月连雨","f":"七言律诗","c":["新年未有一诗新，转觉羁怀感慨频。","人日直连元日雨，梅花合让杏花春。","避愁愁不拾孤影，怕冷冷偏缠老身。","几夜五更了无寐，床头黠鼠亦欺人。"]},{"t":"永乐沽酒","f":"七言律诗","c":["大寒岂可无杯酒，欲致多多恨未能。","楮币破悭捐一券，瓦壶绝少约三升。","村沽太薄全如水，冻面微温尚带冰。","爨仆篙工莫相讶，向来曾有肉如陵。"]},{"t":"汉","f":"七言律诗","c":["灯前閒覆孟坚书，瞬息炎刘四百馀。","五聚井星才属尔，一抔陵土竟何如。","早誇发纵轻烹狗，终藉吞舟失漏鱼。","若使高皇为晋献，可须莽卓始丘墟。"]},{"t":"生日又二首 其二","f":"七言律诗","c":["岂料生逾七十年，孩提脱死瘴乡烟。","未能汤饼觞朋友，祇合炉香拜祖先。","养性有书知道理，夺胎无药学神仙。","天都峰下旧茅屋，消得严滩十日船。"]},{"t":"生日又二首 其一","f":"七言律诗","c":["畏途偶许玩馀生，晚节尤难保令名。","一秃翁真韩长孺，五男儿可晋渊明。","凄风开户绵重著，漏雨溅床酒懒倾。","俗事沓来败人意，且须坚坐待天晴。"]},{"t":"生日再书","f":"七言律诗","c":["汤饼随缘和酱醯，六年三潦念民饥。","重逢白发人生日，愿见黄梅雨止时。","诗好远过千岁寿，家贫深负五男儿。","许身稷契杜陵老，岂谓残生乃至斯。"]},{"t":"生日后三朝又书","f":"七言律诗","c":["□□七十六年春，湖海飘零一病身。","相爱故人誇寿相，远□儿子作生辰。","齿浮声嗄调凉剂，发少头疮爪破巾。","只合归欤办棺冢，断无华表石麒麟。"]},{"t":"生日病中","f":"五言律诗","c":["偶复逢生旦，何知迫死期。","老真难亸病，贫实怕迎医。","自拟修埋志，谁犹□寿诗。","不应六旬叟，未减一分痴。"]},{"t":"用五男儿再赋","f":"七言律诗","c":["每于生日赋新诗，似觉今年老更痴。","窃谓齐公千驷马，岂如陶氏五男儿。","能拚久客常沉醉，不念全家惯忍饥。","七十尚争三屈指，挂冠一纪此差奇。"]},{"t":"用夹谷子括吴山晚眺韵十首 其二","f":"七言律诗","c":["三吴百越楚天宽，不厌登临不厌观。","画舫红桥随处有，丹楼碧宇倚空寒。","梅边吟思春光早，雁外归心夕照残。","灯火沙河塘上路，岂无冻屋卧袁安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其十","f":"七言律诗","c":["眼底胸中稍放宽，超然何肯惑荣观。","馀年早已知天命，古道谁堪共岁寒。","驿使寄梅心独远，禅师分芋口无残。","十诗说尽登临意，我但徐行步步安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其九","f":"七言律诗","c":["极目无穷六合宽，仰天如以浑仪观。","日躔箕斗逢长至，月宿奎娄届大寒。","肘后方多难却老，杯中物到莫留残。","来年七十身犹健，容膝归欤亦易安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其八","f":"七言律诗","c":["情知新国用刑宽，坐致湖山复旧观。","浙右谁非三世宦，江南终不十分寒。","钱王陌上花犹好，苏小门前柳未残。","革故鼎新谁料得，举安天下胜偏安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其七","f":"七言律诗","c":["荡荡天宽眼亦宽，区区笑尔井中观。","帆来狗国毛人远，楼倚牛郎织女寒。","迅速年华榆燧改，槁枯世味蔗滓残。","绝怜棺粪纷纷梦，未必槐安果是安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其六","f":"七言律诗","c":["一锥无地百弓宽，万事须分两眼观。","仙子楼居凌倒景，野人卉服耐奇寒。","金钗玉斝春帷满，黄卷青灯晓漏残。","兴废荣枯手翻覆，几家能遣子孙安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其五","f":"七言律诗","c":["泰伯封疆四望宽，胜将吴越旧书观。","苧罗山下春才到，麋鹿台边沼已寒。","不有采香专怙宠，可能尝胆便除残。","今年木德临心宿，重见家家衽席安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其四","f":"七言律诗","c":["抖擞羁怀强自宽，时登吴阜一閒观。","陆机不作莼羹在，雷焕无踪剑气寒。","倏忽池台荒草合，等閒歌舞落花残。","兴亡生死真常在，命要深知分要安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其三","f":"七言律诗","c":["梯天直上俯平宽，故国繁华尚可观。","西子有船春色去，伍员无庙暮涛寒。","九原事往人难问，四序功成岁又残。","米贱酒平慰迟暮，巢林聊得一枝安。"]},{"t":"用夹谷子括吴山晚眺韵十首 其一","f":"七言律诗","c":["湖共江宽更海宽，遥天纵玩复横观。","雅知山对吟肩瘦，未怯霜欺醉面寒。","感召丰登饶粒食，抚摩瘦敝起彫残。","生灵百万俱高枕，公亦官清梦寐安。"]},{"t":"用前韵改一二语自释","f":"七言律诗","c":["南寒稍近折绵天，葵荠争承小雨怜。","冻合远峰应有雪，炊残荒市更无烟。","未妨夜画炉中箸，何苦晨呵袖里鞭。","人事好乖行路恶，政应委顺付怡然。"]},{"t":"用前韵酬孟君复二首 其二","f":"七言律诗","c":["眼空敢谓世无人，松菟相依似有神。","邂逅十洲三岛客，崎岖万死一生身。","深斟满酌堪同醉，雪鬓霜髯愧不春。","别后诗筒恐难数，何如聊尔倡酬频。"]},{"t":"用前韵酬孟君复二首 其一","f":"七言律诗","c":["吞若虞翻梦里爻，古人不死与神交。","成名永保传青简，临事终当藉白茅。","足可一瓢居陋巷，岂堪二膳养东胶。","龟藏六用泥中乐，未信时人蝘蜓嘲。"]},{"t":"用韵送唐师善归九仙二首 其二","f":"七言律诗","c":["李长庚愿识荆州，马伏波今愧少游。","古道直能胶凤觜，官身焉取烂羊头。","苦心文字雕奇劂，遁世林峦擅僻幽。","鹤竹蜂花有家法，唐瓢更向外人求。"]},{"t":"用韵送唐师善归九仙二首 其一","f":"七言律诗","c":["杞菊先生误作州，归来谁复与同游。","蓑衣正可眠牛背，肉食终非相虎头。","欲起黄陈分宇宙，能穿草树憩深幽。","相看不用多言说，须向拈花笑处求。"]},{"t":"用韵谢湖州总管李才甫附周汉东寄声","f":"七言律诗","c":["文章太守与谁游，山水江南第一州。","试向清风明月内，得非与可子瞻不。","生徒时喜高轩过，英俊多蒙□□□。","冷掾能言修学事，殿堂新葺更书楼。"]},{"t":"甲申元日","f":"七言律诗","c":["春光几度九十日，人寿都卢一百年。","老圃地宽花富贵，醉乡天阔酒神仙。","谁能晚节消閒福，时喜新诗得警联。","晓色欲红拜元造，炉熏一炷鹊声前。"]},{"t":"甲申生日","f":"七言律诗","c":["劬劳永感正关情，厚意殷勤荷友生。","隔日移庖成剧醉，终朝攲枕困馀酲。","略加芎煮香苏饮，少著盐庖苦荬羹。","数首诗词懒酬和，杜门止酒始神清。"]},{"t":"白云李处士于大樗下筑小庵用题王子由书斋韵赋之","f":"七言律诗","c":["天地元知一指齐，樗庵小小架榱题。","故应懒散身常健，孰谓昂藏意未低。","神气自调丹鼎火，仙班不藉紫芝泥。","落成此老来酣饮，酬爵端容据席西。"]},{"t":"白水寺","f":"五言律诗","c":["壁画暗金刚，无人犬吠堂。","翠苔千古润，玉水一寻方。","尘路云蒸火，阴林石凝霜。","仙凡元不远，咫尺异炎凉。"]},{"t":"白茅道中","f":"五言律诗","c":["世故时时异，年华物物新。","溪声添夜雨，麦事待晴春。","草棘扃空户，岩崖伏冻人。","问言何至此，征骑往来频。"]},{"t":"石门市","f":"五言律诗","c":["村村篱落似，慈竹密如云。","鬨市千家聚，康庄五郡分。","连门香白酒，倚户粲红裙。","今日寻荒店，无薪给午饙。"]},{"t":"立春日马上遇黄国宝应犀 其二","f":"五言律诗","c":["十载乱离频，何知有此辰。","翩跹果下马，突兀眼中人。","野店春盘共，僧房夜榻邻。","吾宗老仙伯，题墨尚如新。"]},{"t":"立春日马上遇黄国宝应犀 其一","f":"五言律诗","c":["连宵好梦频，二喜集佳辰。","晓霁逢春日，山深遇故人。","立谈询近事，小酌叩荒邻。","暮宿东松寺，吟眸处处新。"]},{"t":"立秋","f":"七言律诗","c":["暑赦如闻降德音，一凉欢喜万人心。","虽然未便梧桐落，终是相将蟋蟀吟。","初夜银河正牛女，诘朝红日尾觜参。","朝廷欲觅玄真子，蟹舍渔蓑烟雨深。"]},{"t":"立秋久无诗","f":"七言律诗","c":["三伏厌厌病欲萎，可能秋后尚无诗。","连宵急雨凉如洗，贪寐衰翁醉不知。","药饵谁精寸关尺，文章空说斗牛箕。","西斋池上堪逃暑，木落吾将信所之。"]},{"t":"立夏明日行园无客五首 其五","f":"七言律诗","c":["葺圃疏畦日荷锄，六旬老叟尚何图。","卧床迫夏犹毡褥，宴几经春只药炉。","群窃花枝相侮易，合携竹杖与驱除。","千金万卷皆捐弃，更有心情计较渠。"]},{"t":"立夏明日行园无客五首 其四","f":"七言律诗","c":["爱栽竹树爱栽花，新筑船轩傍石斜。","古庙炷香知某客，半山摇扇望吾家。","閒看红袖穿林去，可著冰纨作画誇。","说似渠侬应未信，诗翁烦恼政如麻。"]},{"t":"立夏明日行园无客五首 其三","f":"七言律诗","c":["尚欠佳篇与送春，祇缘醉卧动经旬。","偶无载酒相过客，始是吟诗自在人。","喜见笋芽穿瓦石，都忘雨点渍衣巾。","园林全赖东风力，莫道南风便有神。"]},{"t":"立夏明日行园无客五首 其二","f":"七言律诗","c":["春来何啻酒千瓶，百日醺醺一日醒。","朱笔点诗垂欲困，黄鹂啼树急须听。","沾沙不湿收微雨，倚柱无言立小亭。","芒屦犒僮人一緉，为耘恶草莫教青。"]},{"t":"立夏明日行园无客五首 其一","f":"七言律诗","c":["衲朝裌暮午衫单，始觉春归不再寒。","些子幽花三两亩，霎时啼鸟百千般。","世情落落全相背，诗律平平略放宽。","连日饮徒偶焉往，自炊香薤五盘餐。"]},{"t":"丞相大观文马公先生挽词三首 其三","f":"五言律诗","c":["天地干戈阻，门生合会丧。","谓传和相钵，有腼陆公庄。","衰钝辜陶冶，危疑去庙廊。","空怀精卫意，无奈海茫茫。"]},{"t":"丞相大观文马公先生挽词三首 其二","f":"五言律诗","c":["病笃辞台席，明年遂失襄。","少容公展布，岂遽国危亡。","此老为微子，吾君类偃王。","欺孤木绵鬼，寸斩亦何伤。"]},{"t":"丞相大观文马公先生挽词三首 其一","f":"五言律诗","c":["四载咸淳相，艰哉去国情。","极知几事密，或遂好谋成。","董卓徵荀爽，陈桓免晏婴。","为公翻左汉，尚觉寸丹明。"]},{"t":"仲夏书事十首 其十","f":"五言律诗","c":["暑月忆寒月，老身兼病身。","簟谁分长物，酒并缺贤人。","山市冰难致，家园蒜自珍。","黄芽冷香饮，回首叹扬尘。"]},{"t":"仲夏书事十首 其九","f":"五言律诗","c":["细酌浮菖酒，閒吟树蕙文。","卖符羞米贼，采药按桐君。","壬日近梅溽，午风生草薰。","湖航三纪梦，荷盖石榴裙。"]},{"t":"仲夏书事十首 其八","f":"五言律诗","c":["弃置乾坤事，归休水竹居。","不因徵急债，尽可读残书。","齑糁畬田粟，姜羹石涧鱼。","论文同小酌，未觉故人疏。"]},{"t":"仲夏书事十首 其七","f":"五言律诗","c":["劲瘦元弘博，凄酸忽壮豪。","为诗兼众体，此事属吾曹。","俗学三书虎，雄心六钓鳌。","兰枯菊犹短，不羡蜀葵高。"]},{"t":"仲夏书事十首 其六","f":"五言律诗","c":["菜梜朝酲后，茶瓯午困前。","入帘禽避弹，升灶蚁求膻。","观物因多感，谋生各务全。","蚕登新麦贱，田叟荷皇天。"]},{"t":"仲夏书事十首 其五","f":"五言律诗","c":["息担秋云季，扶犁夏欲中。","园林初畏日，里巷只雌风。","饼粥悭鱐脯，醯盐劣韭葱。","藕丝冰水旧，谁识少陵翁。"]},{"t":"仲夏书事十首 其四","f":"五言律诗","c":["閒身何所事，诗外别无心。","但见独危坐，焉知长苦吟。","兵戈生长老，梦幻去来今。","感慨亦徒尔，宾来酒且斟。"]},{"t":"仲夏书事十首 其二","f":"五言律诗","c":["南风吹密树，古屋隐林隈。","捲画防梅雨，镌诗惜石苔。","医书邻叟借，庵记野僧催。","细省仍微笑，犹胜走俗埃。"]},{"t":"仲夏书事十首 其三","f":"五言律诗","c":["幽居少四邻，长日属閒人。","石气常蒸雾，莺声不改春。","子钱偿未已，卯酒醉何频。","说与耘畦者，无锥未是贫。"]},{"t":"仲夏书事十首 其一","f":"五言律诗","c":["园林夏宜晓，叶叶溜晴光。","此地吾能净，非天独肯凉。","汲泉看马饮，刬草免蛇藏。","似亦为形役，终无市井忙。"]},{"t":"会张仲实宅得天字","f":"五言律诗","c":["兵甲更多难，桑榆迫暮年。","孰能容此老，犹得并诸贤。","空阔瞻乔木，推移叹逝川。","醉乡春有路，暂觉异寒天。"]},{"t":"全州吕农簿挽诗三首 其三","f":"五言律诗","c":["先公与进时，早诵小坡诗。","晚节遭多难，耆年对耄期。","家贫从俗笑，国破任身危。","后死元非福，前途未可知。"]},{"t":"全州吕农簿挽诗三首 其二","f":"五言律诗","c":["公田怨已盈，关币出尤轻。","稍欲输忠款，初非卖直声。","二千垂郡禄，五百存台评。","旧日朝天路，端门野草生。"]},{"t":"全州吕农簿挽诗三首 其一","f":"五言律诗","c":["谁实柄咸淳，无君欲不臣。","举朝皆谄子，此老独全人。","去国獒频嗾，居村虎自驯。","伤心诸狎客，容易竟亡陈。"]},{"t":"再六次韵徐子英江楼","f":"七言律诗","c":["最愁人处最高楼，空望三神想十洲。","大药不灵从老病，把茅犹在盍归休。","许追竹士陪梅友，肯羡蜂王慕蝶侯。","曾点当时未舍瑟，谁知心地异由求。"]},{"t":"再用雨不已韵答仁近","f":"七言律诗","c":["良苗所至已沈没，寄语云师盍少休。","暮境岂堪逢岁恶，腐儒可但为身忧。","败墙蛇出频穿户，湿柱蜗升欲上楼。","拟问邻酤破岑寂，督邮闻说酢如榴。"]},{"t":"再用前韵","f":"五言律诗","c":["此事谁知我，他年岂料今。","棋残才有眼，灯暗欲无心。","衰老常为客，山林故自深。","忘形侣猿鹤，可待整冠襟。"]},{"t":"再用前韵呈元煇二首 其二","f":"五言律诗","c":["天寒鸲鹆来，望雪上山台。","发少不重漆，眼昏犹识梅。","榨槽呼旋制，窑盎买连催。","新许民间酿，樽应日日开。"]},{"t":"再用前韵呈元煇二首 其一","f":"五言律诗","c":["谈拂风前竖，吟藤月下挑。","是非姑且置，来往不为遥。","蚁瓮营新漉，貂裘补旧硝。","聊同小隐隐，未用大招招。"]},{"t":"再次韵谢吴遁翁","f":"七言律诗","c":["一自为农去国赊，九天无路献忠嘉。","不争老杜广文饭，且共仰山鹙子茶。","字画故家元祐脚，篇章时样鄂州花。","它山待刻钟楼作，震撼烟霞十万家。"]},{"t":"再次韵赋飞雪数片","f":"七言律诗","c":["雨收霰止绝纤埃，压瘴迎丰兆已开。","欲积忍将靴踏去，初飘喜著袖盛来。","微微糁体寻生粟，稍稍粘枝辄乱梅。","不解高楼办歌舞，典衣亦合买新醅。"]},{"t":"再送罗云叔","f":"七言律诗","c":["欲共君归未有缘，春风夺我紫阳天。","牡丹富艳花如洛，煮白香浓酒似燕。","细看貌非寒士相，随宜班亚冷官员。","人间第一好山处，赋几篇诗醉几筵。"]},{"t":"再哭无竭禅师","f":"七言律诗","c":["倒撑无底船和尚，撑上西天是世尊。","万壑啼猿如下泪，一江明月与招魂。","涅槃满證无生果，解脱深参阿字门。","却笑孤山人未远，浪歌身异性长存。"]},{"t":"再读存心书","f":"五言律诗","c":["每报家书至，心如喜惧何。","欲开疑有故，已读幸无他。","典粥赀财罄，寒饥幼稚多。","衰门真可叹，两世误儒科。"]},{"t":"再赋典半宅","f":"五言律诗","c":["屋以多为贵，思之亦太愚。","灯膏徒重费，庖膳卒难呼。","榻外知何用，杯中不可无。","质钱分客住，得醉且频沽。"]},{"t":"再赋倚梅观雪以前诗太哀故","f":"七言律诗","c":["清莫清哉亦壮哉，茅庐何自致琼瑰。","江南胜赏无如雪，天下难题最是梅。","剪水玉蛾能送瑞，司花青帝想怜才。","老臣诗就天颜喜，叩齿当空酹一杯。"]},{"t":"再赋惜小骢二首 其二","f":"五言律诗","c":["骏骨直千金，难求起死针。","虽云为马□，却似有人心。","毡帐长城远，旗亭委巷深。","老身全赖此，完璧到如今。"]},{"t":"再赋惜小骢二首 其一","f":"五言律诗","c":["骏驶元奇崛，驯良蔑等伦。","穷途曾尽力，徒步始伤神。","未易营阿堵，何由肖乞银。","佛书端可信，当复转人身。"]},{"t":"再简吴式贤","f":"七言律诗","c":["郊居纵复远康庄，如许诗名许遁藏。","有客远来期识面，不吾遐弃例登堂。","眼高心远乾坤窄，树密泉深上下凉。","谁与图成后三笑，陶巾底用间缁黄。"]},{"t":"刘子华儒吏","f":"七言律诗","c":["短檠彻晓一灯寒，椰腹中藏万卷宽。","了事足为良吏易，读书真作大儒难。","隐身雁鹜虽常调，致位貂蝉可显官。","褒鄂功臣不须此，长枪挽出进贤冠。"]},{"t":"刘元煇来三首 其三","f":"五言律诗","c":["闻筑船亭就，能来共看花。","鲞枯庖海物，豆乳买邻家。","稍可从容饮，犹当委曲赊。","归途有底急，不肯后昏鸦。"]},{"t":"刘元煇来三首 其二","f":"五言律诗","c":["浪出惭何益，深居悔已迟。","积忧□□□，□□定非痴。","暗事人能料，幽怀世不知。","叩门有斯客，急以酒浇之。"]},{"t":"刘元煇来三首 其一","f":"五言律诗","c":["君宅蒲荷岸，吾庐槿菊篱。","相望能几步，不见动踰时。","老更甘清苦，閒应笑拙痴。","门迎到花底，衔袖有新诗。"]},{"t":"同川无竭观旃檀林东窗见婺州港定此为句","f":"七言律诗","c":["心欺劲竹傲长松，铁面霜严舌有锋。","遥指水光来婺□，□听乡语半吴侬。","贴诗满壁誇佳句，答话当机破□□。","□□归来大风雨，定知一钵已降龙。"]},{"t":"同刘仲鼎全君玉饮徐子英家分韵得鸡字","f":"七言律诗","c":["诘曲盘桓手共携，暮归了不记东西。","初筵秩秩谈无底，厦屋渠渠醉似泥。","老貌白头愧青鬓，豪吟野鹜杂家鸡。","相看一笑消长日，未信人间物易齐。"]},{"t":"同年常簿吴次翁子万之万之子直卿将为分水学官喜而赋之","f":"七言律诗","c":["一点书灯传不绝，王侯卿相复何加。","追惟大父同科第，喜见闻孙绍世家。","奥赜蚤能探理窟，芳妍孰敢竞词华。","勿言小邑青衿少，要使人人读五车。"]},{"t":"同曹清父西郊纪事五首 其五","f":"五言律诗","c":["朴略童蒙学，堆豗句读师。","有能致卿相，或不赡妻儿。","士故无他业，人谁此味知。","公庭彼为吏，日日醉歌姬。"]},{"t":"同曹清父西郊纪事五首 其四","f":"五言律诗","c":["风俗嗟颓落，文章委下陈。","出郊聊快目，谋野岂关身。","本为搜诗去，徒成泥酒频。","胸中知此事，眼底似无人。"]},{"t":"同曹清父西郊纪事五首 其三","f":"五言律诗","c":["木脱秋声尽，田空野鸟饥。","时危群盗惨，身老故人稀。","所至犹堪醉，无求自合归。","寥寥天地内，古意一何微。"]},{"t":"同曹清父西郊纪事五首 其二","f":"五言律诗","c":["挂粟枯桑杪，篱门昼掩关。","晴霜开旷野，寒日晒荒山。","指点村烟外，经行冢树间。","群豪故贪愎，窃发亦愚奸。"]},{"t":"同曹清父西郊纪事五首 其一","f":"五言律诗","c":["晴耕新种麦，破块满田间。","诘曲随牛路，周遭傍马山。","几人钟间气，往岁耸朝班。","黄卷今犹在，青云未易攀。"]},{"t":"回生丁亥方端叟乙酉长二岁其弟名万里庚寅少三岁用予旧韵来订兄弟之盟依韵奉答二首 其二","f":"五言律诗","c":["越州兄弟好，年与德俱高。","未觉同宗吝，宁须盖代豪。","雪炉称夜坐，花墅接春遨。","何日成三老，茶瓯瀹碧涛。"]},{"t":"回生丁亥方端叟乙酉长二岁其弟名万里庚寅少三岁用予旧韵来订兄弟之盟依韵奉答二首 其一","f":"五言律诗","c":["闻说庚寅弟，兼思乙酉兄。","楼高江树远，帆去暮潮平。","药岂能延寿，符焉可避兵。","各凭心事好，共保岁寒盟。"]},{"t":"回愚","f":"五言律诗","c":["人云回也乐，愚亦定何如。","瘠产今无几，荒园尚有馀。","离骚香草木，尔雅古虫鱼。","名数谁能记，年来懒著书。"]},{"t":"守孙满岁","f":"七言律诗","c":["升沉荣瘁可须论，古镜当空了不昏。","莫笑今踰六旬叟，颇欣已有两男孙。","特牲与子羞家庙，联骑何人叩圃门。","急扫秋亭具殽果，凉边烂漫倒清樽。"]},{"t":"岁尽即事三首 其三","f":"七言律诗","c":["干戈汹涌一年间，酒债何时可尽还。","盗起屡煽邻县火，军兴全赭近城山。","天阴体倦金疮痛，岁俭家寒藿食艰。","最苦梅开厌求索，柴扉草舍不容关。"]},{"t":"岁尽即事三首 其二","f":"七言律诗","c":["七里滩西更上滩，十年生事一渔竿。","故人共骇霜毛短，俗子犹嫌铁面寒。","雪屋五更天地独，梅诗一句古今难。","虚名浪得真何用，空使先生刻肺肝。"]},{"t":"岁尽即事三首 其一","f":"七言律诗","c":["閒门空宇日萧萧，天地无情鬓转凋。","政使面颜成菜色，未应官职爱冰条。","藏山竹简光阴短，寄陇梅枝信息遥。","不寐夜窗听风雪，枯肠殊欠一樽浇。"]},{"t":"岁除","f":"七言律诗","c":["亲情邻里喜归来，依旧柴门僻处开。","纵是桃符无可笔，未妨菜饼亦堪杯。","著宽毛褐观残雪，洗古铜壶浸老梅。","贺客明朝有诗客，踏青同与眺春台。"]},{"t":"岁除日陈正之刘彦质来奕","f":"七言律诗","c":["明朝六十遂平头，岂料耆年尚百忧。","远忆儿孙兼婢仆，欠赍裹饵与衣裘。","倩人赊酒聊堪醉，看客枰棋卒未休。","旅□乡心记今夕，北风吹雪满寒楼。"]},{"t":"岁除次韵全君玉有怀二首 其二","f":"七言律诗","c":["全老忽贻寒夜句，岁阑吾党久离群。","一场噩梦三千字，百载颓龄七八分。","孰与挽前轩此士，端能殿后栋斯文。","乡傩礼失求诸野，小鬼应犹畏灶君。"]},{"t":"岁除次韵全君玉有怀二首 其一","f":"七言律诗","c":["心事天涯客海涯，自筹何止一毫差。","枕诗夜夜攲檐溜，浊酒朝朝漉井花。","元日惯曾经百窘，幼男勉为讲三加。","扬扬喝道楼前过，肥马轻裘几子华。"]},{"t":"州学遇刘元煇胡子游二首 其二","f":"七言律诗","c":["小儿今忽六旬翁，尚忆无人鬼啸风。","三岁棘闱悬造化，两时饭鼓老英雄。","致身卿相谈何易，责备春秋论亦公。","磨灭山林心不愧，岂无穷者胜于通。"]},{"t":"州学遇刘元煇胡子游二首 其一","f":"七言律诗","c":["五十年前幼学儿，读书窗下此从师。","前脩何限惊埋没，往事无踪隔乱离。","蝉挟晚风穿故阁，蜗凭宿雨蛀残碑。","谁怜昔日垂髫友，白首相逢共赋诗。"]},{"t":"异僧","f":"五言律诗","c":["荒崖传有虎，飞锡径登危。","衣槲纫枯叶，餐松嚼嫩枝。","病人求咒水，野老施庵基。","一夕缘何事，飘然失所之。"]},{"t":"戏书","f":"五言律诗","c":["春天晴更好，无奈恶情怀。","马死鞍空在，花开酒欠佳。","邻医赊药饵，侍婢典簪钗。","倚杖吟还喜，新分孔墓楷。"]},{"t":"戏书旅况","f":"七言律诗","c":["垢痒频搔虱欠烘，泥行草宿叹匆匆。","欲纫衣苦无针线，每煮羹难得菜葱。","险恶固宜防贼盗，愚顽莫可恕奴僮。","閒人况是身为客，是事难将昔日同。"]},{"t":"戏咏老农观稻以秋字为韵 其二","f":"七言律诗","c":["久无筋力荷锄耰，坐阅千畦䆉稏秋。","又喜黄云今满眼，不知白雪已盈头。","丁宁幼稚频驱雀，约敕比邻远放牛。","及早儿孙了租税，颓龄一饱更何忧。"]},{"t":"戏咏昌化县土风二首 其二","f":"七言律诗","c":["富有大山无广川，积多冢树少炊烟。","绝奇车盘岭上石，稍阔马走平东田。","竹筐晒谷争晴日，瓦瓮淹齑及冻天。","未信苏湖万顷室，数家荞穄树头悬。"]},{"t":"戏咏昌化县土风二首 其一","f":"七言律诗","c":["阔衣男子荷薪樵，瘿颈妇人昂髻髫。","巨石塞途饶荦确，荒村扃户故萧条。","水风骚屑雨非雨，溪涧复重桥复桥。","授粲割鲜何敢望，尚无漓酒与侬浇。"]},{"t":"早大雾午大风寇销兵解之象","f":"五言律诗","c":["骤合公超雾，俄飞禦寇风。","大声千里动，阴翳一时空。","远睇烽楼外，愁吟战鼓中。","所思何日见，还得一樽同。"]},{"t":"早见桃花","f":"五言律诗","c":["离家四五程，所至尽堪惊。","未许盗皆息，焉能军不行。","人移山里住，春废道傍耕。","破屋知谁主，桃花照眼明。"]},{"t":"早风未顺喜晴","f":"七言律诗","c":["数星犹自耿寒空，海气弥天晓日红。","没胫已无当路雪，打头不过暂时风。","乡情客思鸿飞外，春色晴光鹊语中。","临酒对花犹健在，谁云矍铄一衰翁。"]},{"t":"早过牛头岭","f":"五言律诗","c":["吾行十馀里，未有一人行。","不见炊烟起，唯闻野水鸣。","日轮山罅出，露点草头明。","处处防豺虎，田家晏始耕。"]},{"t":"早起","f":"五言律诗","c":["窗曙书灯暗，閒居免报衙。","争鸣百舌鸟，各占一枝花。","寝内儿犹睡，厨中物未赊。","露寒衫袖湿，倚遍石栏斜。"]},{"t":"早起","f":"七言律诗","c":["万事峥嵘入夜思，稍欣无病且无饥。","山田望稔秋收近，暑月乘凉早起宜。","暗撚须髯惊露湿，倦爬疥癣喜风吹。","买薪汲水营蔬茹，草草盘餐了一炊。"]},{"t":"早起","f":"七言律诗","c":["调和风雨顺星辰，幸是人间自有人。","老赖独眠无疾病，閒能早起更精神。","胸中羲后先天易，物外无怀太古民。","颇怪吾庐旧山色，不随时世与俱新。"]},{"t":"有感","f":"七言律诗","c":["玩透羲爻未画前，今时天即古时天。","回空其庶亦其庶，轲死不传焉不传。","积愤淫伤诗未削，暗筹微婉史谁编。","继周百世民彝在，岂为兴亡有变迁。"]},{"t":"有感三首 其三","f":"七言律诗","c":["今沿古溯醉眉攒，堪转舆旋老眼寒。","昼静倚楹常独立，夜深抚几忽长叹。","关张运去金刀绝，王谢声沉玉树残。","欲淬笔锋刳鬼胆，生冤死恨海漫漫。"]},{"t":"有感三首 其二","f":"七言律诗","c":["十年归把钓鱼竿，万变惟凭冷眼看。","白发相寻点鬼簿，紫金焉得返魂丹。","渐惊老旧遗民尽，欲问承平往事难。","秋日未须畏残暑，浙江潮退即天寒。"]},{"t":"有感三首 其一","f":"七言律诗","c":["仓皇得郡免朝辞，十六年间老转痴。","一角未堪峨獬豸，二螯敢笑食蟛蜞。","刊摩干宝搜神记，啸咏陶潜责子诗。","格是世人无识者，可能更索树神知。"]},{"t":"朱用和用予南山旧韵次韵谢并呈罗弘道","f":"七言律诗","c":["妙论剧谈逢大敌，深林荫樾尾清游。","柳州先记知非偶，陆相荒庄愧不秋。","似舅远寻昆弟好，老生猥与介宾谋。","凄其廿载龙门梦，垫角曾登李尹舟。"]},{"t":"次张鹏飞解官旧韵","f":"七言律诗","c":["聚敛臣应愧直臣，暂閒身似胜官身。","险夷异路良难测，进退忘怀直任真。","万国山河封域广，九天日月照临新。","乌台凤沼登耆旧，屈指如公几正人。"]},{"t":"次前韵谢袁提学及其弟府判二首 其一","f":"五言律诗","c":["公家贤伯仲，似是晋机云。","黄卷丁年共，青灯午夜分。","望风初魄动，饮德更心醺。","自合登台省，官犹类广文。"]},{"t":"次前韵赋隐居二首 其二","f":"七言律诗","c":["举世纷如自泊如，荒园僻巷闭门居。","总干和鼎非吾事，啖茹燃萁不愿馀。","林下一声蝉噪处，山间十日雨晴初。","空阶剩放苔痕长，始信先生屐齿疏。"]},{"t":"次前韵赋隐居二首 其一","f":"七言律诗","c":["昆冈玉火脱焚如，万事灰心此定居。","今古真成一梦耳，行藏略算十年馀。","曾微实誉歌来暮，岂可虚言赋遂初。","邂逅乘车还戴笠，未妨多病故人疏。"]},{"t":"次韵九月十七日饮陆君用见山堂","f":"七言律诗","c":["凤凰山下隐君庐，水竹宽閒十亩馀。","稚子已能题砌叶，饮徒时许共畦蔬。","杜同谷怨长镵柄，马伏波思下泽车。","何似此公一丘壑，潸心逸兴酉阳书。"]},{"t":"次韵仁近九日予病不出","f":"七言律诗","c":["炎凉飘忽叹如流，久客仍逢岁不秋。","高处未应堪著眼，闷中惟可独搔头。","市酤太恶难沾醉，晴色良佳竟倦游。","戏马龙山总灰灭，儿曹焉悟此身浮。"]},{"t":"次韵仁近见和怀归五首 其五","f":"七言律诗","c":["端能何地脱尘寰，万壑松风梦寐间。","无限三槐仍九棘，孰知东国与西山。","声名赫奕终非福，滋味悠长莫若閒。","马足车轮不到处，陶门惟有昼常关。"]},{"t":"次韵仁近见和怀归五首 其四","f":"七言律诗","c":["万险千艰历历更，是非他日仗谁明。","著书何用心徒苦，攲枕无眠耳自鸣。","劫火不虞逃厄运，浮沤亦复任残生。","说与稗官应末减，堂厨初未识鱼羹。"]},{"t":"次韵仁近见和怀归五首 其三","f":"七言律诗","c":["日短晴窗顷刻阴，乾坤万虑入孤斟。","故交剩见车逢笠，初学谁羞屋画金。","菱镜岂堪朝幌觑，茗炉聊伴夜瓶吟。","生平不倚心如铁，似觉难禁世故侵。"]},{"t":"次韵仁近见和怀归五首 其二","f":"七言律诗","c":["轮蹄追想禁街驰，尚有君平卖卜帷。","遁世久忘三接卦，怀人空赋八哀诗。","敛华就实嗟何及，悟往知来尚可为。","归去井梧应好在，白头江令自堪悲。"]},{"t":"次韵仁近见和怀归五首 其一","f":"七言律诗","c":["诸公合沓据天津，往事微茫问汉滨。","老病腐儒无可意，雪霜死草有重春。","散花不复来天女，中酒焉能致圣人。","谁且生尘赋罗袜，吾家已恐甑生尘。"]},{"t":"次韵仁近客兴二首 其二","f":"七言律诗","c":["华年君欲隐山村，如我弥当杜筚门。","落落筋骸馀老病，奄奄气息仅生存。","黄精满谷春苗嫩，丹卝藏山石溜温。","足可无求度残岁，自编诗集教儿孙。"]},{"t":"次韵仁近客兴二首 其一","f":"七言律诗","c":["阅世纷如起灭沤，可须金羽较沈浮。","自知人老宜坚坐，更为春寒倦薄游。","羌蹇尚能哦楚些，仪邻不复梦唐楼。","载书归老黄山下，待唤溪翁赁半舟。"]},{"t":"次韵仇仁近见赠","f":"七言律诗","c":["霜削风朘缊絮轻，忍能吊古上颓城。","穷途我辈俱相似，老态今年转可惊。","差喜有儿胜伯道，故知无婢效康成。","紫阳溪上馀茅屋，终与沙鸥不负盟。"]},{"t":"次韵仇仁近用韵见示五首 其五","f":"七言律诗","c":["褒衣全觉近人轻，击柝鸣鼙满万城。","士气欲如枯草死，文声未见蛰雷惊。","绛侯岂识长沙傅，秦宓能非棘子成。","当复夜窗抱吟膝，百年长与一灯盟。"]},{"t":"次韵仇仁近用韵见示五首 其四","f":"七言律诗","c":["治任犹近旦中觿，旅次今移日至圭。","恶况味逢佳节序，懒情怀怯好诗题。","向来守黑元知白，几辈平东复镇西。","定是仇仙知此意，卜邻端欲共花溪。"]},{"t":"次韵仇仁近用韵见示五首 其三","f":"七言律诗","c":["久已休官卧紫阳，故园稍复葺荒凉。","虽无厦屋千间广，尚有书檠二尺长。","清赏五更花过雨，珍烹十月菜经霜。","客游漫惹兴亡恨，早觉归心晓夜忙。"]},{"t":"次韵仇仁近用韵见示五首 其二","f":"七言律诗","c":["眼过登伽皱面羞，湖山信美为谁留。","开通不办多王老，下泽唯思侣少游。","行役自量非得已，食贫能忍复焉求。","馀生至此当知命，壮事虚抛更老谋。"]},{"t":"次韵仇仁近用韵见示五首 其一","f":"七言律诗","c":["时惊驿走听庭宣，老朽于予孰使年。","鸣玉久忘綪结佩，穿花空忆锦连钱。","愧非今代王摩诘，许识能诗孟浩然。","野服幅巾亦堪画，丹青何必上凌烟。"]},{"t":"次韵仇仁近有怀见寄十首 其十","f":"七言律诗","c":["相从汩没走泥涂，忽又还家半载馀。","把盏何由尝我酒，典钱犹忆借君书。","儿孙十辈娱诗老，梅竹千株护野庐。","东望怀人屡搔首，能来相访定何如。"]},{"t":"次韵仇仁近有怀见寄十首 其九","f":"七言律诗","c":["犹喜看书懒作诗，暮年自合省云为。","预知阴雨骨骸痛，怯上好山筋力罢。","不寐有时忘数息，无疑焉用扣归奇。","寄声为报仇香道，近日交朋独尔思。"]},{"t":"次韵仇仁近有怀见寄十首 其八","f":"七言律诗","c":["守雌甘似不鸣将，静看无庸手脚忙。","沮溺故难同孔子，绮园何独避高皇。","星移斗转光阴疾，林密山深气味长。","万事灰心如嚼蜡，唯馀杯酒未相忘。"]},{"t":"次韵仇仁近有怀见寄十首 其七","f":"七言律诗","c":["汉廷簪绂簉金张，初服逡巡返士乡。","勇退能为疏傅去，过刚似胜次公狂。","庭梧陨叶元非死，秋燕辞巢不待凉。","玩物察时远灾咎，不须空热九回肠。"]},{"t":"次韵仇仁近有怀见寄十首 其六","f":"七言律诗","c":["少年忽作白头人，慷慨悲歌岂为身。","屈子独醒天可问，重华久去士常贫。","瓶无储粟陶元亮，马似乘船贺季真。","此味孰能相识察，陨霜硕果有馀春。"]},{"t":"次韵仇仁近有怀见寄十首 其五","f":"七言律诗","c":["寄来诗卷了无尘，想见家贫道不贫。","真复远追前辈味，颇惊顿异去来人。","驱车荡荡行须至，破的遥遥见已亲。","换骨得仙内丹熟，可须浮海望三神。"]},{"t":"次韵仇仁近有怀见寄十首 其四","f":"七言律诗","c":["身历干戈百战尘，休官仍似布衣贫。","每看事有难行处，未见心无不愧人。","秋稔粥饘犹可继，夜凉灯火已堪亲。","闭门读《易》吾谋决，莫用蓍龟问鬼神。"]},{"t":"次韵仇仁近有怀见寄十首 其三","f":"七言律诗","c":["老玩韦编尚可为，复能吃口对期期。","离明偶剔书灯见，坎止因斟砚水知。","岂厌微尘裨泰岳，只愁残照近咸池。","儿曹未悟侯王梦，不了邯郸黍一炊。"]},{"t":"次韵仇仁近有怀见寄十首 其二","f":"七言律诗","c":["谁识虚翁此一虚，归来不叹食无鱼。","早闻曾撰异三子，近喜陶诗赋二疏。","但苦老身多疾痛，时呼医士问方书。","君知湖海元龙否，豪气年来已尽除。"]},{"t":"次韵仇仁近有怀见寄十首 其一","f":"七言律诗","c":["我能纳禄君辞聘，大觉蓑衣胜衮衣。","有径弗行缘畏险，无形可见要研几。","就令枵腹常亡赖，尽胜枯骸永不归。","何限戟门委荒草，高堂犹记旧巍巍。"]},{"t":"次韵仇仁近至日","f":"七言律诗","c":["浪说春回地底阳，驼裘正怯北风凉。","未来事甚云难测，已老身无日再长。","紫逻招魂千里雪，彤庭待漏五更霜。","閒人幸脱拘挛外，客枕何庸早起忙。"]},{"t":"次韵仇仁近梅雨","f":"七言律诗","c":["客心何日渡桑乾，琐琐良难雨更难。","途潦家家踰户限，檐声夜夜过更阑。","归舟屡阻千滩涨，暑簟频惊五月寒。","会许灯花报晴信，书帷新照玉虫丹。"]},{"t":"次韵仇仁近晴窗二首 其二","f":"七言律诗","c":["往时淟涊玷蕃宣，处士名闻积有年。","甚欲同倾彭泽酒，未能略送始兴钱。","细看好句无疵处，时出名言亦自然。","苦海爱河争没溺，禅窗一榻篆茶烟。"]},{"t":"次韵仇仁近晴窗二首 其一","f":"七言律诗","c":["涧毛足可继晨羞，窗暗窗明日去留。","古道海深磐石坠，时情风缓暖丝游。","天渊有间终何恨，人我相违各不求。","四顾茫然欲焉往，一寒端为效忠谋。"]},{"t":"次韵仇仁近谢诗跋","f":"七言律诗","c":["羁角朋从饰帨觿，成人可更戏桐圭。","万钧致力终能举，一字争工未易题。","鲁颂向来睎考父，雩风元自异公西。","长江破浪输君手，肯学村船逆上溪。"]},{"t":"次韵元煇中秋雨","f":"七言律诗","c":["良辰合与一樽酬，有酒无朋也自愁。","万事只堪花老眼，一年又过雨中秋。","鸣砧处处凄邻巷，击柝相望起戍楼。","更著乱蛩环独榻，平生天地付神游。"]},{"t":"次韵元煇昨游","f":"七言律诗","c":["藕花茭叶忽明眼，此地聊乘解愠风。","无酒尚堪翻作有，苍颜终不变为红。","虚声浪漫盈天下，急景奔腾过日中。","万事可容著心力，迩来诗句亦匆匆。"]},{"t":"次韵仇仁近暑中二首 其二","f":"七言律诗","c":["瞬息凉炎代谢频，沉冥自养静中身。","读书快意如抓痒，得句言怀当写真。","幸不与闻当世事，可须常作半途人。","忽思秦汉干戈际，商岭犹堪避战尘。"]},{"t":"次韵仇仁近暑中二首 其一","f":"七言律诗","c":["初减官河几许深，向来惟恐百城沈。","晴阶近喜收檐滴，暑屋殊嫌乏树阴。","妾妇齿牙工斗阋，比邻疟疠厌呻吟。","悬知壮士无颜色，赖有同心可断金。"]},{"t":"次韵文蔚约梅上人来访","f":"七言律诗","c":["惭非好客郑当时，猥荷高人不见遗。","顿悟可能参佛理，淡交谁是喜僧诗。","过从未许泥行数，属和多因险韵迟。","彼此缄縢各收拾，他年开卷两相知。"]},{"t":"次韵方去言用予喜归韵见寄三首 其三","f":"七言律诗","c":["野鸟呼风金粟堆，曲江宫殿委荒苔。","是非谁办笔褒贬，鸿燕屡惊春去来。","偃月人今奸骨朽，浣花翁未醉眉开。","吟君诗罢登山崦，立尽斜阳尚懒回。"]},{"t":"次韵方去言用予喜归韵见寄三首 其二","f":"七言律诗","c":["笔法君追宝晋斋，禅机我愧老蒲鞋。","尝僚台阃相知旧，得友江山到处佳。","铁马尘高频极目，锦鳞音断岂忘怀。","亦思竹底陪溪逸，人品终疑未易侪。"]},{"t":"次韵方去言用予喜归韵见寄三首 其一","f":"七言律诗","c":["秋高亲见老崖来，险阻嵚崎付一杯。","万古悬知名不夜，九泉谁免骨为灰。","轻鸥熟与风波狎，劲柏宁资粪壤栽。","却笑诸儿浪生死，大都暮落枉朝开。"]},{"t":"次韵王君偕子同来访","f":"七言律诗","c":["愧子初来坞路赊，曾微酒旨与殽嘉。","答诗辄便拈枯笔，接话才能供淡茶。","膝上佳儿如玉雪，山中春事几风花。","良畴世世勤菑播，终待明时遇宅家。"]},{"t":"次韵王俊甫山长九日登乌聊二首 其二","f":"七言律诗","c":["江边危阜俯江皋，去马来牛细若毛。","古道向来元寂寂，俗流何处不滔滔。","漫拈老笔雕空阔，径命芳樽洗郁陶。","天地年年有摇落，悲秋端谢楚人骚。"]},{"t":"次韵王俊甫山长九日登乌聊二首 其一","f":"七言律诗","c":["山色初明小雨开，可容无地拓襟怀。","荒寒试与登临去，奇崛能随感慨来。","何限诗愁关世故，终凭烂醉了生涯。","风流二谢犹堪恨，俯首刘郎戏马台。"]},{"t":"次韵邓善之书怀七首 其七","f":"五言律诗","c":["昭谏先生宅，咸平处士庐。","大名无死朽，外物几乘除。","岁月勤稽古，山林永遂初。","能诗直馀事，焉不蔺相如。"]},{"t":"次韵邓善之书怀七首 其六","f":"五言律诗","c":["以逊而绵者，居然古性情。","温恭瞻道貌，响浪听心声。","施药痊诸病，留田与后耕。","日予拜嘉惠，欲报乏连城。"]},{"t":"次韵邓善之书怀七首 其五","f":"五言律诗","c":["子将今月旦，可否判生枯。","高论真能借，羁怀未觉孤。","竹吟风拂席，花饮月当垆。","甚愿陪游屐，唯惭老杜殊。"]},{"t":"次韵邓善之书怀七首 其四","f":"五言律诗","c":["我听髯张作，清于月夜笳。","曹思先七子，杜老到三巴。","有力能推拉，无疵可汰沙。","文潜遗论在，霜露老蒹葭。"]},{"t":"次韵邓善之书怀七首 其三","f":"五言律诗","c":["今代邓元侯，书窗不外求。","寡言良有味，节用绝无愁。","真是温如玉，兼能爽似秋。","銮坡宜趣召，夜直结邻楼。"]},{"t":"次韵邓善之书怀七首 其二","f":"五言律诗","c":["老怀饶感慨，无一可欢娱。","久矣还初服，胡然落半途。","流年苏武雁，往事左慈鲈。","莫笑腰围减，还堪作酒壶。"]},{"t":"次韵邓善之书怀七首 其一","f":"五言律诗","c":["二十八回见，天门阖左扉。","不嫌笔端退，但骇镜中非。","自爱希声瑟，谁知尚絅衣。","人生年七十，肯复壮心飞。"]},{"t":"次韵邓善之论诗","f":"五言律诗","c":["未极皮毛落，端难颊舌传。","夔音谐柷敔，岐脉按钩弦。","举目常如见，关心或不眠。","江湖无正色，龋齿亦嫣然。"]},{"t":"次韵休宁程君圉来访","f":"七言律诗","c":["秋崖劲笔敌黄陈，贽卷当年许望尘。","十载江湖春雁断，万山烟雨石羊新。","馀生敢忘尊前话，先正曾同席上宾。","今日相逢两家子，可无努力继前人。"]},{"t":"次韵全君玉元日二首 其二","f":"五言律诗","c":["春攽诸郡国，汉守喜惟良。","旦宿重中尾，时花竞向阳。","古今新旧历，老少后先觞。","万事皆如此，无如且醉狂。"]},{"t":"次韵全君玉元日二首 其一","f":"五言律诗","c":["五更皆早起，惟我是閒人。","展镜须仍雪，添杯脸暂春。","有终还复始，无旧不成新。","万古烧痕意，陈根岂尽陈。"]},{"t":"次韵刘元煇飞雪数片之作","f":"七言律诗","c":["六幕垂同冻不埃，舞霙呼我燕窗开。","已从衣上霏微见，未肯檐前汗漫来。","就砌拾看呵指笋，隔帘迎数斗妆梅。","衰髯却怪全相似，且置閒愁拨蚁醅。"]},{"t":"次韵刘元煇元日","f":"七言律诗","c":["九十日春已十日，清晨閒步小园中。","池痕欲涨去年水，柳色渐回东畔风。","砥道歌游全似梦，专槃生化本无穷。","阴晴寒暖频占相，世事唯宜岁事丰。"]},{"t":"次韵刘元煇初寒夜坐","f":"七言律诗","c":["山肩寒耸月随归，榾柮炉红闭板扉。","跨灶郎来温课册，齐眉人为摺深衣。","花传喜信灯如语，草就佳篇字欲飞。","旧日声名刘夜坐，能传家钵似君稀。"]},{"t":"次韵刘君鼎见赠二首 其二","f":"七言律诗","c":["真复多多穷传记，端能亹亹著诗文。","名场早捷千军阵，胪陛应符五色云。","乱后湖山今稍稍，閒中宾主几醺醺。","衰迟亦欲陪赓唱，未必当筵逮所闻。"]},{"t":"次韵刘君鼎见赠二首 其一","f":"七言律诗","c":["厌闻世态已如聋，旧雨人来久绝踪。","自笑云萍无定止，不图针芥有奇逢。","侯门列鼎三牲奉，田舍巾车一鹿容。","试问吟怀欲何向，定应羞傍马医钟。"]},{"t":"次韵吕肖卿讲学三首 其三","f":"五言律诗","c":["忽复机锋对，真堪底里倾。","果能成伏老，时许唤殷兄。","可惜兹逢晚，相期不计程。","受恩凡两世，焉敢恝无情。"]},{"t":"次韵吕肖卿讲学三首 其二","f":"五言律诗","c":["玄珠在掌握，一失永难寻。","岂不求成道，谁其办苦心。","待时花结果，著力杵磨针。","何幸忘年去，能鸣治世音。"]},{"t":"次韵吕肖卿讲学三首 其一","f":"五言律诗","c":["平生但力田，岂计不逢年。","吾道桴浮海，斯文笔补天。","早能丹点铁，曾用白嘲玄。","万虑今亡矣，焚香易一编。"]},{"t":"次韵夹谷子括吴山晚眺 其三","f":"七言律诗","c":["落木萧萧泽国宽，偶舒岩啸纵川观。","六鳌海阔征帆远，万象天低步屧寒。","旅泊馀生箪食菲，宦游旧味瓮齑残。","达人不堕牛山泪，何待将心与汝安。"]},{"t":"次韵夹谷子括吴山晚眺 其一","f":"七言律诗","c":["诗眼书胸碧宙宽，暮天摇落纵遐观。","霜明枫叶红于染，春点梅梢玉不寒。","北望遥迎书雁至，南烹屡餍鲙鱼残。","一规明月悬江海，几许人家夜枕安。"]},{"t":"次韵夹谷子括吴山晚眺 其二","f":"七言律诗","c":["鹘飞欲没海天宽，万动盈虚静处观。","一画微阳迎日至，九畴休徵验时寒。","世间劫火灰何限，物外仙棋局未残。","好与苍生司性命，五风十雨报平安。"]},{"t":"次韵孙元京见过言诗 其一","f":"七言律诗","c":["骚坛争长各称兵，未卜谁欤霸业成。","欲疗左盲治谷废，合除白俗扫元轻。","屡更落落心犹壮，常恐空空气骤盈。","据险作难终未是，赖公指示轨图平。"]},{"t":"次韵孙元京见过言诗 其二","f":"七言律诗","c":["眼底惊嗟见此流，祇嫌接对未云稠。","苏门逸响追长啸，湘浦馀情续远游。","新息今须乘果下，襄阳谁漫钓槎头。","吾衰久矣公犹健，好控飞车跨九州。"]},{"t":"次韵权季玉枕上偶成","f":"七言律诗","c":["迩日屡闻亲药鼎，客怀沈郁与谁论。","细参素问心无病，勤剔青灯眼未昏。","九折政思为孝子，七襄未用乞天孙。","察君诗味如枯淡，中有无穷古意存。"]},{"t":"次韵许大初见赠二首 其二","f":"七言律诗","c":["风灯雪屋话艰难，各喜诗成咳唾间。","早幸渊骞同阙里，终当园季隐商山。","草玄执戟空投阁，枕面参军善闭关。","祇恐傍人足嘲讶，如泥烂醉不知还。"]},{"t":"次韵许大初见赠二首 其一","f":"七言律诗","c":["相逢未觉道途难，把酒论诗数夕间。","磊落胸襟开古谊，从容色笑借和颜。","长年役役鱼千里，末俗悠悠虎九关。","赖是同乡复同味，一寒如此遽春还。"]},{"t":"次韵许瑞石送邵容斋见寄","f":"七言律诗","c":["款段馀生谢伏波，咏归心事竟云何。","藕花又趁榴花发，诗债仍兼酒债多。","击壤先生黄色论，卖薪老子翠微歌。","吾侪胸次元相似，谁道金章胜钓蓑。"]},{"t":"次韵齐君见过","f":"七言律诗","c":["从容谈笑猎文场，焉用椎锋更挽强。","政使成功能裂土，未如闻道许登堂。","勇捐将印机心息，深隐书帷古味长。","我亦暮年懒干禄，肯来同醉简编香。"]},{"t":"次韵伯田见酬四首 其四","f":"七言律诗","c":["六桥久客旧湖滨，春日花开不似春。","游学顿无福建子，科名更说梓潼神。","暗惊渊实丘夷事，枉作书痴传癖人。","辛苦湘累辨兰艾，庄生齐物等埃尘。"]},{"t":"次韵伯田见酬四首 其三","f":"七言律诗","c":["半年洄溯越江滨，每愧羊裘老富春。","归隐尚能联比长，出游复肯祭行神。","枯肠近饱三爻梦，宿齿宜肩四豆人。","能顾寒斋共芳茗，蠹编时为拂蛛尘。"]},{"t":"次韵伯田见酬四首 其二","f":"七言律诗","c":["世故吾其问水滨，向来不合典班春。","一从去作沧浪客，几度重题郁垒神。","垂死岂堪思往事，忍穷方欲作閒人。","喜公强健犹如故，未有清樽可祓尘。"]},{"t":"次韵伯田见酬四首 其一","f":"七言律诗","c":["久缺笺筒到霅滨，相逢依旧气如春。","深藏尺璧元无价，时击圆蓍尚有神。","桑梓兵戈三峡路，衣冠文物五朝人。","片时略得陪清话，一扫胸中万斛尘。"]},{"t":"次韵君泽夜坐示子侄三首 其三","f":"七言律诗","c":["雨脚如麻坐到明，雨楼听尽五更声。","无人共唱寻寻觅，有子聊教仄仄平。","凌室不能藏腊冻，稼场或至误秋成。","谁知忧世书生意，惟愿天阶正玉衡。"]},{"t":"次韵君泽夜坐示子侄三首 其二","f":"七言律诗","c":["一样乾坤几样人，甑生尘异袜生尘。","寒窗黄卷青灯雨，暖阁金钗玉斝春。","谁同公子梦方魇，我与先生诗又新。","□□儿曹供笔墨，为言不是写真真。"]},{"t":"次韵君泽夜坐示子侄三首 其一","f":"七言律诗","c":["灯影稀疏两岸楼，市声已寂睡声齁。","几家梦断三更过，此老心穷八极游。","服气仙人吾不学，坐禅释子彼何求。","夜思昼读诸郎识，俯仰青春鬓忽秋。"]},{"t":"次韵张中白元日","f":"七言律诗","c":["瓣香清晓肃冠绅，户外遥山展翠颦。","瘦影自怜耽醉叟，欢声何限喜晴人。","匆匆节序梅花老，衮衮尘埃世事新。","自有天来至今日，不知芳草几番春。"]},{"t":"次韵张文焕慵庵万山堂即事二首 其二","f":"七言律诗","c":["新晴钟鼓暮楼台，人与清空两不埃。","日已顿无宣子畏，云应全为退之开。","夜凉河汉牛初渡，秋爽关山雁欲来。","好向丰年作张主，未须松鼎煮丹胎。"]},{"t":"次韵张文焕慵庵万山堂即事二首 其一","f":"七言律诗","c":["张侯诗思涌如泉，吟榻横陈翠麓巅。","十雨五风今乐国，千村万落几人烟。","赏心眺览知何算，转首音尘竟弗传。","句勒口碑天共远，不虚佳月佐觥船。"]},{"t":"次韵张仲实见赠","f":"七言律诗","c":["久縻官务费爬梳，一旦投閒得自如。","紫绶金章已高阁，青鞋布袜是安车。","漫郎心事诗能说，散圣禅流发未除。","物我重轻中了了，可能秤象待苍舒。"]},{"t":"次韵张仲实岁晚","f":"五言律诗","c":["老穷胜夭达，敢惜岁时迁。","食玉多忧死，披蓑且醉眠。","西湖非昔者，南雪尚春前。","稍足陶瓶粟，诸公不用怜。"]},{"t":"次韵张仲实读予近稿","f":"五言律诗","c":["平生穷到骨，不受世人怜。","肠倒三江洗，诗凭万口镌。","旂常无可纪，衣钵尚堪传。","今日如斯者，输君独妙年。"]},{"t":"次韵张慵庵立秋有怀","f":"七言律诗","c":["西风一叶未为稠，积雨寒添客思秋。","试以物情观燕垒，可无心事寄菟裘。","砚何堪办三钱水，竹岂能踰十稔楼。","真是先生有归兴，不应如我雪盈头。"]},{"t":"次韵张慵庵观予奕棋","f":"七言律诗","c":["与牧猪奴可不同，嗟予老矣尚心童。","戏拈玉子鸣飞雹，良喜青裾驻织葱。","浪设机关何所益，仅存边角未为雄。","小鬟有着能相恕，冷被傍人笑此翁。"]},{"t":"次韵张慵庵言别就送","f":"七言律诗","c":["屡陪幽话探玄关，虚往无何已实还。","远眺每穷千里外，佳吟时见一联间。","致身霄汉名方起，回首林泉意欲閒。","闻说姑溪卜新筑，会须容访郭青山。"]},{"t":"次韵志归十首 其十","f":"五言律诗","c":["近城一耕叟，仅有使牛能。","人似愚偏寿，家由俭故兴。","不知求仕宦，未省结交朋。","笑我儒冠误，今如退院僧。"]},{"t":"次韵志归十首 其九","f":"五言律诗","c":["书盍多多读，诗须细细评。","后生才染指，半道遽寒盟。","直取珊瑚出，宁争熠耀明。","伯牙弦已绝，举世喜筝声。"]},{"t":"次韵志归十首 其八","f":"五言律诗","c":["谯国资深入，彭门纳晚成。","至今为癖习，自幼有常程。","朽老宁孤瘦，飞扬勿剽轻。","悬知千载士，肯竞一时名。"]},{"t":"次韵志归十首 其七","f":"五言律诗","c":["楸局堪谁对，铜壶拟共投。","高轩能坐致，浊酒岂难谋。","林鸟供歌吹，园蔬当馔羞。","谓无忧不可，聊以此消忧。"]},{"t":"次韵志归十首 其六","f":"五言律诗","c":["解语莺能巧，交飞蝶许狂。","苔纹深碧毯，榴靥竞红妆。","粗已成幽圃，犹当筑小堂。","未妨无暑药，熟水紫苏香。"]},{"t":"次韵志归十首 其五","f":"五言律诗","c":["添竹复添花，清阴一倍加。","病身思灼艾，暑节近浮瓜。","晚景今如许，初心岂有他。","甘贫仍守拙，肯羡五侯家。"]},{"t":"次韵志归十首 其四","f":"五言律诗","c":["还家五月初，倏忽又旬馀。","凉剂医羸马，尘编磔蠹鱼。","小迟延客饮，作急报儿书。","歙睦频来往，何时永定居。"]},{"t":"次韵志归十首 其三","f":"五言律诗","c":["痴与狂皆有，贫兼病亦应。","屡尝三斗醋，不梦一条冰。","买药凭船贾，分茶谢冢僧。","短衣射猛虎，老矣竟无能。"]},{"t":"次韵志归十首 其二","f":"五言律诗","c":["老不任时栋，穷犹宅士乡。","端能甘澹泊，未觉厌荒凉。","古井深泉冷，閒庭异草香。","田翁来问字，略为说偏傍。"]},{"t":"次韵志归十首 其一","f":"五言律诗","c":["远望舒长啸，幽跧发永叹。","能诗今不少，得句古云难。","涉世颠毛白，希贤寸腑丹。","他乡仍故国，何处可求安。"]},{"t":"次韵李景安提学同过伯几 其一","f":"七言律诗","c":["万卷芸香拥燕居，客来谈论汹淮湖。","精言琴律根前辈，朗诵诗篇压老夫。","胥谓买邻迁爽垲，祇应负郭欠膏腴。","真能隐处非难事，恐有天边尺一呼。"]},{"t":"次韵汪以南归途见寄","f":"七言律诗","c":["身轻更觉马蹄轻，倦听昕堂讲鼓声。","示病早能效摩诘，赋归真复继渊明。","食租近郭膏腴足，卜筑依山爽垲成。","疾寄新诗似怜我，弃田捐宅不聊生。"]},{"t":"次韵汪以南教授美康使君新政因及贱迹四首 其四","f":"七言律诗","c":["石壁峰前旧泮林，新培槐市绿成阴。","川流决溃终归海，木德回环会守心。","夷轨得朋殊未艾，长谣怀感抑何深。","矧伊色笑逢民则，好续当年蹻蹻吟。"]},{"t":"次韵汪以南教授美康使君新政因及贱迹四首 其三","f":"七言律诗","c":["汉廷久已推三杰，鲁国终难致两生。","云雨蛟龙真有势，风霜草木易无情。","小迟玉玺徵黄霸，定许青门老邵平。","勇据皋比作歌颂，依稀駉駜似难赓。"]},{"t":"次韵汪以南教授美康使君新政因及贱迹四首 其二","f":"七言律诗","c":["溃蚁狂澜拔地来，日多事变少人才。","鼎钟古篆盲谁识，布素轻缣拙易裁。","夷甫风流空自命，子山词赋有馀哀。","邦侯博雅难酬对，且向筵前覆酒杯。"]},{"t":"次韵汪以南教授美康使君新政因及贱迹四首 其一","f":"七言律诗","c":["吾州今岁得儒臣，坐镇浮浇力万钧。","月榭风台寻古迹，烟畦雨陇劳遗民。","长庚往往诗无敌，子美云云笔有神。","老懒未遑致三请，低回祇欲老垂纶。"]},{"t":"次韵汪庭芝投赠","f":"七言律诗","c":["鱼龙仙派古来闻，南渡枢臣七世孙。","幸不幸间身且隐，玄之玄处道常尊。","惜閒剩读真书传，入静时思旧户门。","送往恤孤尚留意，亦防公议恐无恩。"]},{"t":"次韵汪翔甫和西城吕全州见过四首 其四","f":"五言律诗","c":["骤见累侯印，遄闻趣相装。","相期终古事，未用暂时香。","清论玉霏麈，高眠雷撼床。","前鱼又堪笑，红袖泣龙阳。"]},{"t":"次韵汪翔甫和西城吕全州见过四首 其三","f":"五言律诗","c":["五鼎封君食，千金奉使装。","傥来皆外物，不朽有真香。","满酌圣贤酒，虚争上下床。","细思诸葛事，只合卧南阳。"]},{"t":"次韵汪翔甫和西城吕全州见过四首 其二","f":"五言律诗","c":["闻道过从地，衣冠异俗装。","小孙迎劝酒，后院出行香。","贾客珠量斗，侯家笏满床。","未如耆旧辈，庞马隐襄阳。"]},{"t":"次韵汪翔甫和西城吕全州见过四首 其一","f":"五言律诗","c":["想见花间路，篮舁草草装。","叩门驯犬喜，入室蠹鱼香。","蹑石苔粘屐，眠松露滴床。","焉知人世事，积甲又宜阳。"]},{"t":"次韵汪翔甫读予诗稿见寄二首 其二","f":"五言律诗","c":["十年兵甲梦，投老卸戎装。","有药医诗病，无花恼梦香。","书明萤度几，簟冷竹遮床。","属与公携酒，蹉跎换岁阳。"]},{"t":"次韵汪翔甫读予诗稿见寄二首 其一","f":"五言律诗","c":["我诗蒯侯剑，玉具谢华装。","老矣三荒径，悠哉一瓣香。","漫垂船子钓，懒下赵州床。","忽忆高轩过，仙巾戴华阳。"]},{"t":"次韵沈茂实小园偶书 其一","f":"七言律诗","c":["人因雅俗分高下，同是园林兴不同。","时觉燕莺相尔汝，焉知蜂蝶有雌雄。","岂惟酒可兼诗可，常在花中与竹中。","秋老纱窗犹未换，要令深夜月华通。"]},{"t":"次韵沈茂实小园偶书 其二","f":"七言律诗","c":["秋风粳稻又尝新，续食年年肯济贫。","远学佺期响□□，近同东老致仙人。","贵公勋业一杯水，俗子面颜三斛尘。","流火授衣诵豳什，戒寒深恐雁来宾。"]},{"t":"次韵灵鹫清长老二首 其二","f":"楚辞体","c":["得句无僧字不清，公来一日两诗成。","龙雷珠浦东坡和，海日江潮老宋惊。","鲁直尚能推大国，长卿谁可诧长城。","二桃三士抱吟膝，我所师兮葛孔明。"]},{"t":"次韵灵鹫清长老二首 其一","f":"七言律诗","c":["粗读书难尽信书，世谁鲠直但阿谀。","平生湖海悲游子，晚岁乾坤老腐儒。","知己尚堪抬醉眼，从僧似欲剃吟须。","何当灵鹫兼三竺，日伴猿饥侣鹤臞。"]},{"t":"次韵连伯正见赠","f":"七言律诗","c":["古调于今底所寻，麟胶忽嗣绝弦音。","骤观布置如平易，徐认萦回极杳深。","露下九皋秋鹤唳，月寒三峡夜猿吟。","宁为清绝更凄楚，肯弄文君户外琴。"]},{"t":"次韵邵君以容名斋二首 其二","f":"七言律诗","c":["我能容物天容我，容足元消地几多。","结莫逆交聊尔汝，闻无义语勿谁何。","飘零踪迹因循惯，冷淡光阴苟且过。","人世政如蚕食叶，百年谁办茧成窝。"]},{"t":"次韵邵君以容名斋二首 其一","f":"七言律诗","c":["细读来诗窥所学，忘机忍事用功深。","远同随笔洪公号，妙得吟窝邵子心。","怀抱春浓重酝酒，语言渊嘿绝弦琴。","我能容物天容我，无是无非镇似今。"]},{"t":"次韵受益九日","f":"七言律诗","c":["归欤岂少旧林塘，何用痡瘏陟彼冈。","白发转添吾辈老，黄花不减去年香。","每嫌佳节多风雨，犹喜炎陬缓雪霜。","典尽寒衣偿酒债，衰翁聊以醉为乡。"]},{"t":"次韵受益苦雨二首 其二","f":"五言律诗","c":["甘泽关民命，随时不在多。","滴穿檐下石，烂倒水中荷。","天有凶荒岁，人无政事科。","诚心能抚字，乖气转为和。"]},{"t":"次韵受益苦雨二首 其一","f":"五言律诗","c":["乃者黄梅近，朝朝以雨书。","将无作人鲊，孰不困河鱼。","近郡淹城郭，连村浸室庐。","何当与奇术，辟谷驾飞车。"]},{"t":"次韵受益喜晴二首 其二","f":"五言律诗","c":["高楼晓气清，钟鼓报新晴。","乍睹阳乌色，频闻喜鹊声。","纵难期上熟，差足慰深耕。","忍见民穷极，唯宜岁事成。"]},{"t":"次韵受益喜晴二首 其一","f":"五言律诗","c":["谁扶一轮日，与扫万重云。","水已落数尺，田犹收几分。","大钧回叶气，疏网削深文。","尔饭堪糊口，忍为梁上君。"]},{"t":"次韵金汉臣五城道中","f":"七言律诗","c":["郊行胸次爽于秋，岁稔天宽百姓忧。","但有樵人歌陇上，永无廷尉望山头。","最宜旷野开诗思，未觉他乡动客愁。","想见霜林疏更好，绿阴时节忆曾游。"]},{"t":"次韵金汉臣雨后病起见寄","f":"七言律诗","c":["一自蒲杯吊楚湘，倏成炎溽乍阴凉。","恨无枥上如飞马，往问斋中独宿床。","病起精神如雨止，怀归愁思与天长。","何时共□□诗说，直上高峰看夕阳。"]},{"t":"次韵金汉臣喜雨","f":"五言律诗","c":["山高田易旱，已过一旬晴。","岂止商饥饱，真成决死生。","甘霖三尺透，病体十分轻。","想见琴堂老，催诗意倍清。"]},{"t":"次韵金汉臣喜晴","f":"七言律诗","c":["雨足秧畴始放晴，乡邻所至有欢声。","宰公明察无冤狱，太守辛勤自劝耕。","我昔黄童成白首，谁今赤子视苍生。","定知米价秋来减，遍买村醪处处行。"]},{"t":"次韵俞好问庆予七十","f":"七言律诗","c":["固穷早类从心孔，懒读今如便腹边。","时制堪惊小戴记，初筵敢拟卫公篇。","云何此老偏令寿，其或斯文遂有传。","见一庵前碧溪在，花瓢归饮许仙泉。"]},{"t":"次韵俞如问旅思送之游松江","f":"七言律诗","c":["芰制荷纫未絮衣，溪船信宿自堪归。","倚门尚尔嗟行役，抱瓮元来久息机。","江阔天遥鸿雁断，日斜岁暮稻粱稀。","芋炉有地煨风雪，骨肉团栾夜共围。"]},{"t":"次韵前广德赵教授","f":"七言律诗","c":["脩程万里未为赊，年少曾逢世运嘉。","早擢高科题雁塔，合班迩列餍龙茶。","宦情划似云归岫，时事惊如雨送花。","书林宝藏饶词藻，肯羡青霄富贵家。"]},{"t":"次韵前住中竺希鉴上人五言","f":"五言律诗","c":["中兴今佛法，百倍胜儒绅。","达磨重初祖，观音再化身。","此心元是道，何物不为尘。","毂觫齐王眼，焉知一角麟。"]},{"t":"次韵胡正卿","f":"七言律诗","c":["长途疾足讵容休，政是嘶风抹电秋。","小复低回从吏隐，未应拘窘叹官囚。","声名甫逐涛江起，魂梦空随沁水流。","一顾即看逢伯乐，直须昼绣问刀头。"]},{"t":"次韵赵云中饮呈孟君复二首 其二","f":"七言律诗","c":["可遨昆阆步瀛莱，祇爱钻腮笑靥开。","暮雨朝云元易散，昏钟晓鼓故相催。","身如病鹤犹遗骨，心似焦桐亦未灰。","纵使吾曹不排闼，不应门阈上苍苔。"]},{"t":"次韵赵云中饮呈孟君复二首 其一","f":"七言律诗","c":["旧业田荒百顷莱，眉头长与醉怀开。","春愁忍共金钗诀，夜禁偏嫌玉漏催。","聚散有情都是梦，古今无物不成灰。","何时再觅狭邪路，白骨谁非塌井苔。"]},{"t":"次韵赵朴翁赴衍圣公峄山书院之招","f":"七言律诗","c":["邹鲁相望击柝间，亦颜谁许独晞颜。","同源泗水别沂水，接壤峄山连泰山。","万世元勋辟杨墨，一时浮论主雍环。","七篇事业君能讲，男子临岐泪肯潸。"]},{"t":"次韵赵达夫问疾","f":"七言律诗","c":["烦君遣信问何如，霖雨无人叩陋居。","孰信着绵当夏半，自惊伏枕已旬馀。","百年未办书传后，一壑犹欣服返初。","处约得衰更多病，从今誓与酒杯疏。"]},{"t":"次韵送张文焕 其一","f":"七言律诗","c":["廊庙端非岩壑姿，慵庵未是可慵时。","浮荣故自无心向，素抱其如有己知。","天上要途终一武，江南绝景已千诗。","欲从远祖赤松子，小待功成亦未迟。"]},{"t":"次韵送郝同知还闽二首 其二","f":"七言律诗","c":["字画多年逼献之，高材天赋岂人为。","一枝秃笔无能敌，百尺名楼有所思。","碛马塞鸿忘旧梦，建茶闽荔富新诗。","皇天具眼终徼福，多病从来喜让夷。"]},{"t":"次韵送郝同知还闽二首 其一","f":"七言律诗","c":["平生奔走遍区中，老尚流离作寓公。","合坐黄堂称太守，愿求丹剂学仙翁。","繄谁虎豹占文变，何限貂蝉出武功。","可似有心随李耳，流沙西迈过崆峒。"]},{"t":"次韵郝元隐浙西山","f":"七言律诗","c":["疏处温凉密处寒，未须向背问支干。","猿闲配偶双嬉戏，树古根枝万屈盘。","何限楼台荒宿草，几年歌舞罢鸣銮。","赖天独肯扶僧刹，佛大泥多许共看。"]},{"t":"次韵唐师善见寄 其一","f":"七言律诗","c":["闻风足使鄙夫宽，家世言诗自杏坛。","万卷古书侔藏室，十年深谷隐王官。","大材益厚楩楠植，至宝终垂琬琰刊。","愧我老衰已无力，青云中道铩飞翰。"]},{"t":"次韵唐师善见寄 其二","f":"七言律诗","c":["归来数亩小园宽，风有轩棂月有坛。","总为才疏能忤俗，兼缘兴尽合休官。","空山老死知无补，往代兴亡稍欲刊。","洛下寄书藉黄犬，莼鲈终恐愧张翰。"]},{"t":"次韵宾旸令郎见示二首 其二","f":"五言律诗","c":["老我泥涂久，郎君玉雪清。","百年双鬓谢，一醉万缘轻。","孰肯延枚叟，端难少贾生。","脩程未可料，聊此慰诗情。"]},{"t":"次韵宾旸令郎见示二首 其一","f":"七言律诗","c":["盛名从昔起寒微，逆旅萧条未必非。","政可夜楼观月落，不应晓枕叹霜飞。","妙年振鬣思千里，他日干霄会百围。","通介随时有中道，稍容衰老擅渔矶。"]},{"t":"次韵宾旸斋中独坐五首 其五","f":"七言律诗","c":["惯忍饥穷即圣贤，松心玉质未贞坚。","苦无知己庸何憾，断不逢人便乞怜。","龟鹤算高终老死，星辰位定有推迁。","味公独坐诗中意，可惜侵寻绛县年。"]},{"t":"次韵宾旸斋中独坐五首 其四","f":"七言律诗","c":["谁欤载笔掌丝纶，雾雨何伤隐豹文。","绝望都俞参稷契，劣能损益记周殷。","蠹残书册犹堪觑，草没阶除尽不耘。","郑老襟期少陵解，从渠衮衮更纷纷。"]},{"t":"次韵宾旸斋中独坐五首 其三","f":"七言律诗","c":["蚁溃金堤薄俗颓，圣门谁与嗣云来。","良难托讽追风雅，只可微辞纪定哀。","有志向能穿虎石，无疑今始悟蛇杯。","掀天气燄吾尝见，转首空成一聚埃。"]},{"t":"次韵宾旸斋中独坐五首 其一","f":"七言律诗","c":["舞燕歌莺子所无，不无灯照短檠书。","酒来形影相酬酢，诗就烟霞共卷舒。","八极渺茫供傲睨，一襟空洞极恢疏。","世间底是英雄物，未许曹瞒笑本初。"]},{"t":"次韵宾旸啼字犹字二首 其二","f":"楚辞体","c":["往年灯火醉樊楼，月落吹箫未肯休。","不惜黄金追胜事，肯回青眼顾时流。","燕来鸿去春光在，死易生难病脉浮。","更问西池赏花约，心虽欲往豫兮犹。"]},{"t":"次韵宾旸啼字犹字二首 其一","f":"七言律诗","c":["醉眼看东误作西，衣缁巾醭屦拖泥。","身无却少心徒壮，花自重开草更萋。","信马旧痕今已灭，干虹老气似宜低。","楼中是日喧呼甚，闻说邻儿亦止啼。"]},{"t":"次韵徐子英江楼二首 其二","f":"七言律诗","c":["娱老曾微燕子楼，谋生又欠木奴洲。","不无造物司行止，岂与齐民系戚休。","幸际乾龙亨庶物，故希晋马锡康侯。","妙龄今日如公等，声气方当叶应求。"]},{"t":"次韵徐子英江楼二首 其一","f":"七言律诗","c":["虚器浮名蜃结楼，潮痕才落水添舟。","医工药不关生死，詹尹蓍宁究咎休。","华盖天临批凤诰，长杨日侍射熊侯。","是人有命皆能致，终许难凭智力求。"]}]};